LESSONS.push(
  {"id": "g9-social-1-u1-1", "grade": "g9", "subject": "social", "term": 1, "unit": 1, "no": 1, "title": "البيانات السكانية ومصادرها", "summary": "شرح متحرك بـ SVG لدرس البيانات السكانية ومصادرها للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-population-data-sources.html", "video": "", "pdf": "", "notes": ["البيانات السكانية ضرورية للتخطيط التنموي في التعليم والصحة والاقتصاد.", "المصادر الرئيسة للبيانات السكانية: التعداد السكاني (شامل كل ١٠ سنوات)، التسجيل الحيوي (مواليد/وفيات/زواج يوميًا)، والمسح بالعينة.", "أول تعداد حديث في عُمان كان عام ١٩٩٣م، وفي عام ٢٠٢٠م نُفّذ التعداد الإلكتروني المعتمد على السجلات.", "المركز الوطني للإحصاء والمعلومات (NCSI) هو الجهة الرسمية للبيانات في سلطنة عُمان."], "exercises": ["قارن بين التعداد السكاني والمسح بالعينة من حيث الشمول والتكلفة.", "اذكر ثلاث وقائع يسجّلها نظام «التسجيل الحيوي».", "ما مزايا التعداد الإلكتروني ٢٠٢٠م في سلطنة عُمان؟"], "levels": {"easy": [{"type": "mcq", "q": "العدّ الشامل لجميع السكان والمساكن في الدولة في زمن محدد يُسمّى:", "options": ["الهجرة", "المسح بالعينة", "الكثافة", "التعداد السكاني"], "answer": 3, "why": "التعداد السكاني شامل ودوري."}, {"type": "mcq", "q": "الجهة المسؤولة عن إصدار الإحصاءات السكانية الرسمية في سلطنة عُمان هي:", "options": ["المركز الوطني للإحصاء والمعلومات", "المكتبات الخاصة", "شركات السياحة", "الأندية الرياضية"], "answer": 0, "why": "المركز الوطني للإحصاء والمعلومات (NCSI) هو المرجع الوطني."}, {"type": "mcq", "q": "تُعد شهادات الميلاد والوفاة من مصادر:", "options": ["المسح بالعينة", "التسجيل الحيوي", "الخرائط المناخية", "الصور الجوية"], "answer": 1, "why": "التسجيل الحيوي يوثق المواليد والوفيات والزواج والطلاق."}, {"type": "mcq", "q": "أُجري أول تعداد سكاني حديث في سلطنة عُمان عام:", "options": ["٢٠٢٥م", "١٩٠٠م", "١٩٩٣م", "١٩٥٠م"], "answer": 2, "why": "بدأ أول تعداد حديث في السلطنة عام ١٩٩٣م."}], "medium": [{"type": "mcq", "q": "ما الميزة الأهم لـ«التسجيل الحيوي» مقارنةً بالتعداد السكاني؟", "options": ["أنه يدرس عينة صغيرة فقط", "أنه لا يحتاج سجلات", "أنه يقيس المساحة فقط", "استمراره يوميًا دون انتظار ١٠ سنوات"], "answer": 3, "why": "التسجيل الحيوي مستمر يوميًا."}, {"type": "mcq", "q": "جمع بيانات تفصيلية عن عادات القراءة لدى ١٠٠٠ طالب لتمثيل طلاب السلطنة مثال على:", "options": ["المسح بالعينة", "التعداد الشامل", "التسجيل الحيوي", "التعداد الإلكتروني الشامل"], "answer": 0, "why": "دراسة جزء ممثل من المجتمع تُسمّى المسح بالعينة."}, {"type": "mcq", "q": "من أهم فوائد التعداد الإلكتروني ٢٠٢٠م في سلطنة عُمان:", "options": ["زيادة استهلاك الورق", "توفير التكلفة والوقت وتحديث البيانات باستمرار عبر ربط السجلات", "إلغاء السجل المدني", "تأخير النتائج سنوات"], "answer": 1, "why": "الربط الإلكتروني للسجلات يسرّع النتائج ويقلل التكلفة."}, {"type": "tfr", "q": "تُساعد البيانات السكانية وزارة التربية والتعليم على تحديد مواقع المدارس الجديدة بدقة.", "answer": true, "reasons": ["لأنها تكشف أعداد الأطفال في سن المدرسة في كل ولاية ومخطط سكني", "لأن المدارس تُبنى عشوائيًا", "لأنها لا علاقة لها بالتعليم"], "reason": 0}, {"type": "tfr", "q": "يُجرى التعداد السكاني الشامل عادةً كل شهر في معظم دول العالم.", "answer": false, "reasons": ["يُجرى كل أسبوع", "يُجرى عادةً كل ١٠ سنوات (أو ٥ سنوات) بسبب حجمه وتكلفته، بينما التسجيل الحيوي مستمر يوميًا", "لا يُجرى أبدًا"], "reason": 1}, {"type": "essay", "q": "قارن بين المصادر الثلاثة للبيانات السكانية: التعداد، التسجيل الحيوي، والمسح بالعينة.", "model": "التعداد: شامل لجميع السكان كل ١٠ سنوات. التسجيل الحيوي: تسجيل يومي مستمر للمواليد والوفيات والزواج. المسح بالعينة: دراسة سريعة لجزء ممثل من السكان بتكلفة أقل."}, {"type": "essay", "q": "لماذا يُعد «التزامن الزمني» شرطًا مهمًا في التعداد السكاني التقليدي؟", "model": "لتجنّب تكرار عدّ الشخص نفسه في مكانين أو إغفال عدّه بسبب التنقّل والسفر خلال فترة التعداد."}], "hard": [{"type": "mcq", "q": "أي ميزة تجعل «السجلات الإدارية الإلكترونية» تتفوّق على التعداد الورقي الميداني في المناطق الجبلية والصحراوية؟", "options": ["أن المناطق النائية بلا سكان", "أن الورق أسرع من الحاسوب", "عدم الحاجة لزيارة كل مسكن ناءٍ ميدانيًا مع توفر البيانات المحدثة إلكترونيًا", "أنها تلغي الحاجة للدقة"], "answer": 2, "why": "الربط الإلكتروني يتجاوز صعوبات التضاريس والتكلفة الميدانية."}, {"type": "mcq", "q": "البيانات التي تحصل عليها وزارة الصحة من عدد المواليد الجدد في المستشفيات تُعد جزءًا من:", "options": ["المسح بالعينة", "الجغرافيا المناخية", "الكثافة الزراعية", "التسجيل الحيوي"], "answer": 3, "why": "تسجيل المواليد ركيزة التسجيل الحيوي."}, {"type": "mcq", "q": "إذا أرادت شركة اتصالات معرفة أسباب تفضيل الشباب لتطبيق معين بسرعة وبتكلفة محدودة، فأي مصدر تختار؟", "options": ["المسح بالعينة", "تعداد ١٩٩٣م", "سجل الوفيات", "التعداد الشامل لكل سكان الدولة"], "answer": 0, "why": "المسح بالعينة هو الأسرع والأكثر تفصيلًا وتوفيرًا."}, {"type": "mcq", "q": "أي من الآتي ليس من خصائص التعداد السكاني الجيد؟", "options": ["التزامن الزمني", "الاقتصار على سكان العاصمة فقط", "الدورية", "الشمولية"], "answer": 1, "why": "التعداد يجب أن يكون شاملًا لكل مناطق الدولة وليس العاصمة فقط."}, {"type": "tfr", "q": "قد يعاني التعداد التقليدي من أخطاء مثل عدم تذكّر بعض كبار السن لسنة ميلادهم بدقة.", "answer": true, "reasons": ["لأن العمر لا يُسجّل في التعداد", "لأن الجميع يحفظون كل التواريخ بلا وثائق", "ويُعالج ذلك بالاعتماد على البطاقات المدنية والسجلات الرسمية الموثّقة"], "reason": 2}, {"type": "tfr", "q": "تعتمد رؤية عُمان ٢٠٤٠ على البيانات السكانية الدقيقة لتخطيط سوق العمل والبنية الأساسية.", "answer": true, "reasons": ["لأن معرفة أعداد الشباب والمهارات والتوزيع الجغرافي أساس أي خطة اقتصادية وطنية", "لأن السكان ثابتون لا يتغيرون", "لأن الرؤية لا تستخدم إحصاءات"], "reason": 0}, {"type": "tfr", "q": "المسح بالعينة يغني الدول تمامًا عن وجود نظام التسجيل الحيوي.", "answer": false, "reasons": ["المسح يسجّل كل مولود يوميًا", "التسجيل الحيوي ضروري يوميًا لتوثيق الحقوق المدنية والمواليد والوفيات، ولا يغني عنه المسح بالعينة", "التسجيل الحيوي غير مهم"], "reason": 1}, {"type": "essay", "q": "اشرح أربع فوائد عملية تستفيدها سلطنة عُمان من ربط السجلات الحكومية في التعداد الإلكتروني ٢٠٢٠م.", "model": "١) خفض التكلفة المالية للعمل الميداني. ٢) توفير بيانات محدثة ولحظية لصنّاع القرار. ٣) رفع الدقة وتقليل الأخطاء البشرية. ٤) التخطيط الفعّال للمدارس والمستشفيات والطرق والوظائف."}, {"type": "essay", "q": "كيف تضمن أن تكون «العينة» في المسح بالعينة ممثّلةً للمجتمع بصدق؟", "model": "بأن تُختار بطريقة عشوائية ومنظمة تشمل مختلف المحافظات والفئات العمرية والنوعين والمستويات، وبحجم كافٍ."}, {"type": "essay", "q": "ما الفرق بين البيانات «الأولية» (المباشرة) والبيانات «الثانوية» في الدراسات السكانية؟", "model": "البيانات الأولية تُجمع مباشرةً لأول مرة من الميدان كالتعداد والمسح، أما الثانوية فتُؤخذ من سجلات وتقارير منشورة مسبقًا لدى الجهات الرسمية."}]}},
  {"id": "g9-social-1-u1-2", "grade": "g9", "subject": "social", "term": 1, "unit": 1, "no": 2, "title": "بنية السكان", "summary": "شرح متحرك بـ SVG لدرس بنية السكان للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-population-structure.html", "video": "", "pdf": "", "notes": ["بنية السكان تشمل: البنية العمرية، البنية النوعية، البنية الاقتصادية، والبنية التعليمية.", "الفئات العمرية: صغار السن (<15)، فئة العمل المنتجة (15–64)، كبار السن (65+).", "نسبة الإعالة = (صغار السن + كبار السن) بالنسبة لفئة سن العمل.", "القطاعات الاقتصادية: أولي (زراعة/صيد)، ثانوي (صناعة/بناء)، ثالث (خدمات كالتعليم والصحة والسياحة)."], "exercises": ["اشرح أثر ارتفاع نسبة فئة الشباب (١٥–٦٤) على الاقتصاد العُماني.", "صنّف المهن الآتية حسب القطاع الاقتصادي: صياد سمك، مهندس مصنع إسمنت، ممرض.", "كيف تؤثر الهجرة في البنية النوعية والعمرية للدولة المستقبلة؟"], "levels": {"easy": [{"type": "mcq", "q": "تُصنّف فئة (أقل من ١٥ سنة) ضمن فئة:", "options": ["المتقاعدين", "كبار السن", "صغار السن (فئة مُعالة)", "فئة العمل المنتجة"], "answer": 2, "why": "صغار السن يحتاجون للرعاية والتعليم وتعولهم فئة العمل."}, {"type": "mcq", "q": "ينتمي نشاط «الصيد البحري والزراعة» إلى القطاع الاقتصادي:", "options": ["الخدمي", "الثانوي", "الثالث", "الأولي"], "answer": 3, "why": "الزراعة والصيد والرعي أنشطة القطاع الأولي."}, {"type": "mcq", "q": "ينتمي «التعليم والصحة والسياحة» إلى القطاع الاقتصادي:", "options": ["الثالث (الخدمات)", "الثانوي", "الأولي", "الزراعي"], "answer": 0, "why": "الخدمات تشكل القطاع الثالث."}, {"type": "mcq", "q": "تُقاس «البنية النوعية» للسكان من خلال:", "options": ["مساحة الدولة", "نسبة الذكور إلى الإناث", "عدد المواليد فقط", "نسبة المتعلمين"], "answer": 1, "why": "البنية النوعية تدرس توزيع السكان بين ذكور وإناث."}], "medium": [{"type": "mcq", "q": "أي عامل يؤثر بصورة واضحة في اختلال «نسبة النوع» في الدول المستقبلة للعمالة؟", "options": ["ارتفاع الجبال", "عدد الموانئ", "الهجرة الخارجية للعمل", "الأمطار الموسمية"], "answer": 2, "why": "معظم المهاجرين للعمل يكونون من الذكور في سن الشباب."}, {"type": "mcq", "q": "دولة ترتفع فيها نسبة فئة (٦٥ سنة فأكثر) إلى ٢٥٪ من السكان تُوصف بأنها:", "options": ["مجتمع فتي", "مجتمع بلا إعالة", "مجتمع زراعي فقط", "مجتمع مُسنّ"], "answer": 3, "why": "ارتفاع نسبة كبار السن سمة المجتمعات المسنّة كاليابان."}, {"type": "mcq", "q": "المقصود بـ«نسبة الإعالة» هو:", "options": ["نسبة صغار السن وكبار السن الذين يعولهم السكان في سن العمل", "نسبة المدارس للمستشفيات", "نسبة الصادرات للواردات", "نسبة الذكور للإناث"], "answer": 0, "why": "تقيس العبء الاقتصادي على الفئة المنتجة."}, {"type": "tfr", "q": "ارتفاع نسبة المتعلمين وحملة الشهادات الجامعية يرفع من كفاءة البنية الاقتصادية للدولة.", "answer": true, "reasons": ["لأن التعليم يقلل الإنتاج", "لأنه لا علاقة بينهما", "لأن التعليم يؤهل كوادر ماهرة للابتكار والعمل في القطاعات الحديثة"], "reason": 2}, {"type": "tfr", "q": "تحتاج الدول ذات المجتمع الفتي إلى استثمار أكبر في بناء المدارس والجامعات وتوفير فرص العمل.", "answer": true, "reasons": ["لتلبية احتياجات الأعداد الكبيرة من الأطفال والشباب الداخلين لسوق العمل", "لأن سكانها متقاعدون", "لأنها لا تحتوي أطفالًا"], "reason": 0}, {"type": "essay", "q": "قارن بين أولويات التخطيط في «مجتمع فتي» و«مجتمع مُسنّ».", "model": "المجتمع الفتي يركّز على بناء المدارس والجامعات ومراكز التدريب وخلق فرص عمل للشباب. أما المجتمع المُسنّ فيركّز على الرعاية الصحية لكبار السن وصناديق التقاعد وتعويض نقص الأيدي العاملة."}, {"type": "essay", "q": "كيف يعكس تحوّل العمالة من القطاع الأولي إلى القطاعين الثانوي والثالث تطوّر اقتصاد الدولة؟", "model": "يدل على تنويع مصادر الدخل وتطوّر الصناعة والخدمات الحديثة كالسياحة واللوجستيات والتقنية، بدل الاعتماد على الزراعة التقليدية وحدها."}], "hard": [{"type": "mcq", "q": "إذا بلغت نسبة صغار السن في دولة ٣٠٪ وكبار السن ٥٪، فكم تبلغ نسبة فئة سن العمل (١٥–٦٤ سنة)؟", "options": ["٣٥٪", "٦٥٪", "٥٠٪", "٧٠٪"], "answer": 1, "why": "100% − (30% + 5%) = 65%."}, {"type": "mcq", "q": "يُسمّى الوضع الديموغرافي الذي تتفوق فيه فئة الشباب (١٥–٦٤) على الفئات المُعالة بـ:", "options": ["الهجرة القسرية", "الشيخوخة السكانية", "الفرصة السكانية (الهبة الديموغرافية)", "التعداد الورقي"], "answer": 2, "why": "الفرصة السكانية تتيح نموًا اقتصاديًا قويًا إذا استُثمرت بالتعليم والتوظيف."}, {"type": "mcq", "q": "أي عبارة تفسّر انخفاض نسبة الإعالة في دولة ما؟", "options": ["زيادة عدد المواليد بشدة", "ارتفاع نسبة المتقاعدين إلى 40%", "هجرة جميع الشباب للخارج", "انخفاض نسبي في أعداد الأطفال وكبار السن مقابل ارتفاع نسبة السكان في سن العمل"], "answer": 3, "why": "كلما كبرت فئة سن العمل مقارنة بالمُعالين انخفضت نسبة الإعالة."}, {"type": "mcq", "q": "لماذا تدرس الدول «البنية العمرية» قبل التخطيط لمشاريع الإسكان الجديدة؟", "options": ["لتقدير عدد الشباب المقبلين على الزواج وتكوين أسر جديدة خلال السنوات القادمة", "لحساب كمية الأمطار", "لمعرفة اتجاه الرياح", "لحساب ارتفاع الجبال"], "answer": 0, "why": "أعداد الشباب تحدّد الطلب المستقبلي على المساكن والأراضي."}, {"type": "tfr", "q": "يمكن أن ترتفع نسبة الإعالة في دولة نامية (بسبب كثرة الأطفال) وفي دولة متقدمة (بسبب كثرة كبار السن).", "answer": true, "reasons": ["لأن الإعالة للأطفال فقط", "لأن الإعالة تشمل الفئتين معًا: صغار السن (<15) وكبار السن (65+)", "لأن الدول المتقدمة بلا إعالة"], "reason": 1}, {"type": "tfr", "q": "الهجرة الداخلية من الريف إلى المدينة ترفع عادةً نسبة الشباب في المدن الكبرى.", "answer": true, "reasons": ["لأنها لا تغير البنية العمرية", "لأن كبار السن هم من يهاجرون للعمل", "لأن معظم المهاجرين للمدن يكونون من الشباب الباحثين عن العمل والدراسة الجامعية"], "reason": 2}, {"type": "tfr", "q": "نسبة النوع تُحسب بقسمة عدد السكان على المساحة بالكيلومتر المربع.", "answer": false, "reasons": ["تلك هي الكثافة السكانية؛ أما نسبة النوع فهي (عدد الذكور ÷ عدد الإناث) × 100", "نسبة النوع تقيس التعليم", "نعم هذا تعريف نسبة النوع"], "reason": 0}, {"type": "essay", "q": "اشرح كيف يمكن لسلطنة عُمان استثمار «بنيتها السكانية الشابة» لتحقيق أهداف رؤية عُمان ٢٠٤٠.", "model": "عبر جودة التعليم والتدريب التقني، ودعم ريادة الأعمال والمشاريع الصغيرة للشباب، وتنويع الاقتصاد في السياحة واللوجستيات والتقنية لتوفير وظائف نوعية."}, {"type": "essay", "q": "ما الأثر المتوقّع على البنية الاقتصادية لولاية ساحلية في عُمان عند إنشاء ميناء ومناطق صناعية حديثة فيها؟", "model": "يتوسّع القطاع الثانوي (الصناعة) والقطاع الثالث (اللوجستيات والخدمات والتجارة) وتزداد فرص العمل المتنوعة بجانب الأنشطة التقليدية كالصيد."}, {"type": "essay", "q": "احسب نسبة النوع إذا كان عدد الذكور في مدينة 52,000 وعدد الإناث 50,000، وفسّر النتيجة.", "model": "نسبة النوع = (52,000 ÷ 50,000) × 100 = 104 ذكور لكل 100 أنثى؛ وهي نسبة متقاربة مع زيادة طفيفة للذكور."}]}},
  {"id": "g9-social-1-u1-3", "grade": "g9", "subject": "social", "term": 1, "unit": 1, "no": 3, "title": "الهرم السكاني", "summary": "شرح متحرك بـ SVG لدرس الهرم السكاني للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-population-pyramid.html", "video": "", "pdf": "", "notes": ["الهرم السكاني رسم بياني يعرض البنية العمرية (رأسيًا) والنوعية (ذكورًا وإناثًا على الجانبين).", "أجزاء الهرم: القاعدة (صغار السن/المواليد)، الوسط (فئة العمل ١٥–٦٤)، القمة (كبار السن ٦٥+).", "أنماط الهرم: متسع القاعدة (نمو سريع)، متوازن/ثابت (نمو مستقر)، ضيّق القاعدة (شيخوخة وتناقص).", "يؤدي استقبال العمالة الوافدة إلى بروز واضح في جهة الذكور بوسط الهرم."], "exercises": ["قارن بين الهرم ذي القاعدة العريضة والهرم ذي القاعدة الضيقة من حيث المواليد ونسبة كبار السن.", "فسّر سبب اختلاف شكل هرم السكان العمانيين عن الهرم السكاني الإجمالي في السلطنة.", "ماذا تتوقع لمستقبل سوق العمل في دولة يتّسع وسط هرمها السكاني؟"], "levels": {"easy": [{"type": "mcq", "q": "الجزء الذي يمثّل فئة «كبار السن» في الهرم السكاني هو:", "options": ["وسط الهرم", "قمة الهرم", "المحور الأفقي", "قاعدة الهرم"], "answer": 1, "why": "كبار السن (65+) يُرسمون في أعلى الهرم (القمة)."}, {"type": "mcq", "q": "الجزء الذي يمثّل فئة «صغار السن» في الهرم السكاني هو:", "options": ["قمة الهرم", "وسط الهرم", "قاعدة الهرم", "خارج الهرم"], "answer": 2, "why": "الفئات الصغرى تبدأ من قاعدة الهرم."}, {"type": "mcq", "q": "يدل «اتساع قمة الهرم السكاني» على:", "options": ["ارتفاع الوفيات المبكرة", "كثرة الأطفال", "نقص المستشفيات", "تطور الرعاية الصحية وارتفاع متوسط العمر"], "answer": 3, "why": "الرعاية الصحية الجيدة ترفع متوسط عمر الإنسان فتتسع القمة."}, {"type": "mcq", "q": "الهرم السكاني ذو القاعدة الضيقة جدًّا يميّز دولًا مثل:", "options": ["اليابان وألمانيا", "المجتمعات كثيرة المواليد", "القرى الزراعية النامية", "الدول حديثة النمو السريع"], "answer": 0, "why": "اليابان وألمانيا مثالان شهيران لشيخوخة السكان."}], "medium": [{"type": "mcq", "q": "إذا كان الهرم السكاني لدولة ما غير متماثل وفيه بروز كبير جهة الذكور في فئة (٢٥–٤٠ سنة)، فهذا يشير إلى:", "options": ["كثرة كبار السن", "استقبال عمالة وافدة ذكورية للعمل", "انخفاض المواليد الإناث", "ارتفاع نسبة الأمية"], "answer": 1, "why": "هجرة العمالة الذكورية تسبّب هذا البروز في سن العمل."}, {"type": "mcq", "q": "ما الدلالة الاقتصادية لاتساع «وسط الهرم السكاني» (١٥–٦٤ سنة)؟", "options": ["كثرة المتقاعدين فقط", "نقص الأيدي العاملة", "وفرة القوى العاملة الشابة القادرة على الإنتاج", "توقف الاقتصاد"], "answer": 2, "why": "وسط الهرم يمثّل القوة المنتجة في المجتمع."}, {"type": "mcq", "q": "المحور الأفقي في الهرم السكاني يمثّل عادةً:", "options": ["السنوات الميلادية", "درجة الحرارة", "الارتفاع عن سطح البحر", "نسبة أو عدد السكان في كل فئة عمرية"], "answer": 3, "why": "يعرض المحور الأفقي النسب المئوية أو أعداد الذكور والإناث."}, {"type": "tfr", "q": "الهرم السكاني ذو القاعدة العريضة يدل على ارتفاع معدل المواليد.", "answer": true, "reasons": ["لأنه يدل على قلة المواليد", "لأن القاعدة تمثل الأطفال حديثي الولادة وصغار السن", "لأن القاعدة تمثل كبار السن"], "reason": 1}, {"type": "tfr", "q": "يبقى شكل الهرم السكاني لأي دولة ثابتًا لا يتغيّر عبر العقود.", "answer": false, "reasons": ["لأن السكان لا يتغيرون", "لأن الأعمار ثابتة", "يتغيّر شكل الهرم مع تطور الطب وانخفاض الوفيات وتغيّر معدلات الإنجاب والهجرة"], "reason": 2}, {"type": "essay", "q": "كيف يستفيد مخطّطو التعليم والصحة من قراءة الهرم السكاني لسلطنة عُمان؟", "model": "من قاعدة الهرم يقدّرون أعداد الأطفال الذين سيدخلون المدارس خلال ٥ سنوات، ومن الوسط يخطّطون للجامعات وسوق العمل، ومن القمة يخطّطون لمراكز رعاية كبار السن."}, {"type": "essay", "q": "قارن بين شكل هرم دولة نامية فتية وشكل هرم دولة متقدمة مُسنّة.", "model": "الدولة الفتية: قاعدة عريضة جدًّا وقمة ضيقة مدبّبة. الدولة المسنّة: قاعدة ضيقة جدًّا ووسط وقمة عريضان."}], "hard": [{"type": "mcq", "q": "ماذا تتوقّع أن يحدث لهرم دولة ذات قاعدة عريضة بعد ٣٠ سنة إذا تحسّنت الرعاية الصحية وانخفض معدل الإنجاب؟", "options": ["تضيق القاعدة تدريجيًا ويتّسع الوسط والقمة ليصبح هرمًا متوازنًا", "تختفي القمة", "تتسع القاعدة أكثر", "يبقى كما هو تمامًا"], "answer": 0, "why": "هذا هو التحول الديموغرافي الطبيعي مع التنمية."}, {"type": "mcq", "q": "تظهر أحيانًا «فجوة أو انكماش» في جهة الذكور بفئة عمرية معينة في أهرامات بعض الدول بسبب:", "options": ["تحسّن الطب", "هجرة الشباب للخارج أو الحروب السابقة في ذلك الجيل", "زيادة المواليد", "بناء المدارس"], "answer": 1, "why": "الحروب أو هجرة الشباب تترك أثرًا واضحًا في الفئة العمرية المتأثرة."}, {"type": "mcq", "q": "أي مؤشر من الهرم السكاني يساعدك على معرفة «نسبة الإعالة» بسرعة؟", "options": ["قراءة عنوان الرسم فقط", "لون الأعمدة", "مقارنة مجموع عرض القاعدة والقمة مع عرض وسط الهرم", "عدد الخطوط"], "answer": 2, "why": "القاعدة + القمة (المُعالون) مقارنة بالوسط (المنتجون)."}, {"type": "mcq", "q": "عند مقارنة هرمين سكانيين لدولتين مختلفتين في عدد السكان، يُفضّل رسم المحور الأفقي بـ:", "options": ["المساحة", "عدد المدن", "درجة الحرارة", "النسبة المئوية (%) وليس بالأعداد المطلقة فقط"], "answer": 3, "why": "النسب المئوية تتيح مقارنة عادلة بين دولة سكانها ٥ ملايين ودولة سكانها ١٠٠ مليون."}, {"type": "tfr", "q": "يساعد الهرم السكاني في التنبّؤ بالطلب المستقبلي على الجامعات والوظائف قبل حدوثه بعشر سنوات.", "answer": true, "reasons": ["بمتابعة انتقال الفئات العمرية من القاعدة نحو سن الجامعة والعمل مع مرور السنين", "لأنه يعرض الماضي فقط", "لأنه لا يتضمن أعمارًا"], "reason": 0}, {"type": "tfr", "q": "في الهرم السكاني المقلوب (قاعدة ضيقة جدًّا)، تواجه الدولة تحدّيًا في تمويل معاشات التقاعد مستقبلًا.", "answer": true, "reasons": ["لعدم وجود كبار سن", "لقلة عدد الشباب العاملين الذين يدعمون الاقتصاد مقارنةً بالأعداد الكبيرة من المتقاعدين", "لكثرة الأطفال"], "reason": 1}, {"type": "tfr", "q": "الهرم السكاني يعرض البنية الاقتصادية والمهنية للسكان بشكل مباشر.", "answer": false, "reasons": ["نعم يعرض كل المهن", "يعرض الدخل فقط", "الهرم السكاني يعرض البنية العمرية والنوعية فقط، ولا يعرض المهن"], "reason": 2}, {"type": "essay", "q": "فسّر كيف يعكس الهرم السكاني تاريخ دولة خلال ٧٠ سنة سابقة.", "model": "كل شريحة عمرية في الهرم تمثّل جيلًا وُلد في فترة زمنية محددة؛ فطفرات المواليد أو انخفاضها أو موجات الهجرة والحروب تبقى مطبوعة كاتساع أو ضيق في شرائح الهرم."}, {"type": "essay", "q": "اقترح سياستين لدولة يعاني هرمها السكاني من ضيق شديد في القاعدة واتساع في القمة.", "model": "١) تشجيع الأسر على الإنجاب عبر دعم السكن والحضانات. ٢) استقطاب كفاءات وعمالة شابة مؤهلة وتطوير الأتمتة لرفع الإنتاجية."}, {"type": "essay", "q": "إذا علمتَ أن نسبة فئة (٠–١٤ سنة) في هرم دولة ما هي ٣٨٪، ما التحدي والفرصة أمام هذه الدولة؟", "model": "التحدي: ارتفاع الإنفاق الحالي على المدارس والرعاية الصحية (إعالة مرتفعة). الفرصة: بعد ١٠–١٥ سنة سيشكلون قوة شبابية منتجة ضخمة إذا أُحسن تعليمهم وتأهيلهم."}]}},
  {"id": "g9-social-1-u1-4", "grade": "g9", "subject": "social", "term": 1, "unit": 1, "no": 4, "title": "النمو السكاني والكثافة السكانية", "summary": "شرح متحرك بـ SVG لدرس النمو السكاني والكثافة السكانية للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-population-growth-and-density.html", "video": "", "pdf": "", "notes": ["النمو السكاني = الزيادة الطبيعية (المواليد − الوفيات) + صافي الهجرة (القادمون − المغادرون).", "تطوّر الطب واللقاحات والمياه النقية خفّض الوفيات فسرّع النمو السكاني.", "الكثافة السكانية العامة = عدد السكان ÷ المساحة الكلية (نسمة/كم²).", "عوامل توزيع السكان: طبيعية (الماء، التضاريس، المناخ، التربة) وبشرية (فرص العمل، الخدمات، المواصلات، الأمن)."], "exercises": ["احسب الكثافة السكانية لمحافظة سكانها 450,000 نسمة ومساحتها 1500 كم².", "فسّر سبب ارتفاع الكثافة السكانية في مسقط والباطنة وانخفاضها في محافظة الوسطى.", "اذكر عاملين طبيعيين وعاملين بشريين يؤثران في توزيع السكان."], "levels": {"easy": [{"type": "mcq", "q": "الفرق بين عدد المواليد وعدد الوفيات خلال سنة يُسمّى:", "options": ["الزيادة الطبيعية", "صافي الهجرة", "الكثافة السكانية", "البنية النوعية"], "answer": 0, "why": "الزيادة الطبيعية = المواليد − الوفيات."}, {"type": "mcq", "q": "وحدة قياس الكثافة السكانية هي:", "options": ["متر / ثانية", "نسمة / كم²", "كيلوجرام / م³", "درجة سيليزية"], "answer": 1, "why": "تقيس عدد الأفراد (نسمة) في كل كيلومتر مربع."}, {"type": "mcq", "q": "أي مما يلي يُعد «عاملًا طبيعيًا» مؤثرًا في توزيع السكان؟", "options": ["شبكة الطرق السريعة", "الجامعات", "المناخ ومصادر المياه", "المناطق الصناعية"], "answer": 2, "why": "المناخ والماء والتضاريس عوامل طبيعية."}, {"type": "mcq", "q": "تتميّز محافظة مسقط وسهل الباطنة في سلطنة عُمان بكثافة سكانية:", "options": ["منخفضة جدًّا", "تساوي صفرًا", "معدومة", "مرتفعة"], "answer": 3, "why": "لتوفر السهول الساحلية والخدمات وفرص العمل."}], "medium": [{"type": "mcq", "q": "بلغ عدد سكان مدينة 250,000 نسمة ومساحتها 500 كم². كثافتها السكانية تساوي:", "options": ["500 نسمة/كم²", "2000 نسمة/كم²", "250 نسمة/كم²", "50 نسمة/كم²"], "answer": 0, "why": "250,000 ÷ 500 = 500 نسمة/كم²."}, {"type": "mcq", "q": "السبب الرئيس للزيادة السكانية السريعة في العالم خلال القرن العشرين هو:", "options": ["زيادة الأوبئة", "انخفاض معدلات الوفيات بفضل التقدّم الطبي والغذائي", "توقف الهجرة", "نقص المياه"], "answer": 1, "why": "تطور الطب واللقاحات خفض الوفيات بشكل حاد."}, {"type": "mcq", "q": "تُعد محافظة الوسطى في سلطنة عُمان من أقل المحافظات كثافةً سكانيةً بسبب:", "options": ["توقف الطرق عنها تمامًا", "صغر مساحتها جدًّا", "اتساع مساحتها الصحراوية وجفاف مناخها مقارنة بالسهول الساحلية", "وجود جبال ثلجية"], "answer": 2, "why": "الطبيعة الصحراوية والمساحة الواسعة تقللان الكثافة السكانية."}, {"type": "tfr", "q": "الكثافة السكانية العامة تُظهر دائمًا التوزيع الفعلي الدقيق للسكان في كل أجزاء الدولة.", "answer": false, "reasons": ["لأنها متوسط عام قد يُخفي تركّز السكان في مدن صغيرة وخلوّ الصحارى الواسعة", "لأن السكان يتوزعون بالتساوي في كل متر", "لأنها لا تستخدم المساحة"], "reason": 0}, {"type": "tfr", "q": "تطوير المنطقة الاقتصادية الخاصة بالدقم يُعد عاملًا بشريًا يجذب السكان نحو محافظة الوسطى.", "answer": true, "reasons": ["لأنه يقلل فرص العمل", "لتوفر فرص العمل والموانئ والخدمات والمشاريع الكبرى", "لأنه عامل مناخي طبيعي"], "reason": 1}, {"type": "essay", "q": "قارن بين أثر العوامل الطبيعية والعوامل البشرية في توزيع السكان بسلطنة عُمان مع مثالين لكل منهما.", "model": "الطبيعية: وفرة المياه والأفلاج وسهولة السطح في سهل الباطنة جذبت السكان، بينما جفاف الصحراء قلّلهم. البشرية: توفر الوظائف والموانئ والجامعات والخدمات في مسقط وصحار والدقم جذب أعدادًا كبيرة."}, {"type": "essay", "q": "كيف تحسب «النمو السكاني الكلي» لدولة ما؟ وماذا يحدث إذا فاق عدد الوفيات عدد المواليد؟", "model": "النمو الكلي = (المواليد − الوفيات) + (القادمون − المغادرون). إذا زادت الوفيات عن المواليد حدث «نمو طبيعي سالب» (تناقص سكاني) ما لم تعوّضه الهجرة."}], "hard": [{"type": "mcq", "q": "في دولة ما كان معدل المواليد ٢٥ بالألف ومعدل الوفيات ٥ بالألف. كم يبلغ معدل الزيادة الطبيعية؟", "options": ["٥ بالألف", "١٢٥ بالألف", "٣٠ بالألف", "٢٠ بالألف (أي ٢٪ سنويًا)"], "answer": 3, "why": "25 − 5 = 20 بالألف = 2%."}, {"type": "mcq", "q": "لماذا قد تكون الكثافة السكانية العامة لمصر أو عُمان منخفضةً رقميًا رغم الازدحام في المدن؟", "options": ["لأن المساحة الكلية تضم صحارى شاسعة غير مأهولة تدخل في المقام فتخفض المتوسط العام", "لأن المدن فارغة", "لأن القانون لا يحسب المدن", "لأن السكان يعيشون في الصحراء فقط"], "answer": 0, "why": "دخول الصحارى في المساحة الكلية يخفض رقم الكثافة العامة كثيرًا."}, {"type": "mcq", "q": "أي مشروع وطني يسهم بصورة مباشرة في تخفيف الضغط السكاني عن العاصمة مسقط؟", "options": ["إغلاق الطرق بين المحافظات", "تطوير الموانئ والمناطق الاقتصادية والجامعات في المحافظات الأخرى كصحار وصلالة والدقم", "منع البناء في الولايات", "تقليل الخدمات خارج مسقط"], "answer": 1, "why": "التنمية الإقليمية المتوازنة توزّع فرص العمل والسكان."}, {"type": "mcq", "q": "تقلّ الكثافة السكانية في القطبين الشمالي والجنوبي أساسًا بسبب:", "options": ["قربهما من خط الاستواء", "كثرة الأنهار الدافئة", "البرودة القارسة وتجمّد التربة وصعوبة الزراعة والحياة", "الازدحام الصناعي"], "answer": 2, "why": "الظروف المناخية المتطرفة طاردة للسكان."}, {"type": "tfr", "q": "يمكن أن تنمو مدينة سكانيًا بسرعة كبيرة حتى لو كان معدل مواليدها منخفضًا إذا كانت جاذبةً للهجرة.", "answer": true, "reasons": ["لأن الهجرة لا تدخل في النمو", "لأن المواليد وحدها تحدد النمو", "لأن صافي الهجرة الموجب يرفع النمو السكاني الكلي بسرعة"], "reason": 2}, {"type": "tfr", "q": "وجود موارد طبيعية كالنفط والغاز في مناطق صحراوية قد يُنشئ تجمّعات سكانية حديثة رغم قسوة المناخ.", "answer": true, "reasons": ["فالعامل الاقتصادي والبشري يتغلب بالتقنية والتكييف والتحلية على صعوبة الطبيعة", "النفط يطرد السكان", "يستحيل سكن أي منطقة صحراوية"], "reason": 0}, {"type": "tfr", "q": "إذا تضاعف عدد سكان ولاية مع ثبات مساحتها، فإن كثافتها السكانية تقلّ إلى النصف.", "answer": false, "reasons": ["تنخفض للصفر", "بل تتضاعف الكثافة السكانية مرتين لأنها تتناسب طرديًا مع عدد السكان", "تبقى ثابتة"], "reason": 1}, {"type": "essay", "q": "دولة (أ) سكانها ١٠ ملايين ومساحتها ١٠٠,٠٠٠ كم²، ودولة (ب) سكانها ٤ ملايين ومساحتها ٢٠,٠٠٠ كم². أي الدولتين أعلى كثافةً سكانية؟ وضّح بالحساب.", "model": "كثافة (أ) = 10,000,000 ÷ 100,000 = 100 نسمة/كم². كثافة (ب) = 4,000,000 ÷ 20,000 = 200 نسمة/كم². إذن الدولة (ب) أعلى كثافةً (الضعف) رغم قلة سكانها."}, {"type": "essay", "q": "اقترح ٣ إجراءات عملية للتعامل مع تحديات النمو السكاني السريع في المدن الكبرى.", "model": "١) التخطيط العمراني الحديث وتطوير النقل العام. ٢) التوسع في تحلية المياه والطاقة المتجددة. ٣) إنشاء مدن ومناطق اقتصادية في المحافظات لتقليل الهجرة للعاصمة."}, {"type": "essay", "q": "لماذا يُعد «سهل الباطنة» من أكثر مناطق سلطنة عُمان كثافةً سكانيةً تاريخيًا وحاضرًا؟", "model": "بسبب استواء السطح، وخصوبة التربة والمياه الجوفية للزراعة، والانفتاح على بحر عُمان للتجارة والصيد، ووجود الطرق الحديثة والموانئ."}]}},
  {"id": "g9-social-1-u2-1", "grade": "g9", "subject": "social", "term": 1, "unit": 2, "no": 1, "title": "العمانيون في شرقي أفريقيا", "summary": "شرح متحرك بـ SVG لدرس العمانيون في شرقي أفريقيا للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-omanis-in-east-africa.html", "video": "", "pdf": "", "notes": ["ساعدت الرياح الموسمية (شتاءً جنوبًا وصيفًا شمالًا) السفن العُمانية في التواصل المبكر مع شرقي أفريقيا.", "دوافع التواجد العُماني: التجارة، نشر الإسلام، ونجدة أهل الساحل ضد البرتغاليين.", "حرّر اليعاربة بقيادة الإمام سيف بن سلطان ممباسا وقلعة يسوع عام ١٦٩٨م.", "بلغ التواجد العُماني ذروته في عهد السيد سعيد بن سلطان الذي اتخذ زنجبار عاصمةً ثانيةً عام ١٨٣٢م."], "exercises": ["اشرح دور الرياح الموسمية في رحلات السفن العُمانية إلى شرقي أفريقيا.", "اذكر ثلاثة أسباب لاختيار السيد سعيد بن سلطان لجزيرة زنجبار مقرًا ثانيًا للحكم.", "ما دور دولة اليعاربة في تحرير ساحل شرقي أفريقيا من البرتغاليين؟"], "levels": {"easy": [{"type": "mcq", "q": "الرياح التي ساعدت السفن العُمانية على الإبحار إلى شرقي أفريقيا شتاءً والعودة صيفًا هي:", "options": ["العواصف الرملية", "نسيم الجبل", "الرياح القطبية", "الرياح الموسمية"], "answer": 3, "why": "الرياح الموسمية المنتظمة كانت شريان الملاحة في المحيط الهندي."}, {"type": "mcq", "q": "القلعة الشهيرة في ممباسا التي حررها العُمانيون من البرتغاليين عام ١٦٩٨م هي:", "options": ["قلعة يسوع", "قلعة بهلاء", "قلعة نزوى", "قلعة الجلالي"], "answer": 0, "why": "حاصر اليعاربة قلعة يسوع وحرروها عام ١٦٩٨م."}, {"type": "mcq", "q": "اتخذ السيد سعيد بن سلطان جزيرة زنجبار عاصمةً ثانيةً عام:", "options": ["١٩٩٣م", "١٨٣٢م", "١٥٠٠م", "٢٠٠٠م"], "answer": 1, "why": "في عام ١٨٣٢م أصبحت زنجبار مقرًا ثانيًا للحكم العُماني."}, {"type": "mcq", "q": "من أبرز الموانئ في شرقي أفريقيا التي ارتبطت بالعُمانيين:", "options": ["طوكيو وبكين", "لندن وباريس", "زنجبار وممباسا وكلوة", "روما وأثينا"], "answer": 2, "why": "كانت زنجبار وممباسا وكلوة أهم مراكز التواجد العُماني."}], "medium": [{"type": "mcq", "q": "القائد العُماني من دولة اليعاربة الذي أرسل الأسطول لتحرير ممباسا عام ١٦٩٨م هو:", "options": ["السيد برغش", "الإمام الصلت بن مالك", "السيد ماجد بن سعيد", "الإمام سيف بن سلطان (قيد الأرض)"], "answer": 3, "why": "أرسل الإمام سيف بن سلطان الأسطول العُماني لنجدة أهل ممباسا."}, {"type": "mcq", "q": "المحصول الزراعي الشهير الذي ازدهرت زراعته في زنجبار في عهد السيد سعيد بن سلطان هو:", "options": ["القرنفل", "التفاح", "القمح القطبي", "الزيتون"], "answer": 0, "why": "أدخل السيد سعيد زراعة القرنفل فأصبحت زنجبار أكبر منتج له عالميًا."}, {"type": "mcq", "q": "بعد وفاة السيد سعيد بن سلطان عام ١٨٥٦م، تولّى حكم سلطنة زنجبار ابنه:", "options": ["السيد ثويني بن سعيد", "السيد ماجد بن سعيد", "الإمام ناصر بن مرشد", "الإمام أحمد بن سعيد"], "answer": 1, "why": "تولّى السيد ثويني مسقط وعُمان، وتولّى السيد ماجد زنجبار."}, {"type": "tfr", "q": "جاء الوجود العُماني في ممباسا عام ١٦٩٨م استجابةً لاستغاثة أهالي الساحل الأفريقي ضد البرتغاليين.", "answer": true, "reasons": ["لأنها كانت رحلة سياحية", "لأن البرتغاليين دعوا العُمانيين", "فقد طلب الأهالي نصرة العُمانيين فهبّت دولة اليعاربة لتحريرهم"], "reason": 2}, {"type": "tfr", "q": "كان العُمانيون ينشرون الإسلام في شرقي أفريقيا بالتجارة والأخلاق الحسنة والمعاملة الطيبة.", "answer": true, "reasons": ["مما أكسبهم محبة السكان المحليين واندماجهم الحضاري", "بالإكراه والحروب المستمرة", "لم ينتشر الإسلام هناك"], "reason": 0}, {"type": "essay", "q": "قارن بين اتجاه الرياح الموسمية شتاءً وصيفًا وأثرها على حركة التجارة العُمانية في المحيط الهندي.", "model": "شتاءً تهب الرياح الشمالية الشرقية فتدفع السفن من عُمان إلى شرقي أفريقيا، وصيفًا تهب الرياح الجنوبية الغربية فتعيدها محمّلة بالبضائع إلى موانئ عُمان."}, {"type": "essay", "q": "لماذا أصبحت زنجبار في عهد السيد سعيد بن سلطان مركزًا تجاريًا عالميًا؟", "model": "بسبب الأمن البحري الذي وفّره الأسطول العُماني، والميناء العميق، وزراعة القرنفل، وعقد الاتفاقيات التجارية مع الدول الكبرى كالولايات المتحدة وبريطانيا وفرنسا."}], "hard": [{"type": "mcq", "q": "ما دلالة وصول السفينة العُمانية «سلطانة» إلى ميناء نيويورك عام ١٨٤٠م؟", "options": ["أن السفينة كانت تائهة", "بداية صناعة الطائرات", "قوة الأسطول العُماني والمكانة الدبلوماسية والتجارية لعُمان في عهد السيد سعيد بن سلطان", "أن عُمان لم تبحر خارج الخليج"], "answer": 2, "why": "كانت أول سفينة عربية تصل للولايات المتحدة وعلى متنها المبعوث أحمد بن النعمان الكعبي."}, {"type": "mcq", "q": "أي عبارة تلخّص العلاقة بين مسقط وزنجبار في عهد السيد سعيد بن سلطان؟", "options": ["انقطاع تام بينهما", "دولتان متناحرتان تمامًا", "مستعمرة أوروبية", "إمبراطورية بحرية موحّدة ذات جناحين متكاملين في آسيا وأفريقيا"], "answer": 3, "why": "أدار السيد سعيد مسقط وزنجبار ككيان بحري تجاري موحّد ومزدهر."}, {"type": "mcq", "q": "ما سبب تحكيم «كاننج» (حاكم الهند البريطاني) عام ١٨٦١م؟", "options": ["الفصل الرسمي بين سلطنتي مسقط وزنجبار بعد الخلاف الذي أعقب وفاة السيد سعيد بن سلطان", "إدخال زراعة القرنفل", "تأسيس دولة اليعاربة", "طرد البرتغاليين من ممباسا"], "answer": 0, "why": "أقرّ تحكيم كاننج استقلال زنجبار عن مسقط مقابل تعويض سنوي."}, {"type": "mcq", "q": "من أبرز الصادرات العُمانية التقليدية التي حملتها السفن إلى شرقي أفريقيا:", "options": ["أخشاب الغابات الاستوائية", "التمور والأسماك المجففة واللبان والمنسوجات", "القرنفل والعاج", "السيارات الحديثة"], "answer": 1, "why": "كانت عُمان تصدّر التمور واللبان والمنسوجات وتستورد الأخشاب والعاج والقرنفل."}, {"type": "tfr", "q": "امتدّ النفوذ التجاري العُماني من سواحل شرقي أفريقيا إلى داخل القارة الأفريقية (تنجانيقا والكونغو).", "answer": true, "reasons": ["توقف عند الشاطئ فقط", "عبر القوافل التجارية التي أسست مراكز تجارية داخلية ونشرت اللغة السواحيلية والإسلام", "لم يدخل العمانيون الداخل أبدًا"], "reason": 1}, {"type": "tfr", "q": "استمرّ الحكم العُماني في زنجبار حتى القرن العشرين (عام ١٩٦٤م).", "answer": true, "reasons": ["انتهى عام ١٧٠٠م", "انتهى عام ١٨٠٠م", "لأكثر من قرن بعد وفاة السيد سعيد بن سلطان وترك إرثًا حضاريًا باقيًا"], "reason": 2}, {"type": "tfr", "q": "لم تكن لعُمان أي علاقة بشرقي أفريقيا قبل القرن التاسع عشر.", "answer": false, "reasons": ["بدأت العلاقات منذ عصور قديمة قبل الإسلام وتوطدت مع هجرات العُمانيين منذ القرن الأول الهجري", "بدأت في عهد البرتغاليين فقط", "بدأت عام ١٩٧٠م فقط"], "reason": 0}, {"type": "essay", "q": "اشرح كيف تكاملت العوامل الجغرافية (الموقع والرياح) مع العوامل البشرية (صناعة السفن والقيادة) في نجاح الوجود العُماني بشرقي أفريقيا.", "model": "الموقع المطل على المحيط الهندي والرياح الموسمية مهّدا الطريق بحريًا، بينما صنعت الخبرة العُمانية في بناء السفن والملاحة وقيادة اليعاربة والسيد سعيد بن سلطان قوةً تجاريةً وحضاريةً كبرى."}, {"type": "essay", "q": "اذكر ثلاثة آثار سياسية واقتصادية نتجت عن تحرير العُمانيين لممباسا عام ١٦٩٨م.", "model": "١) إنهاء الهيمنة البرتغالية على سواحل شرقي أفريقيا. ٢) استعادة حرية التجارة البحرية في المحيط الهندي. ٣) توثيق الروابط السياسية والاجتماعية بين عُمان وشرقي أفريقيا."}, {"type": "essay", "q": "قارن بين دور دولة اليعاربة ودور السيد سعيد بن سلطان في شرقي أفريقيا.", "model": "اليعاربة حرّروا الساحل من البرتغاليين وأمّنوا الموانئ عسكريًا، بينما طوّر السيد سعيد بن سلطان التنظيم الإداري والاقتصادي وزراعة القرنفل والعلاقات الدبلوماسية الدولية وجعل زنجبار عاصمةً ثانية."}]}},
  {"id": "g9-social-1-u2-2", "grade": "g9", "subject": "social", "term": 1, "unit": 2, "no": 2, "title": "الملامح الحضارية للتواجد العماني في شرقي أفريقيا", "summary": "شرح متحرك بـ SVG لدرس الملامح الحضارية للتواجد العماني في شرقي أفريقيا للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-omani-civilization-east-africa.html", "video": "", "pdf": "", "notes": ["العمران: المدينة الحجرية بزنجبار (تراث عالمي)، وبيت العجائب الذي بناه السيد برغش بن سعيد عام ١٨٨٣م (أول مبنى بالكهرباء والمصعد).", "الاقتصاد: إدخال زراعة القرنفل في عهد السيد سعيد بن سلطان مما جعل زنجبار أكبر مصدّر له عالميًا.", "الثقافة والعلم: تأسيس المطبعة السلطانية (١٨٧٩م)، وصدور صحف عربية كالفلق والنجاح، وانتشار المساجد والمدارس.", "اللغة والمجتمع: إثراء اللغة السواحيلية بآلاف المفردات العربية، ونشر الإسلام بالتسامح والتعايش."], "exercises": ["اذكر ثلاثة معالم أو إنجازات حضارية للسيد برغش بن سعيد في زنجبار.", "كيف أثّرت اللغة العربية في اللغة السواحيلية؟ أعطِ مثالين.", "علّل تسمية قصر «بيت العجائب» بهذا الاسم."], "levels": {"easy": [{"type": "mcq", "q": "بُني «بيت العجائب» في زنجبار في عهد:", "options": ["السيد ثويني بن سعيد", "الإمام أحمد بن سعيد", "السيد برغش بن سعيد", "الإمام سيف بن سلطان"], "answer": 2, "why": "بناه السيد برغش بن سعيد عام ١٨٨٣م."}, {"type": "mcq", "q": "تأسست «المطبعة السلطانية» في زنجبار عام ١٨٧٩م لطباعة:", "options": ["الخرائط الأوروبية فقط", "العملات المعدنية فقط", "الكتب اليابانية", "الكتب العلمية والدينية والأدبية العُمانية والعربية"], "answer": 3, "why": "أسهمت المطبعة في نشر التراث العلمي والأدبي العُماني."}, {"type": "mcq", "q": "اللغة التي تضم آلاف الكلمات العربية في شرقي أفريقيا هي:", "options": ["السواحيلية", "الروسية", "الإسبانية", "الكورية"], "answer": 0, "why": "تأثرت السواحيلية بعمق باللغة العربية."}, {"type": "mcq", "q": "الموقع العمراني في زنجبار المُدرج على قائمة التراث العالمي لليونسكو هو:", "options": ["برج إيفل", "المدينة الحجرية (Stone Town)", "سور الصين", "الأهرامات"], "answer": 1, "why": "المدينة الحجرية بزنجبار تحفة معمارية عُمانية-أفريقية."}], "medium": [{"type": "mcq", "q": "لماذا سُمّي القصر الذي بناه السيد برغش بـ«بيت العجائب»؟", "options": ["لأنه بلا أبواب", "لأنه بُني تحت الماء", "لأنه أول مبنى في شرقي أفريقيا يُزوَّد بالكهرباء والمصعد الكهربائي", "لأنه صغير جدًّا"], "answer": 2, "why": "أدهش السكان بضخامته وتقنياته الحديثة كالكهرباء والمصعد."}, {"type": "mcq", "q": "من مظاهر التحديث الخدمي التي أدخلها السلاطين العُمانيون إلى زنجبار:", "options": ["القطارات الفضائية", "الطاقة النووية", "المصانع الثقيلة فقط", "أنابيب المياه العذبة وإنارة الشوارع والتلغراف"], "answer": 3, "why": "أدخل العمانيون المياه العذبة والكهرباء والتلغراف والمستشفيات."}, {"type": "mcq", "q": "أبرز مثال على النشاط الصحفي العربي العُماني في زنجبار هو إصدار صحيفتَي:", "options": ["الفلق والنجاح", "الشروق والغروب", "الأخبار والرياضة", "المحيط والبحر"], "answer": 0, "why": "لعبت الفلق والنجاح دورًا ثقافيًا وفكريًا كبيرًا."}, {"type": "tfr", "q": "اقتصرت الملامح الحضارية العُمانية في شرقي أفريقيا على التجارة فقط دون أي أثر علمي أو عمراني.", "answer": false, "reasons": ["كانت عسكرية فقط", "بل شملت العمران (بيت العجائب) والطباعة والصحافة والمدارس واللغة والزراعة", "لم يبنِ العمانيون شيئًا"], "reason": 1}, {"type": "tfr", "q": "كانت اللغة السواحيلية تُكتب قديمًا بالحروف العربية نتيجة التواصل الحضاري مع العُمانيين.", "answer": true, "reasons": ["كانت تُكتب بالصينية", "لم تُكتب أبدًا بالعربية", "وحفظت بذلك كثيرًا من التراث والأدب السواحيلي القديم"], "reason": 2}, {"type": "essay", "q": "عدّد أربعة مجالات برز فيها العطاء الحضاري العُماني في شرقي أفريقيا مع مثال واحد لكل مجال.", "model": "١) العمران: بيت العجائب والمدينة الحجرية. ٢) الاقتصاد: زراعة القرنفل. ٣) الثقافة والطباعة: المطبعة السلطانية وصحيفة الفلق. ٤) اللغة والدين: نشر الإسلام وإثراء السواحيلية."}, {"type": "essay", "q": "ما الدور الذي لعبته «المطبعة السلطانية» في حفظ التراث العلمي العُماني؟", "model": "طبعت عشرات الكتب والمخطوطات العُمانية النادرة في الفقه والتاريخ واللغة ووزّعتها على العلماء والمكتبات في عُمان وشرقي أفريقيا والعالم الإسلامي."}], "hard": [{"type": "mcq", "q": "أي مظهر ثقافي يؤكد التمازج الحضاري السلمي بين العُمانيين وشعوب شرقي أفريقيا؟", "options": ["منع التجارة المحلية", "انتشار الزي التقليدي (الدشداشة والكمة) والضيافة والكلمات العربية في السواحيلية", "إغلاق الموانئ", "العزلة التامة بين السكان"], "answer": 1, "why": "التأثير المتبادل في اللغة واللباس والعادات دليل تعايش واندماج."}, {"type": "mcq", "q": "تعاون سلطنة عُمان اليوم مع تنزانيا في ترميم «بيت العجائب» يدل على:", "options": ["رغبة في هدم المبنى", "نسيان التاريخ", "الاهتمام بصون التراث الحضاري المشترك وتعميق العلاقات التاريخية", "توقف العلاقات"], "answer": 2, "why": "ترميم المعالم يحفظ التاريخ المشترك ويعزز السياحة الثقافية."}, {"type": "mcq", "q": "ما الأثر الاقتصادي لإدخال زراعة القرنفل في زنجبار وبمبا؟", "options": ["نقص الغذاء", "هجرة السكان من الجزيرة", "تراجع التجارة البحرية", "تحوّل زنجبار لأكبر منتج ومصدّر للقرنفل عالميًا مما درّ عوائد ضخمة موّلت النهضة العمرانية"], "answer": 3, "why": "عوائد القرنفل دعمت بناء القصور والمطبعة والخدمات الحديثة."}, {"type": "mcq", "q": "يُعد الطراز المعماري للأبواب الخشبية المنقوشة بالمسامير النحاسية في زنجبار مزيجًا من:", "options": ["الفنون العُمانية والعربية والهندية والأفريقية", "الخرسانة الحديثة فقط", "الطراز القطبي فقط", "البلاستيك"], "answer": 0, "why": "تعكس الأبواب الزنجبارية التقاء حضارات المحيط الهندي."}, {"type": "tfr", "q": "كان التسامح الديني وحماية حرية العبادة من السياسات الثابتة للحكم العُماني في زنجبار.", "answer": true, "reasons": ["فعاش المسلمون وغير المسلمين في أمن وازدهار تجاري مشترك", "سادت الصراعات الدينية", "لم يُسمح لغير المسلمين بالتجارة"], "reason": 0}, {"type": "tfr", "q": "أسهم العلماء والقضاة العُمانيون في زنجبار في نشر التعليم وإرساء القضاء العادل.", "answer": true, "reasons": ["لم يكن هناك قضاء", "فتولّوا القضاء والتدريس والتأليف وطباعة الكتب", "اقتصر دورهم على الصيد"], "reason": 1}, {"type": "tfr", "q": "تقتصر المفردات العربية في اللغة السواحيلية على كلمتين أو ثلاث فقط.", "answer": false, "reasons": ["كلها كلمات لاتينية", "لا توجد أي كلمة عربية", "بل تضم السواحيلية آلاف الكلمات العربية في الدين والتجارة والزمن والحياة اليومية"], "reason": 2}, {"type": "essay", "q": "اشرح كيف مهّدت النهضة الاقتصادية في عهد السيد سعيد بن سلطان للنهضة العمرانية والعلمية في عهد السيد برغش بن سعيد.", "model": "الازدهار التجاري وعوائد القرنفل التي أسسها السيد سعيد وفّرت الموارد المالية والانفتاح الدولي الذي مكّن السيد برغش لاحقًا من بناء بيت العجائب وتأسيس المطبعة وإدخال الكهرباء والمياه."}, {"type": "essay", "q": "لماذا يُعد إدراج المدينة الحجرية في زنجبار ضمن التراث العالمي لليونسكو مصدر فخر لعُمان وشرقي أفريقيا معًا؟", "model": "لأنه اعتراف عالمي بالقيمة المعمارية والتاريخية الاستثنائية للحضارة العُمانية-الأفريقية المشتركة وتعايشها الثقافي."}, {"type": "essay", "q": "اذكر ثلاث كلمات عربية متداولة في اللغة السواحيلية وبيّن دلالة ذلك تاريخيًا.", "model": "مثل: سلام (Salama)، كتاب (Kitabu)، وقت (Wakati)، سفر (Safari) — وتدل على عمق التواصل الثقافي والعلمي والتجاري العُماني."}]}},
  {"id": "g9-social-1-u2-3", "grade": "g9", "subject": "social", "term": 1, "unit": 2, "no": 3, "title": "التواصل العماني مع شرقي أفريقيا", "summary": "شرح متحرك بـ SVG لدرس التواصل العماني مع شرقي أفريقيا للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-omani-relations-east-africa.html", "video": "", "pdf": "", "notes": ["التواصل الاجتماعي: روابط أسرية وقرابة ممتدة وإتقان للغتين العربية والسواحيلية.", "التواصل الدبلوماسي: سفارات وقنصليات ولجان وزارية واتفاقيات تعاون رسمية مع دول شرقي أفريقيا.", "التواصل الاقتصادي: رحلات الطيران العُماني المباشرة، والاستثمار في الموانئ والسياحة والزراعة والتجارة.", "التواصل الثقافي والعلمي: ندوات هيئة الوثائق والمحفوظات، وترميم المعالم التاريخية كبيت العجائب، والمنح الدراسية."], "exercises": ["اذكر أربعة مجالات للتواصل العُماني المعاصر مع دول شرقي أفريقيا.", "كيف تسهم الموانئ العُمانية والطيران العُماني في تنمية التجارة مع شرقي أفريقيا؟", "ما أهمية التعاون الثقافي في حفظ التراث العُماني بزنجبار؟"], "levels": {"easy": [{"type": "mcq", "q": "من أبرز الدول الأفريقية التي ترتبط بعلاقات تاريخية ومعاصرة قوية مع سلطنة عُمان:", "options": ["كندا والمكسيك", "تنزانيا وكينيا", "أستراليا ونيوزيلندا", "البرازيل والأرجنتين"], "answer": 1, "why": "تنزانيا (وبضمنها زنجبار) وكينيا في قلب شرقي أفريقيا."}, {"type": "mcq", "q": "تُعد مشاركة عُمان في ترميم «بيت العجائب» بزنجبار مثالًا على التواصل:", "options": ["العسكري فقط", "المناخي", "الثقافي والتراثي", "الرياضي فقط"], "answer": 2, "why": "صيانة المعالم التاريخية جهد ثقافي وتراثي مشترك."}, {"type": "mcq", "q": "يساعد وجود سفارات وقنصليات متبادلة بين عُمان ودول شرقي أفريقيا على:", "options": ["إيقاف التجارة", "إغلاق المدارس", "منع السياحة", "تسهيل شؤون المواطنين وتوقيع اتفاقيات التعاون الاقتصادي والثقافي"], "answer": 3, "why": "التمثيل الدبلوماسي يرعى المصالح المشتركة والمواطنين."}, {"type": "mcq", "q": "يُعد الاستثمار في قطاع السياحة والموانئ مثالًا على التواصل:", "options": ["الاقتصادي", "اللغوي فقط", "المناخي", "الزراعي فقط"], "answer": 0, "why": "السياحة والموانئ واللوجستيات ركائز التعاون الاقتصادي."}], "medium": [{"type": "mcq", "q": "ما الأثر المباشر للربط الجوي المباشر بين مسقط وزنجبار ونيروبي؟", "options": ["إلغاء التجارة البحرية", "تسهيل حركة السياح ورجال الأعمال وتواصل الأسر", "منع الطلاب من السفر", "زيادة زمن السفر لأسابيع"], "answer": 1, "why": "الطيران المباشر يختصر المسافة وينشّط السياحة والتجارة."}, {"type": "mcq", "q": "كيف تسهم «المنح الدراسية والتبادل الجامعي» في العلاقات العُمانية-الأفريقية؟", "options": ["تمنع تعلم اللغات", "تضعف التواصل", "تبني جسورًا علميةً وثقافيةً بين جيل الشباب في الجانبين", "تقتصر على التجارة فقط"], "answer": 2, "why": "التعليم والتبادل الشبابي استثمار طويل الأمد في الصداقة."}, {"type": "mcq", "q": "ما الميزة التنافسية التي تمتلكها عُمان عند الاستثمار في أسواق شرقي أفريقيا؟", "options": ["انعدام الموانئ", "البعد الجغرافي الشديد", "عدم وجود روابط لغوية", "الثقة التاريخية، القرب الجغرافي، والموانئ الحديثة"], "answer": 3, "why": "القرب البحري والإرث الإيجابي يسهّلان الشراكة الاقتصادية."}, {"type": "tfr", "q": "تقتصر علاقات سلطنة عُمان المعاصرة مع شرقي أفريقيا على جزيرة زنجبار فقط.", "answer": false, "reasons": ["بل تمتد لتشمل تنزانيا وكينيا وأوغندا ورواندا وبوروندي وغيرها من دول المنطقة", "انقطعت العلاقات عام ١٩٦٤م", "لا توجد علاقات مع كينيا"], "reason": 0}, {"type": "tfr", "q": "تلعب هيئة الوثائق والمحفوظات الوطنية دورًا مهمًا في إحياء وتوثيق التاريخ المشترك مع شرقي أفريقيا.", "answer": true, "reasons": ["لأنها شركة طيران", "من خلال المؤتمرات الدولية والمعارض ونشر الوثائق التاريخية", "لأنها تعمل في الزراعة فقط"], "reason": 1}, {"type": "essay", "q": "اشرح كيف تحوّل «الإرث التاريخي» بين عُمان وشرقي أفريقيا إلى فرصة اقتصادية وسياحية اليوم.", "model": "أسّس التاريخ المشترك ثقةً وروابط ثقافية ومعالم سياحية تجذب الزوار، وتستثمرها عُمان اليوم عبر الطيران المباشر والموانئ والمشاريع المشتركة."}, {"type": "essay", "q": "اذكر دورين للشباب العُماني في تعزيز التواصل الثقافي مع شرقي أفريقيا.", "model": "١) المشاركة في التبادل الطلابي والرحلات البحرية الثقافية (مثل سفينة شباب عُمان). ٢) إنتاج محتوى رقمي وتراثي يعرّف بالتاريخ المشترك باللغتين العربية والسواحيلية."}], "hard": [{"type": "mcq", "q": "أي تكامل اقتصادي يعبّر بدقة عن مصلحة عُمان وشرقي أفريقيا؟", "options": ["ربط الموانئ والمناطق اللوجستية العُمانية بأسواق وموارد شرقي أفريقيا الزراعية والسياحية", "التنافس العدائي وإغلاق الحدود", "الاعتماد على منتج واحد فقط", "إلغاء الرحلات الجوية"], "answer": 0, "why": "التكامل اللوجستي والتجاري يحقق منفعة متبادلة للجانبين."}, {"type": "mcq", "q": "لماذا تُعد «الدبلوماسية الثقافية» (الندوات، الترميم، المعارض) مكملًا مهمًا للدبلوماسية السياسية؟", "options": ["لأنها مكلفة بلا فائدة", "لأنها تقرّب الشعوب وتبني فهمًا عميقًا ومستدامًا يتجاوز الاتفاقيات الرسمية", "لأنها تمنع الاستثمار", "لأنها تلغي السفارات"], "answer": 1, "why": "التواصل الشعبي والثقافي يرسّخ الصداقة الدائمة بين الدول."}, {"type": "mcq", "q": "أي ميناء عُماني يقع على بحر العرب مباشرةً ويشكّل نقطة انطلاق سريعة نحو سواحل شرقي أفريقيا؟", "options": ["وادي شاب", "ميناء داخلي في الصحراء", "ميناء صلالة (وميناء الدقم)", "جبل شمس"], "answer": 2, "why": "ميناء صلالة وميناء الدقم مطلّان مباشرةً على خطوط الملاحة بالمحيط الهندي."}, {"type": "mcq", "q": "ما أهمية توثيق الروايات الشفهية والوثائق القديمة العُمانية في شرقي أفريقيا قبل ضياعها؟", "options": ["تقليل السياحة", "زيادة الخلافات", "تجاهل الماضي", "حفظ التاريخ المشترك للأجيال القادمة وتقديمه بمصادر علمية موثوقة"], "answer": 3, "why": "التوثيق العلمي يحمي التراث الإنساني من النسيان."}, {"type": "tfr", "q": "تسهم الجاليات والأسر ذات الأصول المشتركة في تسهيل التفاهم التجاري والثقافي بين عُمان وشرقي أفريقيا.", "answer": true, "reasons": ["لأنها لا تتحدث العربية ولا السواحيلية", "لأنها تعيق التجارة", "لمعرفتها باللغات والعادات والأسواق في كلا الجانبين"], "reason": 2}, {"type": "tfr", "q": "تتعارض علاقات عُمان القوية مع شرقي أفريقيا مع سياستها في بناء علاقات طيبة مع بقية قارات العالم.", "answer": false, "reasons": ["بل تنسجم مع مبدأ السياسة العُمانية القائم على الصداقة والانفتاح المتوازن مع الجميع", "تغلق موانئها", "تمنع علاقاتها مع آسيا"], "reason": 0}, {"type": "tfr", "q": "يُعد التعاون في مجال «الأمن الغذائي والاستثمار الزراعي» من المجالات الواعدة بين عُمان وشرقي أفريقيا.", "answer": true, "reasons": ["لأنه لا يوجد نقل بحري", "لخصوبة الأراضي الزراعية في شرقي أفريقيا ووفرة أمطارها وقربها البحري من عُمان", "لأن شرقي أفريقيا صحراء قاحلة بالكامل"], "reason": 1}, {"type": "essay", "q": "اقترح مبادرةً شبابيةً أو مدرسيةً لتعريف الطلاب بعمق التواصل العُماني مع شرقي أفريقيا.", "model": "إقامة «يوم التراث البحري العُماني-الأفريقي» بالمدرسة يضم معرضًا لصور بيت العجائب والسفن العُمانية، وركنًا للمفردات العربية في السواحيلية، ولقاءً مع باحث في التاريخ البحري."}, {"type": "essay", "q": "وضّح كيف يدعم موقع ميناء صلالة والدقم دور عُمان كبوابة تجارية بين الخليج وشرقي أفريقيا.", "model": "إطلالتهما المباشرة على المحيط الهندي وخطوط الشحن العالمية تختصر وقت وتكلفة نقل البضائع بين دول الخليج وأسواق شرقي أفريقيا."}, {"type": "essay", "q": "لخّص في أربع نقاط أبرز أسباب استمرار نجاح العلاقات العُمانية-الأفريقية عبر القرون.", "model": "١) التسامح والاحترام المتبادل. ٢) الروابط الأسرية والثقافية العميقة. ٣) المصالح التجارية والتكامل الجغرافي. ٤) الدبلوماسية العُمانية الهادئة المتوازنة."}]}},
  {"id": "g9-social-1-u3-1", "grade": "g9", "subject": "social", "term": 1, "unit": 3, "no": 1, "title": "عُمان في محيطها الإسلامي", "summary": "شرح متحرك بـ SVG لدرس عُمان في محيطها الإسلامي للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-oman-islamic-world.html", "video": "", "pdf": "", "notes": ["دخل أهل عُمان الإسلام طوعًا وأسهموا تاريخيًا في نشره بالقدوة والتجارة في آسيا وأفريقيا.", "انضمّت سلطنة عُمان إلى منظمة التعاون الإسلامي (مقرها جدة، ٥٧ دولة) عام ١٩٧٠م.", "تتعاون عُمان مع منظمة الإيسيسكو (التربية والعلوم والثقافة)، واختيرت نزوى عاصمةً للثقافة الإسلامية عام ٢٠١٥م.", "تبرز عُمان بنشر التسامح (معرض رسالة الإسلام من عُمان) ودعم القضايا العادلة والوساطة السلمية."], "exercises": ["اذكر ثلاثة أهداف لمنظمة التعاون الإسلامي ودور عُمان فيها.", "ما أهمية اختيار نزوى عاصمةً للثقافة الإسلامية عام ٢٠١٥م؟", "كيف تسهم عُمان في نشر صورة إيجابية متسامحة عن الإسلام عالميًا؟"], "levels": {"easy": [{"type": "mcq", "q": "مقرّ منظمة التعاون الإسلامي يقع في مدينة:", "options": ["جدة", "لندن", "نيويورك", "القاهرة"], "answer": 0, "why": "يقع المقر الدائم لمنظمة التعاون الإسلامي في مدينة جدة."}, {"type": "mcq", "q": "تُعد منظمة التعاون الإسلامي ثاني أكبر منظمة دولية حكومية بعد:", "options": ["رابطة المدارس", "الأمم المتحدة", "اتحاد كرة القدم", "منظمة الأرصاد"], "answer": 1, "why": "تضم ٥٧ دولةً إسلاميةً عبر أربع قارات."}, {"type": "mcq", "q": "اختيرت مدينة نزوى عاصمةً للثقافة الإسلامية عام:", "options": ["١٩٩٠م", "١٩٧٠م", "٢٠١٥م", "١٩٠٠م"], "answer": 2, "why": "اختارتها الإيسيسكو عام ٢٠١٥م لمكانتها العلمية والتاريخية."}, {"type": "mcq", "q": "الجهة المسؤولة عن تنظيم معرض «رسالة الإسلام من عُمان» هي:", "options": ["هيئة الطيران", "وزارة الرياضة", "بلدية ظفار", "وزارة الأوقاف والشؤون الدينية"], "answer": 3, "why": "تنظمه وزارة الأوقاف والشؤون الدينية لنشر قيم التسامح."}], "medium": [{"type": "mcq", "q": "انضمّت سلطنة عُمان إلى منظمة التعاون الإسلامي بعد تأسيسها بسنة واحدة، أي عام:", "options": ["١٩٧٠م", "٢٠٠٠م", "١٩٦٠م", "١٩٨٥م"], "answer": 0, "why": "تأسست المنظمة عام ١٩٦٩م وانضمت عُمان عام ١٩٧٠م."}, {"type": "mcq", "q": "الاختصاص الرئيس لمنظمة «الإيسيسكو» (ICESCO) هو:", "options": ["إدارة المطارات", "التربية والعلوم والثقافة وحماية التراث الإسلامي", "تصدير النفط", "صناعة السفن"], "answer": 1, "why": "الإيسيسكو هي الذراع التربوي والعلمي والثقافي للعالم الإسلامي."}, {"type": "mcq", "q": "يمتاز أسلوب السياسة العُمانية في معالجة الخلافات بين الدول الإسلامية بـ:", "options": ["التصعيد الإعلامي", "العزلة التامة", "الوساطة الهادئة والحوار البناء وعدم التدخل في الشؤون الداخلية", "المقاطعة المستمرة"], "answer": 2, "why": "تشتهر عُمان بدبلوماسية الحوار والوساطة الحكيمة."}, {"type": "tfr", "q": "يُعد «البنك الإسلامي للتنمية» من مؤسسات التعاون الاقتصادي التي تسهم في تمويل مشاريع التنمية بالدول الإسلامية.", "answer": true, "reasons": ["لأنه بنك تجاري خاص بمدينة واحدة", "لأنه يقتصر على الرياضة", "حيث يموّل مشاريع التعليم والصحة والبنية التحتية في الدول الأعضاء"], "reason": 2}, {"type": "tfr", "q": "تقتصر علاقات عُمان في محيطها الإسلامي على الجانب الديني فقط دون أي تعاون اقتصادي أو علمي.", "answer": false, "reasons": ["بل تشمل التعاون الدبلوماسي والاقتصادي والإنساني والثقافي والعلمي", "لا يوجد تعاون ثقافي", "تقتصر على السياحة"], "reason": 0}, {"type": "essay", "q": "اشرح كيف يجمع الدور العُماني في العالم الإسلامي بين «الأصالة التاريخية» و«العمل المعاصر».", "model": "الأصالة: إسلام أهل عُمان طوعًا ونشره بالقدوة وعطاء علمائها قديمًا. المعاصرة: عضويتها الفاعلة في منظمة التعاون الإسلامي والإيسيسكو، ومعرض رسالة الإسلام، والوساطة السلمية والإغاثة."}, {"type": "essay", "q": "اذكر ثلاثة مجالات تتعاون فيها سلطنة عُمان مع منظمة الإيسيسكو.", "model": "١) حفظ التراث والمخطوطات الإسلامية. ٢) تطوير التعليم والبحث العلمي. ٣) إبراز العواصم الثقافية الإسلامية (مثل نزوى ٢٠١٥م)."}], "hard": [{"type": "mcq", "q": "لماذا تحظى سلطنة عُمان بموثوقية عالية كوسيط سلام بين الدول الإسلامية؟", "options": ["لبعدها عن القضايا الإسلامية", "لانحيازها الدائم", "لعدم عضويتها في المنظمات", "لالتزامها بالحياد الإيجابي والاحترام المتبادل والحوار الهادئ وعدم التدخل"], "answer": 3, "why": "الحياد الإيجابي والشفافية يمنحان عُمان قبولًا لدى مختلف الأطراف."}, {"type": "mcq", "q": "ما الدلالة الثقافية لتجوّل معرض «رسالة الإسلام من عُمان» في أكثر من ٣٠ دولةً حول العالم؟", "options": ["تصحيح الصورة النمطية عن الإسلام وإبراز قيم التعايش والتفاهم الإنساني", "الترويج لصناعة واحدة", "حصر الثقافة داخل عُمان فقط", "المنافسة التجارية"], "answer": 0, "why": "يقدّم المعرض نموذجًا حيًا للتسامح والتعايش في عُمان."}, {"type": "mcq", "q": "أي عالم عُماني شهير يُعد مؤسس علم العروض وأول معجم عربي (كتاب العين) مما يعكس إسهام عُمان في الثقافة الإسلامية؟", "options": ["ابن سينا", "الخليل بن أحمد الفراهيدي", "جاليليو", "إسحاق نيوتن"], "answer": 1, "why": "الخليل بن أحمد الفراهيدي من أعلام عُمان والعالم الإسلامي."}, {"type": "mcq", "q": "كيف تسهم «الهيئة العُمانية للأعمال الخيرية» في تعزيز التضامن الإسلامي؟", "options": ["بتنظيم الرحلات التجارية فقط", "بجمع الضرائب", "بتقديم الإغاثة العاجلة والمساعدات الإنسانية والطبية للشعوب الشقيقة المتضررة من الأزمات", "ببناء الموانئ فقط"], "answer": 2, "why": "تقدّم الهيئة مساعدات إنسانية وإغاثية منتظمة للدول الشقيقة."}, {"type": "tfr", "q": "انضمام عُمان المبكر عام ١٩٧٠م لمنظمة التعاون الإسلامي يعكس أولوية التضامن الإسلامي منذ بداية النهضة الحديثة.", "answer": true, "reasons": ["انضمت بعد ٥٠ سنة", "فقد بادرت السلطنة للانضمام والمشاركة الفاعلة فور انطلاق نهضتها عام ١٩٧٠م", "ليست عضوًا فيها"], "reason": 1}, {"type": "tfr", "q": "تُعد نزوى وحدها المدينة العُمانية ذات الإرث الإسلامي ولا توجد غيرها.", "answer": false, "reasons": ["نزوى مدينة حديثة فقط", "لا توجد مدن تاريخية أخرى", "تزخر عُمان بمدن تاريخية إسلامية عديدة كمسقط وصحار وبهلاء وصلالة وصور، وإن كانت نزوى رمزًا للعلم والعلماء"], "reason": 2}, {"type": "tfr", "q": "يعزّز التبادل الطلابي والمنح الدراسية بين الجامعات العُمانية والجامعات الإسلامية التقارب العلمي والحضاري.", "answer": true, "reasons": ["فيبادل الباحثون والطلاب الخبرات والمعرفة ويقوّون الروابط بين الشعوب", "يضعف الجامعات", "يمنع البحث العلمي"], "reason": 0}, {"type": "essay", "q": "ما القيم الأربع التي يركّز عليها النموذج العُماني في التعامل داخل العالم الإسلامي؟", "model": "١) التسامح الديني والمذهبي. ٢) التعايش السلمي والاحترام المتبادل. ٣) الحوار والوساطة لحل الخلافات. ٤) التضامن الإنساني ودعم القضايا العادلة."}, {"type": "essay", "q": "قارن بين دور منظمة التعاون الإسلامي (OIC) ومنظمة الإيسيسكو (ICESCO).", "model": "منظمة التعاون الإسلامي منظمة سياسية واقتصادية شاملة تضم ٥٧ دولةً وتنسق المواقف والتضامن العام، بينما الإيسيسكو منظمة متخصصة في مجالات التربية والعلوم والثقافة وحماية التراث."}, {"type": "essay", "q": "اكتب فقرة قصيرة تقترح فيها كيف يمكن لطالب الصف التاسع أن يمثّل «رسالة التسامح العُمانية» على الإنترنت ووسائل التواصل.", "model": "باستخدام لغة محترمة وراقية، واحترام الاختلافات الثقافية والمذهبية، ونشر المعرفة المفيدة وصورة عُمان المشرقة في السلم وحسن الخلق، وتجنّب التنمر أو الإساءة للآخرين."}]}},
  {"id": "g9-social-1-u3-2", "grade": "g9", "subject": "social", "term": 1, "unit": 3, "no": 2, "title": "عُمان في محيطها العالمي", "summary": "شرح متحرك بـ SVG لدرس عُمان في محيطها العالمي للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-oman-global-world.html", "video": "", "pdf": "", "notes": ["مبادئ السياسة الخارجية العُمانية: حسن الجوار، عدم التدخل، حل النزاعات سلميًا، واحترام القانون الدولي.", "انضمّت عُمان إلى الأمم المتحدة في أكتوبر ١٩٧١م وتشارك في وكالاتها كاليونسكو ومنظمة الصحة العالمية.", "من مواقع التراث العالمي في عُمان: قلعة بهلاء، بات والخطم والعين، أرض اللبان، الأفلاج، ومدينة قلهات.", "تُعد جائزة السلطان قابوس لحماية البيئة (مع اليونسكو) والالتزام بالحياد الصفري ٢٠٥٠م من أبرز جهود عُمان البيئية العالمية."], "exercises": ["اذكر ثلاثة مبادئ ثابتة للسياسة الخارجية لسلطنة عُمان.", "سمّ ثلاثة مواقع عُمانية مُدرجة على قائمة التراث العالمي لليونسكو.", "كيف تسهم عُمان عالميًا في مجال حماية البيئة والطاقة النظيفة؟"], "levels": {"easy": [{"type": "mcq", "q": "انضمّت سلطنة عُمان إلى منظمة الأمم المتحدة في عام:", "options": ["١٩٦٠م", "٢٠١٠م", "١٩٩٥م", "١٩٧١م"], "answer": 3, "why": "في أكتوبر ١٩٧١م أصبحت عُمان عضوًا في الأمم المتحدة."}, {"type": "mcq", "q": "المنظمة الدولية التي تمنح «جائزة السلطان قابوس لحماية البيئة» بالتعاون مع السلطنة هي:", "options": ["اليونسكو (UNESCO)", "مجلس الأمن", "أوبك", "منظمة الطيران"], "answer": 0, "why": "تُمنح الجائزة كل عامين عبر اليونسكو."}, {"type": "mcq", "q": "أي موقع مما يلي مُدرج ضمن قائمة التراث العالمي في سلطنة عُمان؟", "options": ["سور الصين العظيم", "الأفلاج العُمانية ومدينة قلهات التاريخية", "الأهرامات", "تاج محل"], "answer": 1, "why": "خمسة أفلاج عُمانية ومدينة قلهات مسجّلة في اليونسكو."}, {"type": "mcq", "q": "الهدف البيئي العالمي الذي التزمت به سلطنة عُمان بحلول عام ٢٠٥٠م هو:", "options": ["إلغاء الطاقة الشمسية", "إغلاق الموانئ", "الحياد الصفري الكربوني", "زيادة التلوث"], "answer": 2, "why": "تعمل عُمان على مشاريع الطاقة المتجددة والهيدروجين الأخضر لتحقيق الحياد الصفري ٢٠٥٠م."}], "medium": [{"type": "mcq", "q": "ما دور السفينة العُمانية «شباب عُمان الثانية» في المحيط العالمي؟", "options": ["صيد الأسماك فقط", "إغلاق الموانئ", "نقل النفط الخام فقط", "نشر رسالة الصداقة والسلام والتعريف بالتراث البحري العُماني في موانئ العالم"], "answer": 3, "why": "تجوب سفينة شباب عُمان موانئ العالم كسفيرة للسلام والثقافة."}, {"type": "mcq", "q": "تتميّز عُمان في الملاحة والتجارة العالمية بموقعها المشرف على:", "options": ["مضيق هرمز وبحر عُمان وبحر العرب", "البحر الأسود", "المحيط المتجمد الشمالي", "بحيرة فيكتوريا"], "answer": 0, "why": "إطلالتها على مضيق هرمز والمحيط الهندي تمنحها أهمية لوجستية عالمية."}, {"type": "mcq", "q": "أي قطاع مستقبلي تبرز فيه عُمان اليوم كشريك عالمي في الطاقة النظيفة؟", "options": ["قطع الغابات", "إنتاج وتصدير الهيدروجين الأخضر والطاقة الشمسية", "إلغاء الكهرباء", "حرق الفحم الحجري"], "answer": 1, "why": "تستفيد عُمان من الشمس والرياح لتصبح مركزًا عالميًا للهيدروجين الأخضر."}, {"type": "tfr", "q": "تُعد «جائزة السلطان قابوس لحماية البيئة» أول جائزة عربية عالمية تُمنح عبر اليونسكو لصون البيئة.", "answer": true, "reasons": ["تُمنح في الرياضة فقط", "أُطلقت عام ١٩٨٩م وتُمنح كل عامين للجهود البيئية المتميزة عالميًا", "أُطلقت عام ٢٠٢٥م"], "reason": 1}, {"type": "tfr", "q": "يقتصر دور عُمان في الأمم المتحدة على حضور الاجتماعات دون المشاركة في الوكالات المتخصصة.", "answer": false, "reasons": ["ليست عضوًا في اليونسكو", "لا تشارك في أي وكالة", "بل تشارك بفاعلية في اليونسكو ومنظمة الصحة العالمية واليونيسف والجهود الإنسانية"], "reason": 2}, {"type": "essay", "q": "اشرح كيف يعزّز إدراج المواقع العُمانية في قائمة التراث العالمي لليونسكو مكانة السلطنة عالميًا.", "model": "يؤكد عمق الحضارة العُمانية وتنوّعها (قلاع وأفلاج ومدن تجارية ولبان)، ويجذب السياحة الثقافية العالمية، ويوفّر حمايةً دوليةً لهذه الكنوز الإنسانية."}, {"type": "essay", "q": "اذكر مثالين على إسهام سلطنة عُمان في «الأمن والسلم والعمل الإنساني» على المستوى الدولي.", "model": "١) الوساطة الدبلوماسية الهادئة لتقريب وجهات النظر وحل النزاعات بالحوار. ٢) الجهود الإنسانية في إطلاق المحتجزين وإرسال المساعدات الإغاثية."}], "hard": [{"type": "mcq", "q": "كيف يترابط «الموقع الجغرافي العُماني» مع «السياسة الخارجية المتوازنة» في دعم اقتصاد السلطنة؟", "options": ["لا علاقة بين السياسة والاقتصاد", "العزلة تزيد الاستثمار", "الاستقرار والسلام يجعلان الموانئ والمناطق الاقتصادية العُمانية وجهةً آمنةً وجاذبةً للاستثمار والتجارة العالمية", "النزاعات تجذب السفن"], "answer": 2, "why": "الأمن والسمعة الدولية الطيبة يعززان الثقة الاستثمارية والتجارية."}, {"type": "mcq", "q": "ما القاسم المشترك بين إدراج «الأفلاج العُمانية» و«أرض اللبان» في اليونسكو؟", "options": ["كلاهما في قارة أوروبا", "كلاهما مبانٍ حديثة", "كلاهما مشاريع نفطية", "كلاهما يوثّق عبقرية الإنسان العُماني في التكيّف مع البيئة والتجارة العالمية قديمًا"], "answer": 3, "why": "الأفلاج إبداع في إدارة المياه، وأرض اللبان شريان تجاري عالمي قديم."}, {"type": "mcq", "q": "تنسجم مشاريع «الهيدروجين الأخضر» في عُمان مع أهداف الأمم المتحدة لـ:", "options": ["التنمية المستدامة ومكافحة تغيّر المناخ والطاقة النظيفة", "زيادة الانبعاثات الكربونية", "الاعتماد على الفحم فقط", "إغلاق المصانع"], "answer": 0, "why": "الهيدروجين الأخضر طاقة نظيفة تدعم أهداف المناخ العالمية."}, {"type": "mcq", "q": "لماذا تُعد مشاركة عُمان في معارض «إكسبو» العالمية فرصةً استراتيجيةً؟", "options": ["لمنافسة المدارس", "للتعريف بالهوية العُمانية العصرية وجذب الاستثمارات والسياحة والشراكات العلمية", "للترفيه فقط دون أهداف", "لإغلاق الأسواق"], "answer": 1, "why": "معارض إكسبو منصة عالمية للتبادل الثقافي والاقتصادي."}, {"type": "tfr", "q": "تعتمد عُمان على سياسة «الحياد الإيجابي» التي تعني التواصل البنّاء مع جميع الأطراف لا الانعزال عن العالم.", "answer": true, "reasons": ["فهي تبني صداقات متوازنة وتبادر للوساطة الإنسانية والسلمية", "الحياد يعني قطع العلاقات", "لا تشارك في المنظمات الدولية"], "reason": 0}, {"type": "tfr", "q": "إسهام عُمان في تسجيل عناصر من «التراث الثقافي غير المادي» باليونسكو (كالبرعة والرزفة والخنجر العُماني والقهوة) يحمي الهوية الوطنية عالميًا.", "answer": true, "reasons": ["لا توجد عناصر غير مادية مسجّلة", "فيوثّق الفنون والعادات العُمانية الأصيلة ضمن التراث الإنساني المشترك", "يقتصر التسجيل على المباني فقط"], "reason": 1}, {"type": "tfr", "q": "تقتصر علاقات عُمان الاقتصادية العالمية على الدول المجاورة فقط.", "answer": false, "reasons": ["لا تملك موانئ دولية", "لا تتعامل مع آسيا", "ترتبط عُمان بشراكات تجارية واستثمارية وملاحية واسعة مع آسيا وأفريقيا وأوروبا والأمريكتين"], "reason": 2}, {"type": "essay", "q": "قارن بين دور عُمان في «محيطها الإسلامي» ودورها في «محيطها العالمي» مبيّنًا القيم المشتركة بينهما.", "model": "في محيطها الإسلامي تنشط عبر منظمة التعاون الإسلامي والإيسيسكو ونشر التسامح؛ وفي محيطها العالمي تنشط عبر الأمم المتحدة واليونسكو وحماية البيئة والتجارة؛ والقيم المشتركة هي السلام، والحوار، والتعايش، والتعاون الإنساني."}, {"type": "essay", "q": "اقترح فكرةً لمشروع طلابي يعرّف زوّار عُمان بمواقع التراث العالمي الخمسة في السلطنة.", "model": "إنشاء خريطة تفاعلية رقمية (بالعربية والإنجليزية) على موقع المدرسة تعرض كل موقع (قلعة بهلاء، بات، أرض اللبان، الأفلاج، قلهات) مع نبذة تاريخية وأقرب مسار سياحي."}, {"type": "essay", "q": "لماذا حظيت «جائزة السلطان قابوس لحماية البيئة» باحترام عالمي واسع منذ عام ١٩٨٩م؟", "model": "لأنها مبادرة رائدة مبكرة ربطت بين الإرث العُماني في احترام البيئة وبين منظمة اليونسكو العالمية لتشجيع العلماء والمؤسسات على حماية كوكب الأرض."}]}},
  {"id": "g4-social-1-u1-1", "grade": "g4", "subject": "social", "term": 1, "unit": 1, "no": 1, "title": "أنا أُجيد", "summary": "شرح متحرك بـ SVG لدرس أنا أُجيد للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-i-am-good-at.html", "video": "", "pdf": "", "notes": ["الموهبة هي قدرة فطرية مميزة يمتلكها الإنسان في مجال معيّن مثل الرسم أو القراءة أو الرياضة أو الإلقاء.", "يختلف الناس في مواهبهم ومهاراتهم، وهذا التنوع يجعل المجتمع متكاملًا وغنيًا.", "أكتشف ما أُجيده من خلال تجربة أنشطة مختلفة وملاحظة ما أستمتع به وأتقنه بسهولة.", "آراء الوالدين والمعلمين والأصدقاء تساعدني على اكتشاف نقاط قوتي ومواهبي.", "احترام مواهب الآخرين وتشجيعهم سلوك إيجابي يعزز الثقة بالنفس."], "exercises": ["اذكر ثلاث مواهب أو مهارات يمكن أن يمتلكها طلاب الصف الرابع.", "كيف يمكنك اكتشاف الموهبة التي تجيدها في المدرسة أو البيت؟", "لماذا يُعدّ اختلاف المواهب بين زملاء الصف أمرًا مفيدًا للجميع؟"], "levels": {"easy": [{"type": "mcq", "q": "القدرة الفطرية المميزة التي يتقنها الإنسان ويستمتع بها تُسمّى:", "options": ["الموهبة", "الإهمال", "التقليد", "الكسل"], "answer": 0, "why": "الموهبة هي القدرة المميزة في مجال معيّن."}, {"type": "mcq", "q": "من أمثلة المواهب الفنية:", "options": ["كرة القدم", "الرسم والخط العربي", "حل المعادلات", "الجري السريع"], "answer": 1, "why": "الرسم والخط العربي من المواهب الفنية."}, {"type": "mcq", "q": "يساعدني على اكتشاف موهبتي:", "options": ["الانعزال التام", "تجاهل الأنشطة", "المشاركة في الأنشطة المدرسية", "عدم المحاولة"], "answer": 2, "why": "المشاركة في الأنشطة تكشف ما أجيده."}, {"type": "mcq", "q": "تنوع المواهب بين طلاب الصف يؤدي إلى:", "options": ["الخلاف الدائم", "ضعف التعاون", "ضياع الوقت", "التكامل والإبداع"], "answer": 3, "why": "اختلاف المواهب يجعل الفريق متكاملًا."}], "medium": [{"type": "mcq", "q": "طالب يجيد تنسيق الكلمات وإلقاء الشعر في الإذاعة المدرسية؛ تُصنّف موهبته ضمن المواهب:", "options": ["الأدبية", "الرياضية", "اليدوية", "الكيميائية"], "answer": 0, "why": "الإلقاء والشعر من المواهب الأدبية."}, {"type": "tfr", "q": "يقتصر مفهوم الموهبة على المواد الدراسية فقط مثل الرياضيات والعلوم.", "answer": false, "reasons": ["لا توجد مواهب رياضية", "الموهبة توجد في الحساب فقط", "المواهب تشمل مجالات متعددة كالفن والرياضة والأدب والعمل الاجتماعي"], "reason": 2}, {"type": "essay", "q": "اذكر طريقتين تساعدانك على اكتشاف الموهبة التي تجيدها.", "model": "١) تجربة أنشطة مدرسية ومنزلية متنوعة وملاحظة ما أستمتع به وأتقنه. ٢) الاستماع لآراء والديّ ومعلميّ حول نقاط قوّتي."}, {"type": "tfr", "q": "اختلاف المواهب بين أفراد المجتمع أمر إيجابي ومفيد.", "answer": true, "reasons": ["لأن كل فرد يسدّ حاجة مختلفة فيتكامل المجتمع", "لأنه يمنع الناس من العمل معًا", "لأن الجميع يجب أن يتشابهوا"], "reason": 0}, {"type": "mcq", "q": "في مشروع مجلة مدرسية، يتكامل الطلاب عندما:", "options": ["يعمل طالب واحد بكل شيء", "يؤجلون العمل دائمًا", "يتنافسون على إفساد العمل", "يوزّعون المهام حسب موهبة كل طالب"], "answer": 3, "why": "توزيع المهام حسب المواهب يحقق أفضل نتيجة."}, {"type": "essay", "q": "كيف تشكر الله تعالى على الموهبة التي وهبك إياها؟", "model": "أشكر الله عليها بالمحافظة عليها وتنميتها واستخدامها في نفع نفسي وأسرتي ومجتمعي دون غرور."}, {"type": "tfr", "q": "من الجيد أن أُقلّد هواية صديقي حتى لو لم أستمتع بها.", "answer": false, "reasons": ["لا يجوز أن تختلف الهوايات", "التقليد الأعمى يصنع الموهبة", "ينبغي لكل طالب أن يكتشف تميّزه الخاص وما يناسب قدراته"], "reason": 2}], "hard": [{"type": "mcq", "q": "شعر خالد بالحزن لأنه لا يجيد الرسم مثل صديقه، لكنه بارع جدًا في ترتيب القصص وحفظها؛ ما النصيحة الأنسب له؟", "options": ["أن يترك المدرسة", "أن يكتشف ويطوّر موهبته الأدبية الخاصة ولا يقارن نفسه سلبيًا", "أن يمنع صديقه من الرسم", "أن يظن أنه بلا موهبة"], "answer": 1, "why": "لكل شخص مجال يبدع فيه، والمقارنة السلبية تُضعف الثقة."}, {"type": "essay", "q": "وضّح بمثال من بيئتك المدرسية كيف يحقق تنوّع المواهب نجاحًا جماعيًا.", "model": "عند إعداد إذاعة عن اليوم الوطني: طالب يكتب الفقرات، وآخر يُلقيها بصوت واضح، وثالث يُعدّ لوحةً فنيةً للمسرح، فينجح الحفل بتكامل الجميع."}, {"type": "tfr", "q": "الغرور بالموهبة والاستهزاء بالآخرين يرفع من قيمة الموهوب بين زملائه.", "answer": false, "reasons": ["الغرور ضروري للنجاح", "الغرور يُنفّر الآخرين، بينما التواضع والتشجيع يرفعان قدر الموهوب", "التواضع يُضعف الموهبة"], "reason": 1}, {"type": "mcq", "q": "أيّ عبارة تُعبّر بدقة عن العلاقة بين الموهبة والخبرة؟", "options": ["الموهبة تظهر تلقائيًا دون أي تجربة", "الأنشطة المدرسية تُخفي المواهب", "الموهبة لا تحتاج لاكتشاف", "التجربة المتنوعة تكشف الموهبة الكامنة وتُبرزها"], "answer": 3, "why": "خوض التجارب المتنوعة هو المفتاح لاكتشاف القدرات الكامنة."}, {"type": "essay", "q": "لماذا يُعدّ رأي المعلم والوالدين مهمًا في اكتشاف مواهب الطفل؟", "model": "لأنهما يراقبان سلوك الطفل وأداءه اليومي بموضوعية، ويلاحظان قدرات قد لا ينتبه إليها الطفل بنفسه."}, {"type": "tfr", "q": "يمكن للإنسان أن يمتلك أكثر من موهبة واحدة في حياته.", "answer": true, "reasons": ["قد يجمع الشخص بين موهبة علمية وموهبة فنية أو رياضية في الوقت نفسه", "لا يُسمح إلا بموهبة واحدة", "المواهب تلغي بعضها"], "reason": 0}, {"type": "mcq", "q": "إذا طُلب من صفك تنظيم حملة نظافة، فكيف توظّف تنوّع مواهب زملائك؟", "options": ["جعل الجميع يرسمون فقط", "تكليف الموهوبين بالرسم بعمل الملصقات، والمتحدثين بالتوعية، والمنظمين بتوزيع المهام", "العمل بعشوائية دون خطة", "الاستغناء عن نصف الصف"], "answer": 1, "why": "توزيع الأدوار وفق المواهب يرفع كفاءة الحملة وجودتها."}, {"type": "essay", "q": "فرّق بين الثقة بالموهبة والغرور بها.", "model": "الثقة بالموهبة تعني معرفة قدراتي وتقديرها مع احترام الآخرين ومساعدتهم، أما الغرور فيعني التكبر على الآخرين والتقليل من شأنهم."}, {"type": "tfr", "q": "عدم إتقان مهارة من أول محاولة يعني أنني لا أملك أي موهبة فيها.", "answer": false, "reasons": ["الموهوب لا يخطئ أبدًا", "أول محاولة تحدد المصير دائمًا", "كثير من المواهب تحتاج لمحاولات وتجارب متكررة حتى تظهر بوضوح"], "reason": 2}, {"type": "essay", "q": "صمّم خطةً صغيرة من ثلاث خطوات تساعد زميلًا جديدًا في صفك على اكتشاف ما يُجيده.", "model": "١) أدعوه لتجربة ٣ أنشطة مختلفة هذا الأسبوع. ٢) أسأله عن النشاط الذي استمتع به أكثر. ٣) أشاركه ملاحظاتي الإيجابية وأشجّعه على عرض عمله للمعلم."}]}},
  {"id": "g4-social-1-u1-2", "grade": "g4", "subject": "social", "term": 1, "unit": 1, "no": 2, "title": "أُنمّي ما أُجيد", "summary": "شرح متحرك بـ SVG لدرس أُنمّي ما أُجيد للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-develop-my-talent.html", "video": "", "pdf": "", "notes": ["الموهبة وحدها لا تكفي للتميّز؛ بل تحتاج إلى تدريب مستمر وممارسة يومية لتنمو وتكبر.", "من طرائق تنمية الموهبة: القراءة، والانضمام للأنشطة المدرسية، والتدرّب تحت إشراف معلم أو مدرب.", "تنظيم الوقت بين الدراسة وتنمية الموهبة والراحة يحقق التوازن والنجاح.", "المثابرة وعدم اليأس عند الخطأ جزء أساسي من تطوير أي مهارة.", "توفّر المدرسة والأسرة والمجتمع في عُمان بيئات داعمة لتنمية مواهب الطلبة."], "exercises": ["لماذا لا تكفي الموهبة وحدها دون تدريب وممارسة؟", "اذكر ثلاث طرائق عملية لتنمية موهبة الرسم أو الإلقاء.", "كيف توازن بين واجباتك الدراسية وتنمية موهبتك يوميًا؟"], "levels": {"easy": [{"type": "mcq", "q": "لتنمو الموهبة وتتطور فإنها تحتاج إلى:", "options": ["الإهمال", "التوقف عن التعلم", "النوم الطويل", "التدريب والممارسة المستمرة"], "answer": 3, "why": "التدريب المستمر هو أساس تنمية الموهبة."}, {"type": "mcq", "q": "تخصيص وقت للواجبات ووقت للموهبة يُسمّى:", "options": ["تنظيم الوقت", "إضاعة الوقت", "التأجيل", "الفوضى"], "answer": 0, "why": "تنظيم الوقت يوازن بين الدراسة والموهبة."}, {"type": "mcq", "q": "عدم الاستسلام عند مواجهة صعوبة أثناء التدرّب يُسمّى:", "options": ["اليأس", "المثابرة", "الخجل", "التكاسل"], "answer": 1, "why": "المثابرة تعني الاستمرار في المحاولة حتى النجاح."}, {"type": "mcq", "q": "يمكنني تنمية موهبتي في المدرسة من خلال:", "options": ["عدم المشاركة", "إخفاء مهاراتي", "الانضمام لجماعات الأنشطة المدرسية", "الغياب المستمر"], "answer": 2, "why": "جماعات الأنشطة المدرسية بيئة ممتازة لتنمية المواهب."}], "medium": [{"type": "mcq", "q": "أيّ خطوة تُعدّ الأفضل لطالبة تُجيد الخط العربي وتريد تطويره؟", "options": ["الكتابة مرة واحدة في السنة", "ترك الدروس المدرسية", "التوقف عن التدريب لأنها موهوبة", "التدرّب يوميًا ١٥ دقيقة وعرض خطوطها على معلمة الفنون"], "answer": 3, "why": "التدريب اليومي المنظم مع توجيه المعلم يطوّر المهارة سريعًا."}, {"type": "tfr", "q": "الموهبة الفطرية كافية وحدها للوصول إلى التميّز دون أي تدريب.", "answer": false, "reasons": ["التدريب يُضعف الموهبة", "الموهوب لا يحتاج للتدريب أبدًا", "الموهبة تحتاج للتدريب المستمر والممارسة حتى تصل للإتقان"], "reason": 2}, {"type": "essay", "q": "اذكر ثلاث وسائل تساعدك على تنمية موهبتك.", "model": "١) التدريب اليومي المنظم. ٢) الانضمام لجماعات الأنشطة المدرسية. ٣) الاستفادة من توجيهات المعلمين والقراءة في مجال الموهبة."}, {"type": "tfr", "q": "تنظيم الوقت يسمح للطالب بالتفوق الدراسي وتنمية موهبته معًا.", "answer": true, "reasons": ["لأن توزيع الساعات يمنح كل مهمة حقها دون تقصير", "لأنه يلغي وقت الدراسة", "لأنه يمنع ممارسة الهوايات"], "reason": 0}, {"type": "mcq", "q": "وضع هدف أسبوعي صغير مثل «قراءة قصتين» يساعد على:", "options": ["الشعور بالملل", "تضييع الوقت", "قياس التقدّم والتحفيز للاستمرار", "ترك القراءة"], "answer": 2, "why": "الأهداف الصغيرة الواضحة تسهل المتابعة وتزيد الحماس."}, {"type": "essay", "q": "ماذا تفعل إذا أخطأت عدة مرات أثناء تعلّم مهارة جديدة؟", "model": "لا أيأس؛ بل أكتشف سبب الخطأ، وأطلب نصيحة معلمي أو والدي، وأعيد المحاولة بصبر ومثابرة حتى أتقنها."}, {"type": "tfr", "q": "المشاركة في المسابقات المدرسية تُكسب الطالب خبرةً وثقةً بنفسه.", "answer": true, "reasons": ["لأنها لا علاقة لها بالمواهب", "لأنها تسبب الخوف فقط", "لأنها تتيح له عرض موهبته والتعلم من تجارب الآخرين"], "reason": 2}], "hard": [{"type": "mcq", "q": "طالبان يمتلكان نفس الموهبة في السباحة؛ الأول يتدرّب بانتظام ويستمع لمدربه، والثاني يعتمد على موهبته فقط. بعد عام واحد، من سيكون أكثر إتقانًا ولماذا؟", "options": ["الأول لأن التدريب المنتظم والتوجيه يصقلان الموهبة ويطورانها", "الثاني لأنه لم يتعب نفسه", "كلاهما بنفس المستوى تمامًا", "لن يتعلم أي منهما"], "answer": 0, "why": "التدريب المنتظم والتوجيه المستمر يصنعان الفارق الحقيقي."}, {"type": "essay", "q": "صمّم جدولًا مسائيًا بسيطًا لطالب في الصف الرابع يوازن فيه بين الدراسة وتنمية موهبته والراحة.", "model": "بعد العودة: غداء وراحة قصيرة ← حل الواجبات والمذاكرة لمدة ساعة ← ممارسة الموهبة ٣٠ دقيقة ← وقت مع الأسرة واللعب ← النوم مبكرًا."}, {"type": "tfr", "q": "الاستفادة من ملاحظات المعلم الناقدة البناءة تُبطئ تطور الموهبة.", "answer": false, "reasons": ["النقد البناء مضر دائمًا", "الملاحظات البناءة تكشف الأخطاء مبكرًا وتختصر طريق الإتقان", "لا يجب سؤال المعلم"], "reason": 1}, {"type": "mcq", "q": "أيّ عبارة تلخّص العلاقة بين «الخطأ» و«تنمية الموهبة»؟", "options": ["الخطأ دليل على انعدام الموهبة", "يجب التوقف فور أول خطأ", "الخطأ جزء طبيعي من التعلم ووسيلة لتحسين الأداء", "المبدعون لم يخطئوا أبدًا"], "answer": 2, "why": "التعلم من الأخطاء هو طريق الإتقان والتميّز."}, {"type": "essay", "q": "كيف تسهم المدرسة العُمانية في رعاية وتنمية مواهب الطلبة؟", "model": "من خلال جماعات الأنشطة (كالفنون والإذاعة والرياضة والابتكار)، وتنظيم المسابقات، وتوجيه المعلمين، وتكريم الموهوبين في طابور الصباح."}, {"type": "tfr", "q": "تشبيه الموهبة بالفسيلة التي تحتاج للماء والعناية تشبيه دقيق.", "answer": true, "reasons": ["لأن كليهما يبدأ صغيرًا وينمو بالرعاية المستمرة ويذبل بالإهمال", "لأن الفسيلة لا تحتاج ماء", "لأن الموهبة لا تنمو أبدًا"], "reason": 0}, {"type": "mcq", "q": "قررت مريم تنمية موهبتها في حفظ الشعر؛ أي خطة هي الأكثر واقعية واستمرارية؟", "options": ["حفظ ٣ أبيات يوميًا ومراجعتها نهاية الأسبوع", "حفظ ١٠٠ بيت في ليلة واحدة", "ترك الحفظ حتى ليلة المسابقة", "الاعتماد على الحظ"], "answer": 0, "why": "التدرّج اليومي المنتظم يضمن الحفظ المتقن دون إرهاق."}, {"type": "essay", "q": "لماذا يُعدّ التوازن بين الموهبة والدراسة ضروريًا لطالب الصف الرابع؟", "model": "لأن الدراسة تبني الأساس العلمي والمعرفي للطالب، والموهبة تنمّي شخصيته وإبداعه، والجمع بينهما دون إفراط يصنع طالبًا متميزًا."}, {"type": "tfr", "q": "يمكن تنمية الموهبة بالمشاهدة فقط دون ممارسة عملية.", "answer": false, "reasons": ["التطبيق العملي غير مهم", "المشاهدة تغني عن التطبيق", "المشاهدة تفيد في التعلم النظري لكن الإتقان لا يتحقق إلا بالممارسة الفعلية"], "reason": 2}, {"type": "essay", "q": "اكتب رسالة قصيرة تشجّع فيها صديقك الذي شعر بالإحباط لأنه لم يفز في أول مسابقة شارك فيها.", "model": "صديقي العزيز، مشاركتك الأولى خطوة شجاعة وتجربة ثمينة؛ الفوز الحقيقي هو ما تعلّمته اليوم. واصل التدريب وسأفرح بنجاحك في المسابقة القادمة!"}]}},
  {"id": "g4-social-1-u1-3", "grade": "g4", "subject": "social", "term": 1, "unit": 1, "no": 3, "title": "أستفيد ممّا أُجيد", "summary": "شرح متحرك بـ SVG لدرس أستفيد ممّا أُجيد للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-benefit-from-my-talent.html", "video": "", "pdf": "", "notes": ["الاستفادة من الموهبة تعني توظيفها فيما ينفعني وينفع أسرتي ومدرستي ومجتمعي.", "يمكن استثمار الموهبة في المساعدة الدراسية، أو التوعية، أو صنع منتجات مفيدة، أو إسعاد الآخرين.", "استثمار الموهبة يعزز الشعور بالمسؤولية والاعتماد على النفس والإنتاجية منذ الصغر.", "ينبغي أن تُستخدم الموهبة في الخير والأعمال النافعة والابتعاد عمّا يضر الآخرين.", "مشاركة الموهبة مع الآخرين تُضاعف أثرها وتنشر الفائدة في المجتمع."], "exercises": ["كيف يمكن لطالب يجيد الرسم أن يفيد مدرسته بموهبته؟", "اذكر فائدتين تعودان عليك عندما تستثمر ما تُجيده في أعمال نافعة.", "ما الضابط الأخلاقي المهم عند استخدام مواهبنا ومهاراتنا؟"], "levels": {"easy": [{"type": "mcq", "q": "تحويل الموهبة إلى عمل نافع لي وللآخرين يُسمّى:", "options": ["نسيان الموهبة", "إهمال الموهبة", "استثمار الموهبة", "إخفاء الموهبة"], "answer": 2, "why": "استثمار الموهبة يعني الاستفادة العملية منها."}, {"type": "mcq", "q": "من أمثلة الاستفادة من موهبة القراءة والإلقاء:", "options": ["إزعاج الصف", "السكوت الدائم", "تمزيق الكتب", "تقديم فقرات الإذاعة المدرسية"], "answer": 3, "why": "الإذاعة المدرسية توظيف نافع لموهبة الإلقاء."}, {"type": "mcq", "q": "عندما أعلّم زميلي مهارةً أجيدها فإن ذلك:", "options": ["يُضاعف الفائدة ويعزز التعاون", "يُضعف مهارتي", "يضيع وقتي", "يقلل من إتقاني"], "answer": 0, "why": "تعليم الآخرين يرسخ المهارة وينشر الخير."}, {"type": "mcq", "q": "ينبغي استخدام المواهب دائمًا في:", "options": ["إيذاء الآخرين", "الخير ونفع المجتمع", "الغرور", "إضاعة الوقت"], "answer": 1, "why": "الخير والنفع هما الغاية من كل موهبة."}], "medium": [{"type": "mcq", "q": "أحمد يُجيد استخدام الحاسوب؛ أي تصرف يُعدّ استثمارًا إيجابيًا لموهبته؟", "options": ["إزعاج زملائه برسائل غير مفيدة", "اللعب لساعات طويلة وإهمال واجباته", "تصميم بطاقات توعية عن ترشيد الماء", "العبث بملفات غيره"], "answer": 2, "why": "تصميم بطاقات التوعية يوظّف الموهبة لخدمة المجتمع."}, {"type": "tfr", "q": "لا يمكن لطالب الصف الرابع الاستفادة من موهبته إلا بعد أن يكبر ويصبح موظفًا.", "answer": false, "reasons": ["الموهبة لا تظهر إلا بعد الجامعة", "الأطفال لا يستطيعون إفادة أحد", "يمكن للطالب استثمار موهبته منذ الصغر في البيت والمدرسة"], "reason": 2}, {"type": "essay", "q": "اقترح فكرتين يمكن لطالب يُجيد الأعمال اليدوية أن يفيد بهما أسرته أو مدرسته.", "model": "١) صنع منظمات للأقلام من مواد مُعاد تدويرها لمكتب الأسرة. ٢) تصميم وسائل تعليمية بسيطة لغرفة الصف."}, {"type": "tfr", "q": "استثمار الموهبة في وقت الفراغ يحمي الطالب من الملل وإضاعة الوقت.", "answer": true, "reasons": ["لأنه يشغل وقته بأنشطة ممتعة ومفيدة وتنتج أثرًا إيجابيًا", "لأن الموهبة تسبب الملل", "لأن وقت الفراغ يجب أن يُهدر"], "reason": 0}, {"type": "mcq", "q": "مشاركة سارة لفواصل الكتب مع زميلاتها في المكتبة حققت:", "options": ["إخفاء موهبتها", "نفعًا للآخرين وتشجيعًا على القراءة", "خسارة مهارتها", "توقفها عن الخط العربي"], "answer": 1, "why": "فواصل الكتب الجميلة تشجّع الزميلات على القراءة."}, {"type": "essay", "q": "كيف تعود مساعدة زميلك بمهارتك بالفائدة عليك أنت أيضًا؟", "model": "تزيد من إتقاني للمهارة، وتقوّي ثقتي بنفسي، وتبني صداقة طيبة، وتنشر روح التعاون في الصف."}, {"type": "tfr", "q": "توظيف الموهبة في السخرية من الآخرين يُعدّ استثمارًا ناجحًا لها.", "answer": false, "reasons": ["لا توجد ضوابط أخلاقية للموهبة", "السخرية دليل إبداع", "الموهبة أمانة يجب استخدامها في الخير وإسعاد الناس لا إيذائهم"], "reason": 2}], "hard": [{"type": "mcq", "q": "أكمل التسلسل الصحيح لرحلة الموهبة في الوحدة الأولى:", "options": ["أستفيد ← أهمل ← أكتشف", "أخفي ← أتدرب ← أترك", "أقلّد ← أستفيد ← أتوقف", "أكتشف ما أُجيد ← أُنمّي ما أُجيد ← أستفيد ممّا أُجيد"], "answer": 3, "why": "تبدأ الرحلة بالاكتشاف، ثم التنمية، ثم الاستثمار النافع."}, {"type": "essay", "q": "اربط بين موهبة تمتلكها أنت (أو تتمناها) وكيف يمكن أن تخدم بها مجتمعك المدرسي هذا الفصل.", "model": "مثال: إذا كنت أجيد الرسم، أصمّم ملصقات ملونة لتشجيع زملائي على المحافظة على نظافة الساحة وترشيد استهلاك الماء."}, {"type": "tfr", "q": "الأفكار الطلابية البسيطة في استثمار المواهب قد تكون بذرةً لمشاريع مستقبلية ناجحة.", "answer": true, "reasons": ["لأن أفكار الصغار بلا قيمة", "لأنها تُدرّب الطالب مبكرًا على التخطيط والإنتاج وتحمّل المسؤولية", "لأن المشاريع لا تحتاج موهبة"], "reason": 1}, {"type": "mcq", "q": "طالبة تجيد كتابة القصص القصيرة، وتريد إفادة أطفال الصف الأول؛ ما أنسب مبادرة لها؟", "options": ["الاحتفاظ بقصصها في الدرج المغلق", "كتابة قصة مصوّرة بسيطة عن النظافة وقراءتها لهم في وقت الفسحة", "كتابة نصوص صعبة جدًا لا يفهمونها", "التوقف عن الكتابة"], "answer": 1, "why": "ملاءمة القصة لعمر المستفيدين يجعل الموهبة أكثر نفعًا وتأثيرًا."}, {"type": "essay", "q": "ما الفرق بين طالب يكتفي بالتفاخر بموهبته وطالب يستثمرها لخدمة الآخرين؟", "model": "المتفاخر لا يترك أثرًا نافعًا وقد يُنفّر زملاءه، أما المستثمر لموهبته فيُنتج أعمالًا مفيدة ويكسب محبة الجميع ويزداد إتقانًا."}, {"type": "tfr", "q": "إعادة تدوير الكرتون لصنع مجسمات تعليمية يجمع بين الموهبة وحماية البيئة.", "answer": true, "reasons": ["لأنه يوظف المهارة اليدوية في عمل مفيد ويقلل النفايات في الوقت نفسه", "لأن إعادة التدوير لا علاقة لها بالبيئة", "لأن المجسمات لا تفيد التعلم"], "reason": 0}, {"type": "mcq", "q": "عندما يواجه صفّك مشكلة تأخر بعض الطلاب عن طابور الصباح، كيف يوظف طالبٌ موهوبٌ في التصميم موهبته لحلّها؟", "options": ["الغياب عن الطابور", "السخرية من المتأخرين برسوم مزعجة", "تجاهل المشكلة تمامًا", "تصميم لوحة تشجيعية محفّزة للانضباط والالتزام بالوقت"], "answer": 3, "why": "التحفيز الإيجابي بالتصميم يعالج المشكلة بأسلوب راقٍ ومفيد."}, {"type": "essay", "q": "كيف تشجّع الأسرة أبناءها على الاستفادة ممّا يُجيدونه؟", "model": "بتقدير أعمالهم وعرضها في البيت، وإشراكهم في مهام تناسب مهاراتهم، وتشجيعهم على إهداء إنتاجهم أو المشاركة به في المعارض."}, {"type": "tfr", "q": "الاستفادة من الموهبة تعني دائمًا الحصول على المال فقط.", "answer": false, "reasons": ["التطوع بالموهبة بلا قيمة", "لا فائدة إلا بالمال", "الفائدة تشمل أيضًا إسعاد الآخرين، ونشر التوعية، ومساعدة الأسرة، والتعلم"], "reason": 2}, {"type": "essay", "q": "لخّص في ثلاث جمل كيف تكمل دروس الوحدة الأولى (أنا أُجيد، أُنمّي ما أُجيد، أستفيد ممّا أُجيد) بعضها بعضًا.", "model": "أولًا أكتشف القدرة المميزة التي وهبني الله إياها. ثانيًا أُنمّيها بالتدريب المستمر وتنظيم الوقت. ثالثًا أُوظّفها في أعمال نافعة لي ولأسرتي ومجتمعي."}]}},
  {"id": "g4-social-1-u2-1", "grade": "g4", "subject": "social", "term": 1, "unit": 2, "no": 1, "title": "أسرتي تُجيد", "summary": "شرح متحرك بـ SVG لدرس أسرتي تُجيد للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-my-family-excels.html", "video": "", "pdf": "", "notes": ["تمتلك كل أسرة مجموعةً من المهارات والقدرات التي يُجيدها أفرادها في مجالات متعددة.", "الأسرة المنتجة هي التي تستثمر مهارات أفرادها لإنتاج سلع أو خدمات مفيدة وتعتمد على نفسها.", "من المهارات الأسرية الشائعة في عُمان: الحرف اليدوية كالسعفيات والفخار، والطبخ العُماني، والزراعة المنزلية، والخياطة، والتصميم.", "تكامل مهارات الوالدين والأبناء يصنع قوةً حقيقيةً لنجاح أي عمل أسري.", "تقدير مهارات أفراد الأسرة والفخر بعملهم الشريف قيمة وطنية وإنسانية نبيلة."], "exercises": ["اذكر ثلاث مهارات يمكن أن تجيدها الأسر العُمانية المنتجة.", "ما الفرق بين الأسرة المستهلكة والأسرة المنتجة؟", "كيف يمكنك كطالب في الصف الرابع المساهمة في دعم مهارات أسرتك؟"], "levels": {"easy": [{"type": "mcq", "q": "الأسرة التي تستثمر مهاراتها لإنتاج سلع أو خدمات مفيدة تُسمّى:", "options": ["الأسرة الكسولة", "الأسرة المنتجة", "الأسرة المستهلكة فقط", "الأسرة المتفرقة"], "answer": 1, "why": "الإنتاج واستثمار المهارات هما صفة الأسرة المنتجة."}, {"type": "mcq", "q": "من المهارات الأسرية التراثية في سلطنة عُمان:", "options": ["إهمال الزراعة", "إضاعة الوقت", "صناعة السعفيات", "عدم التعاون"], "answer": 2, "why": "صناعة السعفيات من سعف النخيل حرفة عُمانية أصيلة."}, {"type": "mcq", "q": "مشاركة الأبناء في أعمال الأسرة المناسبة لعمرهم تُعلّمهم:", "options": ["الإهمال", "التكاسل", "الأنانية", "تحمّل المسؤولية والتعاون"], "answer": 3, "why": "المشاركة الأسرية تغرس المسؤولية وروح الفريق."}, {"type": "mcq", "q": "العمل اليدوي الشريف مصدر:", "options": ["فخر وعزّة", "ضعف", "خجل", "حزن"], "answer": 0, "why": "كل عمل حلال نافع هو مصدر فخر وعزة."}], "medium": [{"type": "mcq", "q": "في أسرة سعيد: الأب يزرع النعناع والطماطم، والأم تغلّفها، وسعيد يكتب اسم المنتج على الملصقات؛ هذا يدل على:", "options": ["عدم التنظيم", "تكامل مهارات أفراد الأسرة", "اعتماد الأسرة على فرد واحد", "إهمال العمل"], "answer": 1, "why": "كل فرد أدّى دورًا يتناسب مع مهارته فتكامل العمل."}, {"type": "tfr", "q": "تقتصر مهارات الأسر المنتجة على الحرف القديمة فقط ولا تشمل المهارات الحديثة.", "answer": false, "reasons": ["لا توجد حرف تراثية", "المهارات الحديثة ممنوعة", "تشمل الحرف التراثية والمهارات الحديثة كالتصميم والتصوير والحلويات"], "reason": 2}, {"type": "essay", "q": "اذكر مثالين لمهارات أسرية تراثية ومثالين لمهارات أسرية حديثة في عُمان.", "model": "تراثية: صناعة السعفيات، تجهيز التمور أو الفخار. حديثة: التصميم الرقمي، تغليف الهدايا أو صناعة المخبوزات المنزلية."}, {"type": "tfr", "q": "الحوار الأسري يساعد على اكتشاف المهارات التي يُجيدها كل فرد في البيت.", "answer": true, "reasons": ["لأن تبادل الآراء يكشف هوايات وقدرات الأبناء والوالدين", "لأن الحوار يضيع الوقت", "لأن الأفراد لا يعرفون بعضهم"], "reason": 0}, {"type": "mcq", "q": "من فوائد الزراعة المنزلية للأسرة:", "options": ["توفير خضروات طازجة وتجميل البيت وتقليل المصاريف", "زيادة النفايات", "إضاعة الماء بلا فائدة", "إهمال الحديقة"], "answer": 0, "why": "الزراعة المنزلية نموذج رائع للإنتاج الأسري النافع."}, {"type": "essay", "q": "كيف تشجّع أسرتك على استثمار مهاراتها؟", "model": "بالتحدث معهم عن مهارات كل فرد، واقتراح فكرة بسيطة نعمل عليها معًا، والمساعدة بحماس في المهام التي تناسب عمري."}, {"type": "tfr", "q": "ينبغي على طالب الصف الرابع ألا يشارك في أي عمل أسري بحجة أنه صغير.", "answer": false, "reasons": ["المشاركة تمنع اللعب", "الأطفال لا يستطيعون المساعدة", "يمكنه المشاركة في مهام آمنة وبسيطة تناسب عمره كالتنظيم والتغليف"], "reason": 2}], "hard": [{"type": "mcq", "q": "قارن بين أسرة تشتري جميع احتياجاتها البسيطة وأسرة تصنع بعضها وتنتج للآخرين؛ ما الميزة الأبرز للأسرة الثانية؟", "options": ["عدم وجود وقت للتعاون", "زيادة الإنفاق غير الضروري", "الاعتماد على النفس وتنمية المهارات وزيادة الدخل الأسري", "فقدان المهارات"], "answer": 2, "why": "الإنتاج الأسري يعزز الاعتماد على النفس والاقتصاد الأسري."}, {"type": "essay", "q": "لماذا يُعدّ إحياء الحرف العُمانية داخل الأسرة مثل السعفيات والتطريز أمرًا مهمًا للهوية الوطنية؟", "model": "لأنه يحافظ على تراث الأجداد وينقله للأجيال الجديدة، ويُحوّله إلى مصدر دخل وفخر وطني يعكس أصالة المجتمع العُماني."}, {"type": "tfr", "q": "توزيع الأدوار داخل الأسرة المنتجة يقلل الجهد على فرد واحد ويزيد جودة الإنتاج.", "answer": true, "reasons": ["لأن العمل الفردي أفضل دائمًا", "لأن كل فرد يركز في المهمة التي يتقنها فيرتفع الإتقان ويقل الإرهاق", "لأن التعاون يبطئ العمل"], "reason": 1}, {"type": "mcq", "q": "أسرة تمتلك مزرعة نخيل صغيرة؛ ما أفضل فكرة لتحويلها إلى إنتاج أسري مميّز؟", "options": ["تنظيف التمور وتعبئتها بعبوات نظيفة وجذابة وتقديمها للسوق المحلي", "ترك التمور تتساقط دون جمع", "قطع النخيل", "عدم العناية بالري"], "answer": 0, "why": "تحسين التعبئة والنظافة يرفع قيمة المنتج الأسري."}, {"type": "essay", "q": "ما القيم الأخلاقية التي يجب أن تتحلى بها الأسرة المنتجة في عملها؟", "model": "الأمانة والصدق، وإتقان العمل والنظافة، والتعاون والاحترام بين أفراد الأسرة، والالتزام بالمواعيد."}, {"type": "tfr", "q": "الأسرة المنتجة تفيد نفسها فقط ولا تؤثر على اقتصاد الوطن.", "answer": false, "reasons": ["الأسر المنتجة توفر منتجات محلية وتنشّط السوق وتدعم الاقتصاد الوطني", "لا علاقة للأسرة بالاقتصاد", "المنتجات المحلية غير مطلوبة"], "reason": 0}, {"type": "mcq", "q": "أيّ دور يناسب طالبًا في الصف الرابع يجيد الرسم ضمن مشروع أسرته لإعداد العسل العُماني؟", "options": ["قيادة شاحنة التوصيل", "استخدام آلات ثقيلة خطرة", "المساعدة في تصميم ملصق جميل لاسم المنتج وكتابة العبارات", "إدارة الحسابات البنكية الكبرى"], "answer": 2, "why": "تصميم الملصق آمن ومناسب لعمره ويستثمر موهبته."}, {"type": "essay", "q": "كيف تسهم الأم والأب والأبناء معًا في إنجاح مشروع خياطة وتطريز منزلي؟", "model": "الأم تخيط وتطرز، والأب يوفّر الأقمشة ويسوّق المنتجات، والأبناء يساعدون في فرز الخيوط وترتيب الأكياس وكتابة بطاقات الشكر."}, {"type": "tfr", "q": "تقدير الطالب لعمل والديه البسيط يزيد من تماسك الأسرة وسعادتها.", "answer": true, "reasons": ["لأن التقدير غير مهم", "لأن العمل البسيط لا يُقدّر", "لأن الاحترام والفخر بالعمل الشريف يدعمان روح المحبة والانتماء"], "reason": 2}, {"type": "essay", "q": "تخيّل أن أسرتك تريد بدء عمل منتج؛ اكتب قائمةً بثلاث مهارات في أسرتك واذكر كيف تتكامل.", "model": "مثال: أمي تجيد إعداد البخور، وأبي يجيد التنظيم والتسويق، وأنا أجيد الخط والرسم لتزيين العلب؛ فتتكامل جهودنا في منتج جميل ومتقن."}]}},
  {"id": "g4-social-1-u2-2", "grade": "g4", "subject": "social", "term": 1, "unit": 2, "no": 2, "title": "أُخطّط لمشروع أسرتي", "summary": "شرح متحرك بـ SVG لدرس أُخطّط لمشروع أسرتي للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-plan-family-project.html", "video": "", "pdf": "", "notes": ["التخطيط هو التفكير المسبق وتحديد الخطوات اللازمة لتحقيق هدف معيّن بنجاح قبل البدء بالتنفيذ.", "خطوات التخطيط لمشروع أسري: اختيار الفكرة المناسبة، تحديد الأدوات والتكلفة، توزيع الأدوار، وتحديد الوقت وطريقة التسويق.", "يجب اختيار فكرة مشروع تناسب مهارات الأسرة وحاجة الناس في المجتمع.", "العمل بعشوائية دون تخطيط يؤدي إلى هدر الوقت والمال وضعف الجودة.", "تحديد سعر عادل ومناسب وتقديم منتج نظيف ومتقن من أسرار نجاح المشروع."], "exercises": ["رتّب خطوات التخطيط لمشروع أسري صغير من البداية حتى التنفيذ.", "لماذا نحتاج إلى حساب تكلفة الأدوات قبل بدء المشروع؟", "ما الذي يحدث إذا بدأت الأسرة مشروعها دون توزيع للأدوار؟"], "levels": {"easy": [{"type": "mcq", "q": "التفكير المسبق وترتيب الخطوات قبل البدء بالعمل يُسمّى:", "options": ["التخطيط", "العشوائية", "التأجيل", "الفوضى"], "answer": 0, "why": "التخطيط هو وضع خطة مرتبة قبل التنفيذ."}, {"type": "mcq", "q": "عند اختيار فكرة مشروع أسري يجب أن تناسب:", "options": ["الأشياء الصعبة والمستحيلة", "مهارات الأسرة وحاجة المجتمع", "ما لا يحتاجه أحد", "إضاعة المال"], "answer": 1, "why": "ملاءمة الفكرة للمهارات وحاجة السوق تضمن النجاح."}, {"type": "mcq", "q": "تحديد من يقوم بكل مهمة في المشروع يُسمّى:", "options": ["التكلفة", "التسويق", "توزيع الأدوار", "التأخير"], "answer": 2, "why": "توزيع الأدوار يوضح مسؤولية كل فرد."}, {"type": "mcq", "q": "معرفة ثمن المواد الخام قبل الشراء تساعد على:", "options": ["زيادة الخسارة", "نسيان الأدوات", "إفساد المنتج", "ضبط الميزانية"], "answer": 3, "why": "حساب التكلفة يضبط الميزانية ويمنع التبذير."}], "medium": [{"type": "mcq", "q": "ما الترتيب الصحيح لخطوات التخطيط لمشروع أسري؟", "options": ["اختيار الفكرة ← تحديد الأدوات والتكلفة ← توزيع الأدوار ← التنفيذ والتسويق", "البيع ← الفكرة ← شراء الأدوات", "التنفيذ ← التفكير بالفكرة ← توزيع الأدوار", "التغليف ← شراء المواد ← اختيار الفكرة"], "answer": 0, "why": "الخطة تبدأ بالفكرة ثم الموارد والأدوار ثم التنفيذ."}, {"type": "tfr", "q": "يمكن إنجاح أي مشروع أسري بسهولة دون الحاجة لوضع خطة مسبقة.", "answer": false, "reasons": ["العشوائية تزيد الأرباح", "التخطيط غير مهم للمشاريع الصغيرة", "العمل دون خطة يؤدي للفوضى وهدر الوقت والمال"], "reason": 2}, {"type": "essay", "q": "اذكر ثلاثة أسئلة يجب أن تُجيب عنها الأسرة عند التخطيط لمشروعها.", "model": "١) ماذا سنُنتج؟ ٢) ما الأدوات والتكلفة المطلوبة؟ ٣) ما دور كل فرد في الأسرة ومتى سنُنجز العمل؟"}, {"type": "tfr", "q": "الاهتمام بنظافة المنتج وتغليفه الجميل يزيد إقبال الناس على شرائه.", "answer": true, "reasons": ["لأن النظافة والإتقان يعكسان جودة المنتج ويكسبان ثقة المشتري", "لأن التغليف لا يهم أحدًا", "لأن الناس يفضلون الفوضى"], "reason": 0}, {"type": "mcq", "q": "اشترت أسرة مواد بمبلغ ٨ ريالات عُمانية، وأنتجت ١٠ علب؛ ما الخطوة الصحيحة لتحديد سعر البيع؟", "options": ["بيع العلبة بنصف ريال فتخسر الأسرة", "تجاهل التكلفة تمامًا", "بيع العلبة بـ ٢٠ ريالًا للمبالغة", "تحديد سعر عادل يغطي التكلفة ويحقق ربحًا معقولًا مثل ريال واحد"], "answer": 3, "why": "السعر العادل يغطي التكلفة (٠٫٨ ريال للعلبة) ويحقق ربحًا مناسبًا."}, {"type": "essay", "q": "كيف يمكن للأسرة التعريف بمنتجها (تسويقه) بطريقة صحيحة وصادقة؟", "model": "بعرضه في المعارض الأسرية والمجتمعية، وإخبار الأقارب والجيران، ووصف المنتج بصدق وأمانة مع إبراز جودته."}, {"type": "tfr", "q": "تحديد موعد واضح لإنجاز المشروع يساعد الأسرة على الالتزام والانضباط.", "answer": true, "reasons": ["لأن الوقت غير مهم", "لأنه يسبب الفوضى", "لأنه يمنع التسويف ويضمن تسليم المنتجات في وقتها"], "reason": 2}], "hard": [{"type": "mcq", "q": "بدأت أسرة مشروع عصائر طبيعية في يوم حار لكنها نسيت شراء الأكواب والأغطية؛ ما الخطوة التي قصّرت فيها؟", "options": ["اختيار المشروب", "حصر الأدوات والمواد المطلوبة في مرحلة التخطيط", "حب التعاون", "تحديد اسم الأسرة"], "answer": 1, "why": "قائمة الأدوات المسبقة تمنع نسيان المستلزمات الأساسية."}, {"type": "essay", "q": "ضع خطةً مصغّرة من ٤ نقاط لمشروع أسري لبيع «شتلات الريحان والنعناع» في حيكم.", "model": "١) الفكرة: زراعة شتلات ريحان ونعناع. ٢) الأدوات: أصص صغيرة وتربة وبذور بتكلفة تقريبية ٦ ريالات. ٣) الأدوار: الأب يجهز التربة، الأم تزرع، وأنا أسقي وأكتب بطاقات العناية. ٤) التسويق: عرضها للجيران وفي يوم الحيّ."}, {"type": "tfr", "q": "المبالغة الكبيرة في رفع سعر المنتج الأسري تضمن استمرار نجاح المشروع.", "answer": false, "reasons": ["السعر المرتفع دائمًا أفضل", "الأسعار المبالغ فيها تُنفّر المشترين، بينما السعر العادل يبني ثقة دائمة", "المشترون لا يهتمون بالسعر"], "reason": 1}, {"type": "mcq", "q": "عندما تُقارن أسرة بين فكرتين لمشروع: الأولى تحتاج آلات غالية جدًا، والثانية تعتمد على مهارة متوفرة وأدوات بسيطة؛ أيهما أنسب للبداية؟", "options": ["الأولى لأنها أكثر تعقيدًا", "ترك التخطيط تمامًا", "كلاهما غير مناسب", "الثانية لأنها واقعية وتناسب إمكانات الأسرة وتقلل المخاطرة"], "answer": 3, "why": "البدء بإمكانات واقعية ومهارة متقنة يضمن انطلاقة آمنة وناجحة."}, {"type": "essay", "q": "لماذا يُعدّ «تقييم المشروع بعد التنفيذ» خطوةً ذكيةً للتطوير في المستقبل؟", "model": "لأنه يساعد الأسرة على معرفة نقاط القوة لتعزيزها، واكتشاف الأخطاء أو ملاحظات الزبائن لتحسين المنتج في المرات القادمة."}, {"type": "tfr", "q": "يمكن أن يشارك الأطفال في وضع خطة المشروع باقتراح أسماء أو أفكار للتغليف.", "answer": true, "reasons": ["لأن إشراكهم ينمي تفكيرهم الإبداعي ويزيد حماسهم للعمل", "لأن التخطيط للكبار فقط", "لأن أفكار الأطفال غير مفيدة"], "reason": 0}, {"type": "mcq", "q": "ما العلاقة بين «الالتزام بالموعد» و«سمعة المشروع الأسري»؟", "options": ["لا توجد علاقة بينهما", "الالتزام بالموعد يبني الثقة ويجعل الزبائن يعودون للشراء مجددًا", "التأخر يزيد إعجاب الزبائن", "المواعيد للمدارس فقط"], "answer": 1, "why": "الوفاء بالمواعيد من أهم صفات المشروع الناجح."}, {"type": "essay", "q": "اذكر خطأين شائعين قد تقع فيهما أسرة تبدأ مشروعها دون تخطيط، واقترح حلًا لكل منهما.", "model": "١) شراء مواد أكثر من الحاجة ← الحل: كتابة قائمة وميزانية مسبقة. ٢) تداخل المهام وتأخر التسليم ← الحل: توزيع الأدوار وتحديد جدول زمني."}, {"type": "tfr", "q": "الصدق في وصف مكونات المنتج (مثل نوع العسل أو المكسرات) ضروري حتى لو كان المشروع صغيرًا.", "answer": true, "reasons": ["المبالغة في الوصف مقبولة", "الصدق للمتاجر الكبرى فقط", "الأمانة والصدق واجب أخلاقي وأساس الثقة في كل عمل صغير أو كبير"], "reason": 2}, {"type": "essay", "q": "اشرح مقولة «ساعة من التخطيط توفّر ساعات من التعب» بمثال من مشروع أسري.", "model": "إذا خطّطت الأسرة لمشروع المخبوزات فجهّزت قائمة المكونات ووزّعت الأدوار قبل البدء، أنجزت الطلب بسرعة ونظافة دون توقف متكرر لشراء نواقص."}]}},
  {"id": "g4-social-1-u2-3", "grade": "g4", "subject": "social", "term": 1, "unit": 2, "no": 3, "title": "أثر مشروع أسرتي", "summary": "شرح متحرك بـ SVG لدرس أثر مشروع أسرتي للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-impact-family-project.html", "video": "", "pdf": "", "notes": ["يترك المشروع الأسري آثارًا إيجابيةً مهمةً على الأسرة والمجتمع والوطن.", "أثره على الأسرة: زيادة الدخل، والاعتماد على النفس، وتقوية المحبة والتعاون بين أفرادها، وتنمية مهارات الأبناء.", "أثره على المجتمع: توفير منتجات محلية نظيفة وعالية الجودة، وإحياء الحرف العُمانية، ونشر ثقافة العمل والإنتاج.", "أثره على الوطن: دعم الاقتصاد الوطني، وتشجيع المنتج العُماني، وتحقيق أهداف التنمية المستدامة.", "دعم الأسر المنتجة بشراء منتجاتها وتشجيعها واجب مجتمعي جميل."], "exercises": ["اذكر أثرين إيجابيين للمشروع الأسري على الأسرة نفسها.", "كيف يستفيد المجتمع والوطن من نجاح المشاريع الأسرية؟", "كيف يمكنك أنت وأسرتك تشجيع الأسر المنتجة في منطقتكم؟"], "levels": {"easy": [{"type": "mcq", "q": "من الآثار المادية للمشروع الأسري على الأسرة:", "options": ["قلة التعاون", "زيادة الإسراف", "ضياع المهارات", "زيادة الدخل والقدرة على الادخار"], "answer": 3, "why": "المشروع الأسري يحسّن دخل الأسرة ويساعدها على الادخار."}, {"type": "mcq", "q": "من الآثار المعنوية للعمل المشترك في المشروع الأسري:", "options": ["تقوية المحبة والترابط الأسري", "تباعد أفراد الأسرة", "الكسل", "الخوف"], "answer": 0, "why": "التعاون الأسري يقوي المحبة والترابط."}, {"type": "mcq", "q": "دعم الأسر المنتجة يكون عن طريق:", "options": ["عدم زيارة معارضها", "شراء منتجاتها وتشجيعها", "تجاهل منتجاتها", "إحباطها"], "answer": 1, "why": "الشراء والتشجيع يدعمان استمرار الأسر المنتجة."}, {"type": "mcq", "q": "المشاريع الأسرية في عُمان تُسهم في:", "options": ["إضعاف السوق", "نسيان التراث", "دعم الاقتصاد الوطني وإحياء الحرف", "إهمال المواهب"], "answer": 2, "why": "المشاريع الأسرية تنشط الاقتصاد وتحفظ الحرف العُمانية."}], "medium": [{"type": "mcq", "q": "أيّ مما يأتي يُصنّف ضمن أثر المشروع الأسري على «الأبناء»؟", "options": ["تعلم التبذير", "ترك التعاون", "إهمال الدراسة", "اكتساب الثقة بالنفس وتعلم قيمة العمل والمسؤولية"], "answer": 3, "why": "مشاركة الأبناء تُنمّي شخصيتهم ومسؤوليتهم."}, {"type": "tfr", "q": "تقتصر فائدة المشروع الأسري على الربح المادي فقط.", "answer": false, "reasons": ["المال هو الأثر الوحيد", "لا توجد فوائد معنوية للعمل", "له فوائد معنوية واجتماعية ووطنية كبيرة بجانب الدخل المادي"], "reason": 2}, {"type": "essay", "q": "اذكر أثرين للمشروع الأسري على المجتمع المحلي.", "model": "١) توفير منتجات محلية نظيفة وموثوقة بأسعار مناسبة. ٢) نشر ثقافة العمل والإنتاج وإلهام أسر أخرى لبدء مشاريع نافعة."}, {"type": "tfr", "q": "شراء المنتجات المحلية من الأسر المنتجة يُسهم في دعم اقتصاد سلطنة عُمان.", "answer": true, "reasons": ["لأنه ينشّط السوق المحلي ويدعم الأسر العُمانية ويشجّع الإنتاج الوطني", "لأن الشراء المحلي يضر الاقتصاد", "لأن الأسر لا تحتاج دعمًا"], "reason": 0}, {"type": "mcq", "q": "عندما تُعيد أسرة إنتاج السعفيات العُمانية وتبيعها في المعرض؛ فإنها تحقق للوطن:", "options": ["إضاعة التراث", "تقليد غير مفيد", "الحفاظ على الهوية والتراث العُماني ودعم الاقتصاد", "إهمال الحرف"], "answer": 2, "why": "إنتاج الحرف التراثية يحمي الهوية الوطنية ويدعم الاقتصاد."}, {"type": "essay", "q": "كيف يتعلّم الطالب قيمة المال والادخار من خلال مشاركته في مشروع أسرته؟", "model": "عندما يرى الجهد المبذول في إنتاج السلع وحساب التكلفة والأرباح، يُدرك أن المال يأتي بالتعب والعمل، فيحافظ عليه ولا يُسرف فيه."}, {"type": "tfr", "q": "نجاح مشروع أسرة واحدة في الحي قد يُشجّع أسرًا أخرى على استثمار مهاراتها.", "answer": true, "reasons": ["لأن الأسر لا تتأثر ببعضها", "لأن النجاح يمنع الآخرين من العمل", "لأن التجارب الناجحة تمنح الآخرين الثقة وتُظهر إمكانية النجاح"], "reason": 2}], "hard": [{"type": "mcq", "q": "صنّف الأثر التالي في الدائرة المناسبة: «زيادة الصادرات المحلية من اللبان والبخور العُماني وتنشيط السياحة»:", "options": ["أثر على الوطن", "أثر فردي فقط", "أثر سلبي", "لا يُعد أثرًا"], "answer": 0, "why": "تنشيط السياحة والمنتجات الوطنية أثر مباشر على الوطن."}, {"type": "essay", "q": "قارن بين الأثر المادي والأثر المعنوي للمشروع الأسري بمثال لكل منهما.", "model": "الأثر المادي: زيادة دخل الأسرة والقدرة على الادخار (مثل توفير مبلغ لشراء مستلزمات المدرسة). الأثر المعنوي: زيادة الترابط الأسري والفخر والثقة بالنفس بين الأبناء."}, {"type": "tfr", "q": "توفير منتجات منزلية صحية ونظيفة من الأسر المنتجة يُسهم في تحسين صحة أفراد المجتمع.", "answer": true, "reasons": ["لأن الأكل المنزلي غير صحي", "لأنها تُحضّر بعناية ومكونات طبيعية معروفة المصدر", "لأن النظافة لا تؤثر على الصحة"], "reason": 1}, {"type": "mcq", "q": "نظّمت مدرستك يومًا لعرض منتجات الأسر المنتجة في الولاية؛ ما الهدف الأهم من هذه المبادرة؟", "options": ["إلغاء الدروس فقط", "المنافسة السلبية", "تعريف المجتمع بمنتجات الأسر ودعمها وغرس ثقافة الإنتاج في الطلاب", "شراء أشياء غير نافعة"], "answer": 2, "why": "المعارض المدرسية تدعم الأسر المنتجة وتُعلّم الطلاب قيمة الإنتاج."}, {"type": "essay", "q": "لماذا يُعدّ «ترابط الأسرة» من أثمن مكاسب المشروع الأسري؟", "model": "لأن المال قد يُنفق، أما المحبة والتفاهم والعمل بروح الفريق فتبقى وتصنع بيئةً أسريةً سعيدةً ومستقرة للأبناء."}, {"type": "tfr", "q": "يمكن للأسر المنتجة أن تُسهم في تقليل البطالة وخلق فرص عمل ذاتية.", "answer": true, "reasons": ["لأن المشروع الأسري يتيح لأفراد الأسرة العمل والإنتاج بأنفسهم", "لأن المشاريع الأسرية لا توفر عملًا", "لأن العمل يكون في الشركات فقط"], "reason": 0}, {"type": "mcq", "q": "زارت أسرتك مهرجانًا تراثيًا ورأيت ركنًا لأسرة تبيع فخارًا عُمانيًا متقنًا؛ ما التصرف الذي يجسّد المواطنة الإيجابية؟", "options": ["تشجيعهم بالثناء والشراء منهم إن أمكن ودعم المنتج العُماني", "التقليل من شأن عملهم", "السخرية من الأسعار بصوت عالٍ", "ترك المكان بفوضى"], "answer": 0, "why": "احترام وتشجيع الحرفيين والأسر المنتجة سلوك وطني راقٍ."}, {"type": "essay", "q": "ارسم بالكلمات «دوائر الأثر الثلاث» لمشروع أسرة تنتج عسلًا عُمانيًا طبيعيًا.", "model": "١) الأسرة: دخل حلال وتعاون وتعلم تربية النحل. ٢) المجتمع: حصول الجيران على عسل طبيعي نقي. ٣) الوطن: تعزيز سمعة العسل العُماني ودعم الاقتصاد الزراعي."}, {"type": "tfr", "q": "تتعارض المشاريع الأسرية مع رؤية التطور الحديث لسلطنة عُمان.", "answer": false, "reasons": ["الاقتصاد يعتمد على المصانع الكبرى فقط", "المشاريع الصغيرة لا تناسب التطور", "بل تدعمها وتُعد جزءًا مهمًا من ريادة الأعمال وتنويع الاقتصاد الوطني"], "reason": 2}, {"type": "essay", "q": "لخّص ما تعلمته في الوحدة الثانية (أسرتي المُنتِجة) في فقرة من ثلاث جمل مترابطة.", "model": "تكتشف الأسرة مهارات أفرادها المتنوعة وتتعاون لاستثمارها. ثم تخطّط لمشروعها بخطوات منظمة تشمل الفكرة والتكلفة والأدوار والجودة. وعند نجاحه يمتد أثره الإيجابي ليقوّي الأسرة ويخدم المجتمع ويدعم اقتصاد الوطن."}]}},
  {"id": "g4-social-1-u3-1", "grade": "g4", "subject": "social", "term": 1, "unit": 3, "no": 1, "title": "أنا متطوّع", "summary": "شرح متحرك بـ SVG لدرس أنا متطوّع للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-i-am-a-volunteer.html", "video": "", "pdf": "", "notes": ["العمل التطوّعي هو الجهد الذي يبذله الإنسان برغبته واختياره لخدمة مجتمعه دون انتظار مقابل مادي.", "المتطوّع شخص مبادر يُحب الخير، ويتعاون مع الآخرين لإسعادهم وحل مشكلات حيّه ومدرسته.", "من أمثلة التطوّع المناسبة لطلاب الصف الرابع: تنظيف ساحة المدرسة، وزراعة الشتلات، ومساعدة كبار السن، وجمع الكتب للمحتاجين.", "يعزز التطوّع روح التكافل والمحبة والانتماء للوطن، وفي عُمان له جذور أصيلة مثل «العونة».", "العمل التطوّعي يكون آمنًا ومناسبًا لعمر الطالب وتحت إشراف الأسرة أو المدرسة."], "exercises": ["عرّف العمل التطوّعي بأسلوبك الخاص.", "اذكر ثلاثة أعمال تطوعية بسيطة يمكنك القيام بها في مدرستك أو حيّك.", "ما العلاقة بين العمل التطوّعي وعادة «العونة» العُمانية الأصيلة؟"], "levels": {"easy": [{"type": "mcq", "q": "الجهد الذي يبذله الإنسان برغبته لخدمة مجتمعه دون مقابل مادي يُسمّى:", "options": ["الراحة", "البيع والشراء", "العمل التطوّعي", "المنافسة"], "answer": 2, "why": "التطوّع عطاء اختياري دون مقابل مادي."}, {"type": "mcq", "q": "من أمثلة التطوّع في المدرسة:", "options": ["إلقاء الأوراق في الساحة", "كسر الأقلام", "إزعاج الزملاء", "المشاركة في تنظيم المكتبة المدرسية"], "answer": 3, "why": "تنظيم المكتبة خدمة تطوعية مفيدة للجميع."}, {"type": "mcq", "q": "العادة العُمانية الأصيلة التي تعبّر عن التعاون والتطوّع بين أهل القرية تُسمّى:", "options": ["العونة", "الهجرة", "الخصام", "الانفراد"], "answer": 0, "why": "العونة مظهر تراثي عُماني رائع للتطوع والتكافل."}, {"type": "mcq", "q": "قبل المشاركة في عمل تطوّعي خارج البيت يجب أن:", "options": ["أخرج دون إخبار أحد", "أستأذن والديّ وألتزم بتعليمات السلامة", "أستخدم أدوات خطرة", "أتأخر حتى منتصف الليل"], "answer": 1, "why": "الاستئذان والسلامة شرطان أساسيان لتطوع الصغار."}], "medium": [{"type": "mcq", "q": "طلب المعلم متطوّعين لاستقبال طلاب الصف الأول ومساعدتهم؛ ما الصفة التي يُظهرها من يبادر لذلك؟", "options": ["الأنانية", "الكسل", "المبادرة وحب الخير والتعاون", "الخوف"], "answer": 2, "why": "المبادرة لمساعدة الصغار تجسّد روح التطوع."}, {"type": "tfr", "q": "ينتظر المتطوّع أجرًا ماليًا مقابل كل ساعة يقضيها في خدمة حيّه.", "answer": false, "reasons": ["المتطوع يفرض أجرًا", "التطوع لا يكون إلا بمقابل مالي", "العمل التطوّعي يُقدَّم دون مقابل مادي ابتغاء الأجر ونفع المجتمع"], "reason": 2}, {"type": "essay", "q": "اذكر عملين تطوّعيين يمكنك القيام بهما في حيّك السكني.", "model": "١) المشاركة مع أسرتي في تنظيف حديقة الحيّ أو المسجد. ٢) زراعة شتلات وسقيها أو جمع ملابس وقصص نظيفة للتبرع بها."}, {"type": "tfr", "q": "عادة «العونة» في المجتمع العُماني تُعدّ صورةً أصيلةً من صور العمل التطوّعي.", "answer": true, "reasons": ["لأن أهل القرية يتعاونون فيها لخدمة بعضهم دون مقابل مادي", "لأن العونة عمل تجاري", "لأنها لا علاقة لها بالتعاون"], "reason": 0}, {"type": "mcq", "q": "أيّ تصرف يتعارض مع أخلاقيات المتطوّع؟", "options": ["الابتسامة في وجه الآخرين", "التفاخر والتباهي بالمساعدة لإحراج المحتاجين", "الالتزام بالوقت", "التعاون مع الفريق"], "answer": 1, "why": "التطوع يقوم على الإخلاص والتواضع واحترام كرامة الآخرين."}, {"type": "essay", "q": "لماذا يجب أن يلتزم المتطوّع الصغير بقواعد السلامة وإشراف الكبار؟", "model": "لحماية نفسه من الإصابات والمخاطر، وضمان أن تكون مهمته مناسبةً لعمره وقدراته فينجزها بأمان ونجاح."}, {"type": "tfr", "q": "التطوّع يقتصر على تقديم المال فقط ولا يشمل تقديم الوقت أو الجهد.", "answer": false, "reasons": ["الوقت ليس له قيمة في التطوع", "التطوّع بالمال فقط", "يشمل التطوّع تقديم الوقت والجهد والمعرفة والمهارة وليس المال فقط"], "reason": 2}], "hard": [{"type": "mcq", "q": "في حملة تنظيف شاطئ صحار، أراد طالب الصف الرابع رفع قطعة حديد صدئة وحادة بيده؛ ما التصرف الصحيح؟", "options": ["رفعها بسرعة", "الطلب من صديقه الأصغر رفعها", "ترك الحملة تمامًا", "إخبار المشرف المسؤول وعدم لمس الأجسام الحادة لحماية سلامته"], "answer": 3, "why": "السلامة أولًا: الأجسام الحادة والخطرة يتعامل معها الكبار والمشرفون."}, {"type": "essay", "q": "قارن بين مجتمع ينتشر فيه التطوّع ومجتمع ينشغل فيه كل فرد بنفسه فقط.", "model": "المجتمع المتطوّع يكون نظيفًا ومترابطًا، تسوده المحبة والتكافل وتُحلّ مشكلاته سريعًا، أما المجتمع الأناني فتضعف فيه العلاقات وتتراكم المشكلات."}, {"type": "tfr", "q": "مشاركة طالب في صيانة فلج القرية مع والده بتقديم الماء للمتطوعين تُعدّ عملًا تطوّعيًا جميلًا.", "answer": true, "reasons": ["لأن تقديم الماء لا قيمة له", "لأنه يبذل جهدًا آمنًا ومناسبًا لعمره لخدمة المتطوعين وحيّه دون مقابل", "لأنه يجب أن يحمل الحجارة الثقيلة"], "reason": 1}, {"type": "mcq", "q": "ما الأثر النفسي الأبرز الذي يشعر به المتطوّع بعد إنجاز مبادرة خيرية؟", "options": ["الندم على وقته", "السعادة الداخلية والرضا والشعور بقيمته في المجتمع", "الحزن والملل", "الرغبة في العزلة"], "answer": 1, "why": "العطاء الصادق يمنح الإنسان سعادةً ورضًا عميقين."}, {"type": "essay", "q": "كيف يمكنك توظيف موهبتك التي درستها في الوحدة الأولى في عمل تطوّعي داخل مدرستك؟", "model": "مثال: إذا كنت أجيد القراءة، أتطوّع لقراءة القصص لطلاب الصف الأول في المكتبة؛ وإذا كنت أجيد الرسم، أتطوّع برسم لوحات إرشادية للمدرسة."}, {"type": "tfr", "q": "الالتزام والجدية مطلوبان في العمل التطوّعي تمامًا كما في العمل المدرسي.", "answer": true, "reasons": ["لأن الآخرين يعتمدون على المتطوّع في إنجاز المهمة بإتقان", "لأن العمل التطوّعي لا يحتاج إتقانًا", "لأن المتطوّع يعمل بلا نظام"], "reason": 0}, {"type": "mcq", "q": "أيّ موقف يُجسّد «الإخلاص في التطوّع»؟", "options": ["ترك المهمة في منتصفها", "العمل فقط عند التقاط الصور", "الشكوى المستمرة أثناء العمل", "تنظيف المصلى المدرسي بجدّ سواء رآك المعلم أم لم يرك"], "answer": 3, "why": "الإخلاص يعني إتقان الخير لله وللمجتمع لا للظهور فقط."}, {"type": "essay", "q": "لماذا يُعدّ التطوّع مظهرًا مهمًا من مظاهر المواطنة الصالحة؟", "model": "لأن المواطن الصالح يشعر بالمسؤولية تجاه وطنه ومجتمعه، فيبادر لخدمته والمحافظة على مرافقه ومساعدة أهله دون انتظار مقابل."}, {"type": "tfr", "q": "الأعمال التطوّعية الصغيرة مثل إماطة الأذى عن الطريق لها قيمة وأثر كبير.", "answer": true, "reasons": ["لأن التطوّع يحتاج حملات ضخمة فقط", "لأن الأعمال الصغيرة لا تؤثر", "لأنها تحمي الناس من الأذى وتنشر النظافة وتُعد صدقة عظيمة"], "reason": 2}, {"type": "essay", "q": "اقترح فكرة مبادرة تطوّعية بسيطة لصفك بعنوان «مدرستي أجمل»، واذكر كيف تشارك فيها.", "model": "مبادرة لتزيين ممرات المدرسة بأصص نباتات طبيعية: نجمع الأصص ونزرع الشتلات ونوزّع جدولًا يوميًا لسقيها والمحافظة عليها."}]}},
  {"id": "g4-social-1-u3-2", "grade": "g4", "subject": "social", "term": 1, "unit": 3, "no": 2, "title": "أُخطّط للعمل التطوّعي", "summary": "شرح متحرك بـ SVG لدرس أُخطّط للعمل التطوّعي للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-plan-volunteer-work.html", "video": "", "pdf": "", "notes": ["العمل التطوّعي الناجح يحتاج إلى تخطيط منظم وليس مجرد حماسٍ عشوائي.", "خطوات التخطيط للعمل التطوّعي: تحديد الحاجة في الحي أو المدرسة، تحديد الهدف، تشكيل الفريق وتوزيع المهام، تحديد الوقت والمكان والأدوات، ثم التنفيذ والتقييم.", "التنسيق مع إدارة المدرسة أو الأسرة أو الفرق التطوّعية الرسمية يضمن نجاح المبادرة وسلامتها.", "تحديد المستفيدين بدقة يضمن وصول المساعدة لمن يحتاجها فعلًا.", "بعد الانتهاء نُقيّم المبادرة لنعرف ما نجح فيها وما يمكن تحسينه مستقبلًا."], "exercises": ["لماذا يحتاج العمل التطوّعي إلى تخطيط مسبق؟", "رتّب خطوات التخطيط لحملة تطوّعية لتشجير ساحة المدرسة.", "ما أهمية التنسيق مع إدارة المدرسة أو الوالدين قبل تنفيذ أي مبادرة؟"], "levels": {"easy": [{"type": "mcq", "q": "لنجاح العمل التطوّعي وتجنب الفوضى نحتاج إلى:", "options": ["العشوائية", "التخطيط المنظم", "التسرّع", "عدم التنسيق"], "answer": 1, "why": "التخطيط المنظم يحقق أفضل النتائج."}, {"type": "mcq", "q": "تحديد اليوم والساعة والمكان للمبادرة التطوّعية يُعدّ جزءًا من:", "options": ["التأجيل", "الإهمال", "خطة العمل التطوّعي", "نسيان الهدف"], "answer": 2, "why": "الزمان والمكان عنصران أساسيان في الخطة."}, {"type": "mcq", "q": "الخطوة التي تأتي بعد الانتهاء من تنفيذ المبادرة هي:", "options": ["البدء من الصفر دون مراجعة", "إخفاء النتائج", "إغلاق الباب والانصراف", "تقييم المبادرة وشكر المشاركين"], "answer": 3, "why": "التقييم والشكر يختتمان المبادرة بإيجابية."}, {"type": "mcq", "q": "توزيع المهام على أعضاء الفريق التطوّعي يؤدي إلى:", "options": ["إنجاز العمل بنظام وسرعة", "تضارب الأعمال", "تعطيل المبادرة", "ملل الجميع"], "answer": 0, "why": "توزيع المهام يمنع التداخل ويرفع الكفاءة."}], "medium": [{"type": "mcq", "q": "أيّ هدف يُعدّ أوضح وأفضل لخطة عمل تطوّعي؟", "options": ["فعل أي شيء جيد", "زراعة ١٥ شتلةً في حديقة المدرسة صباح يوم الخميس", "التحدث عن التطوع فقط", "الانتظار دون موعد"], "answer": 1, "why": "الهدف الواضح يحدد العمل والعدد والمكان والزمان."}, {"type": "tfr", "q": "الحماس وحده يكفي لإنجاح أي حملة تطوّعية دون الحاجة لتخطيط أو توزيع أدوار.", "answer": false, "reasons": ["لا حاجة لتوزيع الأدوار", "التخطيط يُطفئ الحماس", "الحماس مهم لكنه يحتاج لتخطيط وتنظيم حتى لا تتحول الحملة إلى فوضى"], "reason": 2}, {"type": "essay", "q": "اذكر أربع خطوات أساسية للتخطيط لعمل تطوّعي في مدرستك.", "model": "١) تحديد الحاجة والهدف. ٢) استئذان إدارة المدرسة والتنسيق معها. ٣) تشكيل الفريق وتحديد الأدوات والوقت. ٤) التنفيذ بروح الفريق ثم التقييم والشكر."}, {"type": "tfr", "q": "شكر المتطوّعين بعد انتهاء المبادرة يُشجّعهم على المشاركة في مبادرات قادمة.", "answer": true, "reasons": ["لأن التقدير والشكر يزرعان الفرح ويعززان الدافعية للعطاء", "لأن الشكر غير ضروري", "لأنه يقلل الحماس"], "reason": 0}, {"type": "mcq", "q": "أراد طلاب جمع قصص لمكتبة الحيّ؛ ما الخطوة التي تسبق الإعلان عن الحملة؟", "options": ["التنسيق مع إدارة المدرسة وتحديد مكان وزمن استلام القصص", "توزيع القصص قبل جمعها", "تقييم الحملة", "إنهاء الفريق"], "answer": 0, "why": "التنسيق وتحديد آلية الاستلام يسبقان الإعلان."}, {"type": "essay", "q": "ما أهمية تحديد قائمة الأدوات قبل يوم التنفيذ؟", "model": "لضمان توفر كل ما يحتاجه الفريق (كالقفازات والأكياس والشتلات) في وقته دون توقف أو ارتباك أثناء العمل."}, {"type": "tfr", "q": "تحديد المستفيدين من المبادرة التطوّعية يساعد على توجيه الجهد للمكان الصحيح.", "answer": true, "reasons": ["لأنه يؤخر العمل", "لأنه غير مهم معرفة المستفيدين", "لأنه يضمن وصول الخدمة أو المساعدة لمن يحتاجها فعلًا"], "reason": 2}], "hard": [{"type": "mcq", "q": "اجتمع ١٠ متطوّعين لتنظيف حديقة الحيّ، لكنهم لم يُحضروا أكياس نفايات ولا قفازات؛ أي مرحلة من التخطيط فشلت هنا؟", "options": ["اختيار اسم الحديقة", "شكر المتطوعين", "تحديد وتجهيز الأدوات اللازمة", "الرغبة في الخير"], "answer": 2, "why": "تجهيز الأدوات مسبقًا جزء أساسي من التخطيط."}, {"type": "essay", "q": "صمّم بطاقة خطة مصغّرة لمبادرة «سقيا الطيور» في ساحة المدرسة خلال فصل الصيف في عُمان.", "model": "الهدف: وضع ٦ أوانٍ نظيفة للماء في الظل. التنسيق: مع إدارة المدرسة. الأدوات: أوانٍ آمنة وماء نظيف. الأدوار: فريق يثبّت الأواني وفريق يتناوب على تجديد الماء يوميًا. التقييم: متابعة نظافة الماء كل أسبوع."}, {"type": "tfr", "q": "تقييم العمل التطوّعي يعني البحث عن أخطاء الآخرين للومهم.", "answer": false, "reasons": ["التقييم للّوم فقط", "التقييم يهدف لمعرفة ما نجح وتطوير العمل في المرات القادمة بروح إيجابية", "لا فائدة من التقييم"], "reason": 1}, {"type": "mcq", "q": "لماذا يُفضّل التعاون مع الفرق الخيرية والتطوّعية المعتمدة في الولاية عند جمع التبرعات؟", "options": ["لضمان التنظيم الرسمي ووصول التبرعات لمستحقيها بأمان وموثوقية", "لإلغاء دور الطلاب", "لتعقيد الإجراءات فقط", "لأن الفرق لا تعمل"], "answer": 0, "why": "الفرق المعتمدة تضمن التنظيم والموثوقية والوصول الدقيق للمستفيدين."}, {"type": "essay", "q": "قارن بين التخطيط لمشروع أسري (الوحدة الثانية) والتخطيط لعمل تطوّعي (الوحدة الثالثة) من حيث وجه الشبه ووجه الاختلاف.", "model": "وجه الشبه: كلاهما يحتاج فكرة واضحة وأدوات وتوزيع أدوار وتنفيذ وتقييم. وجه الاختلاف: المشروع الأسري يهدف للإنتاج والدخل المادي بجانب النفع، أما التطوّعي فيهدف لخدمة المجتمع دون مقابل مادي."}, {"type": "tfr", "q": "يمكن توثيق إنجازات المبادرة التطوّعية بلوحة في المدرسة لتحفيز باقي الطلاب.", "answer": true, "reasons": ["لأن عرض التجارب الناجحة ينشر ثقافة التطوّع ويلهم الآخرين للمشاركة", "لأن التوثيق ممنوع", "لأنه لا يؤثر على الطلاب"], "reason": 0}, {"type": "mcq", "q": "إذا تعذّر حضور أحد أعضاء الفريق في يوم المبادرة بسبب مرضه، فما التصرف التنظيمي الصحيح؟", "options": ["إلغاء المبادرة كلها والغضب منه", "ترك مهمته دون إنجاز", "توزيع مهمته بهدوء على بقية الأعضاء والاطمئنان على صحته", "التوقف عن التعاون معه"], "answer": 2, "why": "المرونة وروح الفريق تعالج الظروف الطارئة بلطف وكفاءة."}, {"type": "essay", "q": "ما الأسئلة الثلاثة التي تطرحها على فريقك في جلسة تقييم المبادرة؟", "model": "١) هل حققنا الهدف الذي وضعناه؟ ٢) ما أفضل شيء نجح في مبادرتنا؟ ٣) ما الصعوبة التي واجهتنا وكيف نتجنبها في المبادرة القادمة؟"}, {"type": "tfr", "q": "تحديد وقتٍ مناسبٍ للمبادرة (مثل الصباح الباكر في الصيف) يُعدّ جزءًا من التخطيط الذكي في عُمان.", "answer": true, "reasons": ["لأن الظهيرة أنسب للعمل الخارجي", "لأن الوقت لا يفرق في الصيف", "لتجنب حرارة الشمس الشديدة والحفاظ على سلامة المتطوعين ونشاطهم"], "reason": 2}, {"type": "essay", "q": "اكتب إعلانًا مدرسيًا قصيرًا يدعو زملاءك للمشاركة في حملة تطوّعية لتنظيم المكتبة المدرسية متضمنًا الزمان والمكان والهدف.", "model": "إعلان مبادرة «مكتبتنا أجمل»: ندعوكم للمشاركة في ترتيب وتصنيف كتب المكتبة المدرسية يوم الأربعاء الساعة ١٠ صباحًا في قاعة المكتبة. معًا نصنع بيئة قراءة ممتعة للجميع!"}]}},
  {"id": "g4-social-1-u3-3", "grade": "g4", "subject": "social", "term": 1, "unit": 3, "no": 3, "title": "تطوّعي حياة", "summary": "شرح متحرك بـ SVG لدرس تطوّعي حياة للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-my-volunteering-is-life.html", "video": "", "pdf": "", "notes": ["العمل التطوّعي يمنح الحياة جمالًا وأملًا، ويترك آثارًا عظيمةً على المتطوّع والحيّ والوطن.", "أثر التطوّع على الفرد: تنمية الشخصية، والثقة بالنفس، وتكوين صداقات إيجابية، والشعور بالسعادة والرضا.", "أثر التطوّع على الحيّ والمجتمع: تقوية الترابط والتكافل بين الجيران، ونظافة البيئة، وحل المشكلات المحلية.", "أثر التطوّع على الوطن: دعم الجهود الوطنية، وحماية المرافق العامة، ونشر قيم الرحمة والتعاون.", "الاستمرار في التطوّع يجعله أسلوب حياة يوميًا وليس مجرد مناسبة عابرة."], "exercises": ["لماذا سُمّي هذا الدرس بـ«تطوّعي حياة»؟", "اذكر أثرين للتطوّع على شخصيتك، وأثرين على حيّك السكني.", "كيف نجعل التطوّع عادةً مستمرةً في حياتنا اليومية؟"], "levels": {"easy": [{"type": "mcq", "q": "الشعور الذي يملأ قلب المتطوّع بعد مساعدة الآخرين هو:", "options": ["السعادة والرضا", "الحزن", "الندم", "الغضب"], "answer": 0, "why": "إسعاد الآخرين يملأ قلب المتطوع بالرضا والسعادة."}, {"type": "mcq", "q": "من آثار التطوّع على الحيّ السكني:", "options": ["انقطاع التواصل بين الجيران", "نظافة المرافق وتقوية الترابط بين الجيران", "إهمال الحدائق", "زيادة النفايات"], "answer": 1, "why": "التطوع يجمل الحي ويقرب الجيران."}, {"type": "mcq", "q": "إماطة الأذى عن الطريق ومساعدة زميل يوميًا تُعدّ:", "options": ["إضاعة وقت", "عملًا غير مفيد", "تطوّعًا بسيطًا وأسلوب حياة", "أمرًا صعبًا جدًا"], "answer": 2, "why": "المبادرات اليومية البسيطة تجعل التطوع أسلوب حياة."}, {"type": "mcq", "q": "عندما يرى الأطفال الكبارَ يتطوّعون، فإنهم:", "options": ["ينفرون من الخير", "يرفضون المساعدة", "ينسون التعاون", "يقتدون بهم ويتعلمون حب العطاء"], "answer": 3, "why": "القدوة الحسنة تنشر ثقافة التطوع."}], "medium": [{"type": "mcq", "q": "كيف يُسهم التطوّع في بناء الصداقات الإيجابية؟", "options": ["يجمع المتطوّع بأشخاص يحبون الخير والتعاون مثله", "يبعده عن زملائه", "يسبب الخلافات", "يمنعه من التحدث مع أحد"], "answer": 0, "why": "العمل التطوعي بيئة رائعة لتكوين صداقات إيجابية."}, {"type": "tfr", "q": "يحتاج الإنسان لأن يكون ثريًا جدًا حتى يترك أثرًا تطوّعيًا في حياة الآخرين.", "answer": false, "reasons": ["الوقت والجهد بلا أثر", "لا تطوّع إلا بالمال الكثير", "الابتسامة والجهد والوقت والمساعدة البسيطة تترك أثرًا عظيمًا دون مال"], "reason": 2}, {"type": "essay", "q": "اذكر ثلاثة آثار إيجابية للتطوّع: واحد على الفرد، وواحد على الحيّ، وواحد على الوطن.", "model": "على الفرد: زيادة الثقة والسعادة. على الحيّ: نظافة المرافق وترابط الجيران. على الوطن: دعم الجهود الوطنية وتعزيز التكافل."}, {"type": "tfr", "q": "استمرار المبادرات التطوّعية الصغيرة أفضل من الحماس المؤقت الذي ينقطع سريعًا.", "answer": true, "reasons": ["لأن الاستمرار يجعل العطاء عادةً دائمةً ويراكم أثرًا كبيرًا مع الوقت", "لأن العمل المتقطع أفضل دائمًا", "لأن المبادرات الصغيرة لا تنفع"], "reason": 0}, {"type": "mcq", "q": "سقي نباتات حديقة الحيّ بانتظام مع أصدقائك يُجسّد معنى «تطوّعي حياة» لأنه:", "options": ["عمل مؤقت ليوم واحد فقط", "يستهلك وقت اللعب بلا فائدة", "يُتلف الحديقة", "يُحافظ على حياة النباتات وجمال المكان ويعزّز التعاون"], "answer": 3, "why": "رعاية النباتات تبث الحياة في البيئة وتغرس روح العطاء."}, {"type": "essay", "q": "ما المقصود بـ«نشر العدوى الإيجابية» في العمل التطوّعي؟", "model": "أن يكون المتطوّع قدوةً حسنةً، فعندما يراه الآخرون يُبادر بالخير بابتسامة، يتحمّسون لتقليده والمشاركة في خدمة المجتمع."}, {"type": "tfr", "q": "العمل التطوّعي يُضعف التحصيل الدراسي للطالب دائمًا.", "answer": false, "reasons": ["المتفوقون لا يتطوّعون", "التطوع يمنع المذاكرة", "التطوّع المنظم في أوقات الفراغ ينمّي شخصية الطالب وتنظيمه لوقته"], "reason": 2}], "hard": [{"type": "mcq", "q": "تعرّضت إحدى الولايات لأمطار غزيرة، فبادر الشباب والأسر بمساعدة الجيران وتنظيف الطرقات بإشراف الجهات المختصة؛ ما القيمة التي يُبرزها هذا الموقف؟", "options": ["الأنانية", "التكافل الوطني وروح التطوّع الأصيلة في عُمان", "إهمال السلامة", "التنافس السلبي"], "answer": 1, "why": "التكاتف وقت الأزمات أسمى صور التطوع والمواطنة."}, {"type": "essay", "q": "اشرح بأسلوبك كيف يحوّل التطوّع سكان الحيّ من مجرد جيران إلى «أسرة واحدة متفاعلة».", "model": "عندما يجتمع الجيران في أعمال مشتركة لخدمة حيّهم، يتعارفون ويتبادلون المحبة والاحترام، ويتفقدون احتياجات بعضهم، فتزول العزلة ويقوى الترابط."}, {"type": "tfr", "q": "المهارات التي يتعلمها الطفل في التطوّع (مثل القيادة والعمل الجماعي) تفيده في دراسته ومستقبله.", "answer": true, "reasons": ["لأن التطوّع لا يعلّم أي مهارة", "لأنها مهارات حياتية أساسية تنجح بها المشاريع الدراسية والمهنية", "لأن المهارات الاجتماعية غير مطلوبة"], "reason": 1}, {"type": "mcq", "q": "أيّ عبارة تُعبّر عن التكامل بين دروس الوحدة الثالثة (أنا متطوّع، أُخطّط للعمل التطوّعي، تطوّعي حياة)؟", "options": ["الانتظار دون مبادرة", "التخطيط ← ترك التطوّع ← العزلة", "العمل العشوائي ← التوقف ← النسيان", "الشعور بقيمة التطوّع ← التخطيط المنظم له ← جني آثاره وجعله أسلوب حياة"], "answer": 3, "why": "تبدأ الوحدة بالوعي بالذات المتطوّعة، ثم التخطيط، ثم الأثر والاستدامة."}, {"type": "essay", "q": "اقترح ثلاث «عادات تطوّعية يومية» صغيرة يلتزم بها طالب الصف الرابع طوال الأسبوع.", "model": "١) إماطة أي ورقة أو أذى في ممر المدرسة أو الطريق. ٢) مساعدة زميل أو أخ أصغر في فهم مسألة أو حمل أغراضه. ٣) سقي نباتات البيت أو وضع ماء للطيور."}, {"type": "tfr", "q": "المحافظة على الممتلكات العامة في الحيّ تُعدّ جزءًا من المسؤولية التطوّعية والمجتمعية.", "answer": true, "reasons": ["لأن حماية الحدائق والمدارس والمساجد تحفظ حق الجميع وتقلل الهدر", "لأن الممتلكات العامة لا تهم المواطن", "لأن الحفاظ عليها واجب الحكومة وحدها"], "reason": 0}, {"type": "mcq", "q": "لو لاحظت أن حديقة حيّكم جميلة لكن ينقصها سلال مهملات كافية، فما أرقى مبادرة جماعية مقترحة؟", "options": ["إلقاء الأوراق على الأرض احتجاجًا", "التنسيق مع الكبار ولجنة الحيّ لتوفير سلال وتوعية الأطفال باستخدامها", "عدم زيارة الحديقة", "لوم الأطفال الصغار فقط"], "answer": 1, "why": "المبادرة الإيجابية تعالج المشكلة بالتنسيق والتوعية."}, {"type": "essay", "q": "لماذا يُقال إن «المتطوّع يأخذ أكثر مما يُعطي»؟", "model": "لأنه يعطي قليلًا من وقته وجهده، لكنه يكتسب في المقابل أجرًا عظيمًا وسعادةً قلبيةً، وثقةً بالنفس، ومحبة الناس، ومهاراتٍ حياتيةً ثمينة."}, {"type": "tfr", "q": "يمكن أن يشارك كبار السن والأطفال معًا في المبادرات التطوّعية بالحيّ كلٌّ حسب قدرته.", "answer": true, "reasons": ["لا يمكن للأطفال وكبار السن العمل معًا", "التطوّع للشباب فقط", "فكبار السن يشاركون بالخبرة والتوجيه والأطفال بالنشاط والحيوية، فيتكامل الجيلان"], "reason": 2}, {"type": "essay", "q": "اكتب شعارًا قصيرًا من كلماتك يشجّع طلاب مدرستك على التطوّع، واشرح معناه في سطرين.", "model": "الشعار: «بيدٍ صغيرةٍ نصنع أثرًا كبيرًا». المعنى: حتى لو كنا صغارًا في الصف الرابع، فإن مبادراتنا التطوّعية المتعاونة تجعل مدرستنا وحيّنا أجمل وأسعد."}]}},
  {"id": "g4-social-2-u4-1", "grade": "g4", "subject": "social", "term": 2, "unit": 4, "no": 1, "title": "أنتخب مَنْ يُمثّلني", "summary": "شرح متحرك بـ SVG لدرس أنتخب مَنْ يُمثّلني للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-elect-my-representative.html", "video": "", "pdf": "", "notes": ["الانتخاب هو طريقة منظّمة وعادلة يختار بها أفراد المجموعة مَنْ يمثّلهم ويتحدث باسمهم.", "يمارس الطلاب الانتخاب في المدرسة عند اختيار رئيس الصف أو أعضاء مجلس الطلبة أو الجماعات المدرسية.", "يمارس المواطنون الكبار الانتخاب في سلطنة عُمان لاختيار أعضاء مجلس الشورى والمجالس البلدية.", "تمرّ عملية الانتخاب بخطوات واضحة: الترشح، عرض الأفكار، التصويت السري، فرز الأصوات، ثم إعلان الفائز.", "نختار المرشح بناءً على كفاءته وأمانته وتعاونه وقدرته على خدمة الجميع، وليس لمجرد الصداقة أو القرابة."], "exercises": ["ما المقصود بعملية الانتخاب؟", "اذكر ثلاث صفات يجب أن تتوفر في الطالب الذي ننتخبه ليمثّل صفّنا.", "رتّب خطوات انتخاب رئيس الصف من البداية حتى إعلان النتيجة."], "levels": {"easy": [{"type": "mcq", "q": "الطريقة المنظّمة التي يختار بها أفراد المجموعة مَنْ يمثّلهم تُسمّى:", "options": ["العشوائية", "التشاجر", "الانسحاب", "الانتخاب"], "answer": 3, "why": "الانتخاب هو وسيلة الاختيار العادل والمنظم."}, {"type": "mcq", "q": "الطالب الذي يتقدم ليمثّل صفّه ويعرض أفكاره يُسمّى:", "options": ["المرشّح", "الناخب", "المشاهد", "الزائر"], "answer": 0, "why": "المرشح هو المتقدم لتمثيل المجموعة."}, {"type": "mcq", "q": "من أهم صفات المرشّح الجيد لتمثيل الصف:", "options": ["الإهمال", "الأمانة والتعاون والانضباط", "عدم الاستماع للآخرين", "الغضب السريع"], "answer": 1, "why": "الأمانة والتعاون والانضباط صفات الممثل الناجح."}, {"type": "mcq", "q": "الخطوة الأخيرة في عملية الانتخاب هي:", "options": ["الترشّح", "كتابة الأسماء", "فرز الأصوات وإعلان الفائز", "إغلاق الصندوق"], "answer": 2, "why": "بعد التصويت تُفرز الأصوات ويُعلن الفائز."}], "medium": [{"type": "mcq", "q": "ما الترتيب الصحيح لخطوات انتخاب رئيس الصف؟", "options": ["إعلان الفائز ← التصويت ← الترشح", "التصويت ← الترشح ← عرض الأفكار", "فرز الأصوات ← الترشح ← التصويت", "الترشح ← عرض الأفكار ← التصويت ← فرز الأصوات ← إعلان الفائز"], "answer": 3, "why": "هذا هو التسلسل النظامي العادل لأي انتخاب."}, {"type": "tfr", "q": "يكون التصويت في الانتخابات سريًا حتى يختار كل ناخب بحرية ودون حرج.", "answer": true, "reasons": ["يجب أن يرى الجميع ورقة زميله", "السرية غير مفيدة", "السرية تحمي حرية الناخب وتمنع الضغط أو الإحراج"], "reason": 2}, {"type": "essay", "q": "فرّق بين «المرشّح» و«الناخب» في جملتين واضحتين.", "model": "المرشّح هو الشخص الذي يتقدّم لتمثيل المجموعة ويعرض أفكاره لخدمتها. أما الناخب فهو الشخص الذي يُدلي بصوته لاختيار المرشّح الأنسب."}, {"type": "tfr", "q": "الأفضل دائمًا أن أنتخب صديقي المقرّب حتى لو كان لا يلتزم بواجباته ولا يتعاون مع الصف.", "answer": false, "reasons": ["نختار الأكفأ والأقدر على خدمة الصف بصدق وأمانة لا لمجرد الصداقة", "الصداقة أهم من الكفاءة", "لا حاجة للانضباط في رئيس الصف"], "reason": 0}, {"type": "mcq", "q": "كيف تُهيّئ الانتخابات المدرسية الطلاب لمستقبلهم في سلطنة عُمان؟", "options": ["تُعلّمهم الخصام", "تُضيع وقت الحصة فقط", "تُدرّبهم على اختيار الأكفأ واحترام الرأي والنتيجة قبل المشاركة في انتخابات الشورى والبلدية", "لا علاقة لها بالمستقبل"], "answer": 2, "why": "الممارسة المدرسية تغرس ثقافة الشورى والاختيار الواعي مبكرًا."}, {"type": "essay", "q": "كيف تتصرف بروحٍ رياضية إذا ترشّحت لرئاسة الصف ولم تفز؟", "model": "أحترم اختيار زملائي، وأهنّئ الفائز بابتسامة، وأعرض عليه مساعدتي وتعاوني لإنجاح أنشطة صفّنا."}, {"type": "tfr", "q": "من حق كل طالب تتوفر فيه الشروط أن يترشّح لتمثيل صفّه.", "answer": true, "reasons": ["لا يُسمح بأكثر من مرشح", "الترشح لطالب واحد فقط", "لأن الفرص متكافئة وعادلة بين جميع الطلاب المستوفين للشروط"], "reason": 2}], "hard": [{"type": "mcq", "q": "تقدّم مرشّحان لرئاسة الصف: الأول وعد بحلول واقعية لتنظيم المكتبة الصفية ووقت الفسحة، والثاني وعد بإلغاء الاختبارات تمامًا! مَن تختار ولماذا؟", "options": ["الأول لأن برنامجه واقعي وصادق ويمكن تنفيذه لخدمة الصف", "الثاني لأن وعده مغرٍ", "كلاهما غير مناسب", "أرفض التصويت"], "answer": 0, "why": "الناخب الواعي يميّز بين الوعود الواقعية الصادقة والوعود المستحيلة."}, {"type": "essay", "q": "لماذا يُعدّ فرز الأصوات أمام ممثلين عن الطلاب وإشراف المعلم أمرًا مهمًا في الانتخابات؟", "model": "لتحقيق الشفافية والنزاهة، حتى يطمئن الجميع أن العدّ دقيق وعادل فتُقبل النتيجة بثقة ورضا."}, {"type": "tfr", "q": "تمثيل الصف يعني أن يتسلّط الفائز على زملائه ويفرض رأيه وحده.", "answer": false, "reasons": ["رئيس الصف يفعل ما يشاء وحده", "التمثيل مسؤولية وخدمة وتعاون ونقل لآراء الزملاء لا تسلّط", "لا يجب استشارة الزملاء"], "reason": 1}, {"type": "mcq", "q": "أيّ قيمة عُمانية وإسلامية ترتبط ارتباطًا وثيقًا بعملية الانتخاب؟", "options": ["التعصّب", "الأنانية", "الشورى والعدل", "الإهمال"], "answer": 2, "why": "الشورى والعدل هما أساس اختيار الممثلين في مجتمعنا."}, {"type": "essay", "q": "تخيّل أنك مرشّح لتمثيل صفك؛ اكتب كلمتين تعريفيتين (برنامجًا قصيرًا من نقطتين) تعرضهما على زملائك.", "model": "زملائي الأعزاء، أعدكم إن اخترتموني بـ: ١) إنشاء صندوق مقترحات للاستماع لأفكاركم ونقلها للمعلم. ٢) تنظيم مسابقة أسبوعية لجعل صفّنا الأنظف والأكثر تعاونًا."}, {"type": "tfr", "q": "إذا تساوى مرشّحان في عدد الأصوات تمامًا، تُعاد جولة التصويت بينهما بطريقة منظّمة لحسم الاختيار بعدل.", "answer": true, "reasons": ["لأن إعادة التصويت تحسم التساوي بعدل وشفافية", "يُختار الأكبر طولًا", "يُلغى الصف"], "reason": 0}, {"type": "mcq", "q": "ما دور «مجلس الشورى» و«المجالس البلدية» في سلطنة عُمان بشكل مبسّط لطالب الصف الرابع؟", "options": ["نقل صوت المواطنين ومقترحاتهم والمساهمة في تطوير الخدمات والولايات", "تنظيم الألعاب فقط", "لا دور لها", "مراقبة الطقس فقط"], "answer": 0, "why": "تمثّل هذه المجالس صوت المواطنين وتسهم في تطوير الوطن."}, {"type": "essay", "q": "اذكر سببًا يجعل التصويت السري أفضل من رفع الأيدي في كثير من الانتخابات.", "model": "لأن التصويت السري يجعل الطالب يختار بقناعته الحقيقية دون خوف من غضب صديق أو إحراج أحد."}, {"type": "tfr", "q": "ينتهي دور الناخبين بمجرد انتهاء التصويت ولا علاقة لهم بمساعدة الفائز.", "answer": false, "reasons": ["لا يجب مساعدة رئيس الصف", "الفائز يعمل وحده دائمًا", "المجموعة كلها تتعاون مع ممثلها وتسانده وتشاركه الأفكار لنجاح الصف"], "reason": 2}, {"type": "essay", "q": "لماذا يُعدّ انتخاب مَنْ يمثّلني خطوةً في «الارتقاء بوطني»؟", "model": "لأن اختيار الأشخاص الأكفاء والأمناء في المدرسة ثم في المجتمع يضمن جودة القرارات والخدمات، فيتطور المجتمع ويرتقي الوطن."}]}},
  {"id": "g4-social-2-u4-2", "grade": "g4", "subject": "social", "term": 2, "unit": 4, "no": 2, "title": "أنا عُضو فاعل", "summary": "شرح متحرك بـ SVG لدرس أنا عُضو فاعل للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-active-member.html", "video": "", "pdf": "", "notes": ["العضو الفاعل هو الفرد الذي يشارك بإيجابية والتزام في مجموعته (الأسرة، الصف، الجماعة المدرسية، المجتمع) ويؤدي دوره بإتقان.", "لا يكفي الانتساب بالاسم فقط، بل تُقاس الفاعلية بالعطاء والمبادرة وتقديم الأفكار البناءة وتنفيذ المهام.", "من صفات العضو الفاعل: الالتزام بالمواعيد، والاستماع لآراء الآخرين، واحترام القرار الجماعي، والمبادرة لحل المشكلات.", "العضو الفاعل يتحمل مسؤوليته ولا يعتمد على الآخرين للقيام بواجبه.", "كلما كان أفراد الصف والوطن أعضاءً فاعلين، ارتقى المجتمع وتقدّم."], "exercises": ["ما الفرق بين العضو الفاعل والعضو غير الفاعل (المتفرج) في فريق مدرسي؟", "اذكر ثلاث صفات تجعلك عضوًا فاعلًا في صفّك أو أسرتك.", "كيف تتصرف إذا لم يُعتمد اقتراحك في اجتماع المجموعة واختار الأغلبية اقتراحًا آخر؟"], "levels": {"easy": [{"type": "mcq", "q": "الشخص الذي يشارك بإيجابية ويلتزم بأداء دوره في المجموعة يُسمّى:", "options": ["المتفرّج", "العضو الخامل", "العضو الفاعل", "المنسحب"], "answer": 2, "why": "المشاركة الإيجابية والالتزام هما معنى العضو الفاعل."}, {"type": "mcq", "q": "من صفات العضو الفاعل عند النقاش في الصف:", "options": ["مقاطعة الزملاء", "عدم الانتباه", "رفع الصوت بغضب", "الاستماع الجيد واحترام آراء الآخرين"], "answer": 3, "why": "الإنصات والاحترام أساس النقاش البناء."}, {"type": "mcq", "q": "كيف تكون عضوًا فاعلًا في أسرتك؟", "options": ["بمساعدة والديّ والمحافظة على ترتيب غرفتي", "بترك أغراضي مبعثرة", "بعدم التعاون مع إخوتي", "برفض الواجبات"], "answer": 0, "why": "المساعدة والترتيب يظهران فاعليتك في البيت."}, {"type": "mcq", "q": "الانتساب لجماعة مدرسية بالاسم فقط دون مشاركة يُعدّ:", "options": ["فاعلية عالية", "عضوية غير فاعلة", "مبادرة رائعة", "قيادة ناجحة"], "answer": 1, "why": "الفاعلية تتطلب عملًا ومشاركة لا مجرد اسم."}], "medium": [{"type": "mcq", "q": "لاحظت أن مجموعة مشروع العلوم متأخرة في إنجاز اللوحة؛ ما تصرف العضو الفاعل؟", "options": ["لوم الآخرين والجلوس ساكتًا", "الانضمام لمجموعة أخرى سرًا", "المبادرة بتقديم حل وتنظيم المهام والمشاركة في الإنجاز", "تمزيق اللوحة"], "answer": 2, "why": "العضو الفاعل يبادر بالحلول والعمل بدل اللوم."}, {"type": "tfr", "q": "العضو الفاعل يفرض رأيه دائمًا ولا يقبل أي فكرة من زملائه.", "answer": false, "reasons": ["آراء الزملاء غير مهمة", "فرض الرأي دليل قوة", "العضو الفاعل يستمع لآراء الجميع ويحترم قرار الأغلبية"], "reason": 2}, {"type": "essay", "q": "قارن بين العضو الفاعل والعضو الخامل في نقطتين.", "model": "العضو الفاعل: ١) يبادر ويقدم أفكارًا وحلولًا. ٢) يلتزم بمهامه ويتعاون مع الفريق. أما الخامل: ١) يكتفي بالمشاهدة والشكوى. ٢) يعتمد على غيره في إنجاز العمل."}, {"type": "tfr", "q": "الالتزام بقوانين المدرسة والمحافظة على نظافتها دليل على أنني عضو فاعل.", "answer": true, "reasons": ["لأن احترام القوانين والمرافق يعكس المسؤولية والانتماء للمدرسة", "لأن القوانين تمنع الفاعلية", "لأن النظافة لا علاقة لها بالعضوية"], "reason": 0}, {"type": "mcq", "q": "ماذا تعني عبارة «يدٌ واحدة لا تُصفّق» في سياق عمل الفريق؟", "options": ["أن العمل الفردي يكفي دائمًا", "أن النجاح الكبير يتحقق بتعاون ومشاركة جميع الأعضاء", "أن الفريق لا يحتاج لتعاون", "أن التصفيق ممنوع"], "answer": 1, "why": "تكاتف الأعضاء الفاعلين يصنع الإنجازات الكبيرة."}, {"type": "essay", "q": "اذكر موقفًا تصرفت فيه كعضو فاعل في صفّك أو أسرتك.", "model": "مثال: عندما رتّبنا صفّنا استعدادًا لمسابقة أنظف صف، بادرت بتنظيم مكتبة الصف وساعدت زملائي في ترتيب اللوحات حتى فزنا."}, {"type": "tfr", "q": "يمكن لطالب الصف الرابع أن يكون عضوًا فاعلًا في وطنه من خلال اجتهاده في الدراسة وحفاظه على الممتلكات العامة.", "answer": true, "reasons": ["لأن الدراسة لا تفيد الوطن", "لأن الطلاب الصغار لا دور لهم تجاه الوطن", "لأن التفوق العلمي وحماية المرافق من أهم واجبات الطالب تجاه وطنه"], "reason": 2}], "hard": [{"type": "mcq", "q": "اقترح سيف فكرةً جميلةً لرحلة الجماعة، لكن الأغلبية اختارت فكرة أخرى؛ فشعر بالضيق قليلًا ثم ابتسم وشارك في التحضير للرحلة المختارة. هذا يدل على:", "options": ["الضعف وعدم الثقة", "اللامبالاة", "عدم اهتمامه بفكرته", "النضج واحترام القرار الجماعي وروح العضو الفاعل"], "answer": 3, "why": "احترام الشورى وقرار الأغلبية مع التعاون أسمى مظاهر الفاعلية."}, {"type": "essay", "q": "كيف تحفّز زميلًا خجولًا في فريقك ليصبح عضوًا فاعلًا ومشاركًا؟", "model": "أستمع لرأيه باهتمام، وأسأله عن اقتراحاته بلطف، وأقترح عليه مهمة تناسب موهبته، وأشجّعه وأشكره على كل مساهمة يقدمها."}, {"type": "tfr", "q": "العضو الفاعل ينتقد أخطاء زملائه بأسلوب جارح ليُظهر أنه الأفضل.", "answer": false, "reasons": ["النقد الجارح ضروري للفريق", "العضو الفاعل يقدّم ملاحظاته بأدب وبروح بناءة هدفها تحسين العمل لا جرح المشاعر", "التكبر يرفع جودة العمل"], "reason": 1}, {"type": "mcq", "q": "أيّ عبارة تُلخّص أثر وجود أعضاء فاعلين في مجلس الطلبة بالمدرسة؟", "options": ["كثرة الاجتماعات بلا نتائج", "تحوّل الأفكار إلى مبادرات حقيقية تُحسّن البيئة المدرسية للجميع", "اعتماد الجميع على رئيس المجلس وحده", "توقف الأنشطة"], "answer": 1, "why": "الأعضاء الفاعلون يحوّلون الخطط إلى إنجازات ملموسة."}, {"type": "essay", "q": "اشرح كيف ترتبط «العضوية الفاعلة» بـ«الارتقاء بالوطن».", "model": "الوطن يتكوّن من أسر ومدارس ومؤسسات؛ فإذا كان كل فرد عضوًا فاعلًا ومخلصًا ومبادرًا في موقعه، ارتفعت جودة العمل وازدهر الوطن كله."}, {"type": "tfr", "q": "الاعتذار المسبق عند حدوث ظرف طارئ يمنع حضور اجتماع الفريق يُعدّ من أدب والتزام العضو الفاعل.", "answer": true, "reasons": ["لأنه يحترم وقت الفريق ويتيح لهم ترتيب المهام دون ارتباك", "لأن الغياب دون إخبار أفضل", "لأن المواعيد غير مهمة"], "reason": 0}, {"type": "mcq", "q": "ما المهارة الأهم التي يحتاجها العضو الفاعل عند اختلاف الآراء داخل المجموعة؟", "options": ["السخرية من المخالفين", "الصراخ لفرض الرأي", "الانسحاب الفوري", "الحوار الهادئ والبحث عن نقطة التقاء تخدم مصلحة الجميع"], "answer": 3, "why": "الحوار الهادئ يجمع الأفكار الجيدة ويحفظ تماسك الفريق."}, {"type": "essay", "q": "ضع ميثاقًا قصيرًا من ٣ بنود للعضو الفاعل في صفك الدراسي.", "model": "١) ألتزم بدوري ومواعيدي بأمانة. ٢) أستمع لزملائي بأدب وأحترم القرار الجماعي. ٣) أبادر بالمساعدة والأفكار الإيجابية لجعل صفّنا الأفضل."}, {"type": "tfr", "q": "القيام بواجبي الدراسي بإتقان لا علاقة له بكوني عضوًا فاعلًا.", "answer": false, "reasons": ["العضو الفاعل يهمل دروسه", "الدراسة منفصلة عن الفاعلية", "إتقان الواجب الأساسي هو أول وأهم دليل على الفاعلية والمسؤولية"], "reason": 2}, {"type": "essay", "q": "تخيّل أن مدرستك ستستقبل وفدًا زائرًا؛ اذكر ثلاث مبادرات يمكنك تقديمها كعضو فاعل لإنجاح اليوم.", "model": "١) المشاركة في ترتيب ونظافة مدخل الصف واللوحات. ٢) الاستقبال بابتسامة وترحيب عُماني أصيل. ٣) الالتزام بالنظام والهدوء وتقديم صورة مشرّفة عن مدرستي ووطني."}]}},
  {"id": "g4-social-2-u4-3", "grade": "g4", "subject": "social", "term": 2, "unit": 4, "no": 3, "title": "صوتي أمانة", "summary": "شرح متحرك بـ SVG لدرس صوتي أمانة للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-my-vote-is-a-trust.html", "video": "", "pdf": "", "notes": ["صوت الناخب أمانةٌ ومسؤوليةٌ كبيرة، لأنه يؤثر في اختيار الشخص الذي سيمثّل المجموعة ويخدمها.", "الأمانة في التصويت تعني أن أعطي صوتي للأكفأ والأصدق والأقدر على العطاء، بعيدًا عن المجاملة أو التحيّز.", "يرفض المواطن والطالب الأمين أي محاولة للتأثير غير الشريف على صوته كالهدايا أو الوعود الكاذبة أو الضغط.", "التفكير الجيد والمقارنة بين المرشحين قبل التصويت يحقق المصلحة العامة للجميع.", "اختيار الأكفأ بأمانةٍ ينعكس نجاحًا وتطورًا على الصف والمدرسة والوطن."], "exercises": ["لماذا يُعدّ صوتك في الانتخابات «أمانة»؟", "ماذا تفعل إذا طلب منك زميل أن تصوّت له مقابل هدية أو مجاملة؟", "كيف يؤدي التصويت بأمانة إلى الارتقاء بالصف والوطن؟"], "levels": {"easy": [{"type": "mcq", "q": "إعطاء صوتي للمرشح الأكفأ والأصدق دون مجاملة يُسمّى:", "options": ["التحيّز", "الأمانة في التصويت", "الإهمال", "التقليد"], "answer": 1, "why": "اختيار الأكفأ بصدق هو جوهر أمانة الصوت."}, {"type": "mcq", "q": "تقديم هدية للناخب ليصوّت لمرشح معيّن يُعدّ سلوكًا:", "options": ["صحيحًا ومقبولًا", "مطلوبًا في الانتخابات", "غير شريف ومرفوضًا", "دليل كفاءة"], "answer": 2, "why": "محاولة شراء الأصوات بالهدايا تنافي الأمانة والنزاهة."}, {"type": "mcq", "q": "عند التصويت أضع أولًا:", "options": ["التسرّع دون تفكير", "المجاملة فقط", "الوعود المستحيلة", "المصلحة العامة للجميع"], "answer": 3, "why": "المصلحة العامة مقدّمة على المجاملات."}, {"type": "mcq", "q": "قبل أن أصوّت، ينبغي أن:", "options": ["أستمع لأفكار المرشحين وأفكّر جيدًا", "أختار بالقرعة", "أقلّد من يجلس بجانبي", "لا أقرأ الأسماء"], "answer": 0, "why": "الاستماع والتفكير الواعي يحفظان أمانة الصوت."}], "medium": [{"type": "mcq", "q": "اختيار حارس المرمى الأبرع لتمثيل فريق المدرسة بدلًا من صديقي غير المتدرّب يُعلّمنا:", "options": ["التحيّز للأصدقاء", "تغليب الكفاءة والمصلحة العامة", "ترك الرياضة", "عدم الاهتمام بالفوز"], "answer": 1, "why": "الكفاءة تضمن نجاح الفريق كله."}, {"type": "tfr", "q": "صوت فرد واحد لا يُحدث أي فرق في الانتخابات، لذلك لا يهم لمن أُعطيه.", "answer": false, "reasons": ["يمكن اختيار أي اسم عشوائيًا", "الصوت الواحد بلا فائدة", "كل صوت له قيمة وقد يرجّح كفة الأكفأ، وهو أمانة يُسأل عنها صاحبه"], "reason": 2}, {"type": "essay", "q": "اذكر أمرين يجب تجنبهما لحفظ أمانة صوتك في الانتخابات.", "model": "١) تجنب المجاملة أو التحيّز على حساب الكفاءة. ٢) رفض الهدايا أو المصالح الشخصية والوعود الكاذبة التي تحاول التأثير على صوتي."}, {"type": "tfr", "q": "المقارنة الهادئة بين سلوك المرشحين وبرامجهم تساعدني على اتخاذ قرار أمين.", "answer": true, "reasons": ["لأن المقارنة الموضوعية تكشف المرشح الأصدق والأكثر قدرة على العطاء", "لأن المقارنة تشتّت الناخب", "لأن البرامج لا قيمة لها"], "reason": 0}, {"type": "mcq", "q": "كيف تحفظ الصداقة مع زميلك المترشّح إذا رأيت أن مرشحًا آخر أكفأ منه؟", "options": ["تصوّت بأمانة سرًا للأكفأ، وتُبقي علاقتك طيبة ومحترمة مع زميلك", "تُقاطعه تمامًا", "تسخر منه أمام الصف", "تُجامله على حساب مصلحة الصف"], "answer": 0, "why": "سرية التصويت والأدب يحفظان الأمانة والصداقة معًا."}, {"type": "essay", "q": "كيف تنعكس أمانة التصويت على تطور وطننا سلطنة عُمان؟", "model": "عندما يختار المواطنون ممثلين أمناء وأكفاء في مجلس الشورى والمجالس البلدية، تصل قضايا المجتمع بصدق وتتحسن الخدمات ويرتقي الوطن."}, {"type": "tfr", "q": "تقليد زميلي في اختيار المرشح دون أن أعرف برنامجه يُعدّ تصرفًا واعيًا.", "answer": false, "reasons": ["لا داعي لمعرفة برامج المرشحين", "التقليد يوفّر التفكير", "التصويت الواعي يتطلب قناعة شخصية بعد التفكير لا التقليد الأعمى"], "reason": 2}], "hard": [{"type": "mcq", "q": "قارن بين مرشحين لتمثيل الصف: (أ) معروف بصدقه ومساعدته للجميع منذ بداية العام، و(ب) لم يساعد أحدًا قط لكنه وزّع ملصقات ملونة يوم الانتخاب فقط؛ مَن يستحق أمانة صوتك؟", "options": ["كلاهما متساويان", "المرشح (ب) بسبب الملصقات", "المرشح (أ) لأن أفعاله الصادقة المستمرة دليل كفاءته وأمانته", "لا أصوّت لأحد"], "answer": 2, "why": "السجل الحقيقي من الأمانة والتعاون أصدق من الدعاية المؤقتة."}, {"type": "essay", "q": "اكتب ردًّا مهذبًا وحازمًا تردّ به على زميل طلب منك التصويت له مقابل هدية.", "model": "شكرًا لك يا صديقي، لكنني لا أقبل هدية مقابل صوتي؛ فصوتي أمانة وأختار مَنْ أراه الأنسب لخدمة صفّنا، وأتمنى لك كل التوفيق بجهدك وأفكارك."}, {"type": "tfr", "q": "الأمانة في التصويت جزء من الأمانة العامة التي أمرنا بها ديننا الإسلامي وقيمنا العُمانية.", "answer": true, "reasons": ["لا علاقة للأمانة بالتصويت", "فقد أمر الإسلام بأداء الأمانات إلى أهلها، والصوت شهادة وأمانة عظيمة", "التصويت أمر شكلي فقط"], "reason": 1}, {"type": "mcq", "q": "أكمل تسلسل دروس الوحدة الرابعة (أرتقي بوطني) بترتيبها المنطقي:", "options": ["أنتخب مَنْ يمثّلني ← أكون عضوًا فاعلًا ← أحفظ أمانة صوتي ليرتقي وطني", "أهمل التصويت ← أنسحب ← أنتقد", "أجامل ← أتوقف ← أبتعد", "التقليد ← العشوائية ← الفوضى"], "answer": 0, "why": "تتكامل الدروس الثلاثة لبناء مواطن واعٍ وفاعل وأمين."}, {"type": "essay", "q": "ما المخاطر التي تحدث للمجموعة إذا صوّت معظم أعضائها بالمجاملة وتركوا الكفاءة؟", "model": "قد يفوز شخص غير قادر على تحمّل المسؤولية، فتتعطّل أنشطة المجموعة، وتضيع مصالح الجميع، ويشعر الأعضاء بعدم الرضا."}, {"type": "tfr", "q": "مسؤولية الطالب تنتهي فور وضع الورقة في صندوق الاقتراع ولا علاقة له بمتابعة تنفيذ الوعود.", "answer": false, "reasons": ["من حق الناخب وواجبه متابعة ممثله والتعاون معه وتذكيره بمقترحات الصف بأدب", "لا يجوز متابعة الممثل", "التصويت نهاية المشاركة"], "reason": 0}, {"type": "mcq", "q": "في يوم الانتخابات، ما السلوك الذي يجمع بين «الشفافية» و«حرية الاختيار»؟", "options": ["فرز الأصوات في السر دون شهود", "التصويت العلني تحت ضغط الأصدقاء", "التصويت السري في مكان مخصص ثم فرز الأصوات علنًا أمام الجميع", "تغيير الأصوات بعد الفرز"], "answer": 2, "why": "السرية عند التصويت والعلنية عند الفرز هما ضمانة النزاهة."}, {"type": "essay", "q": "لماذا يُعدّ «تغليب المصلحة العامة على المصلحة الشخصية» علامةً على المواطنة الصالحة؟", "model": "لأن المواطن الصالح يحب الخير لوطنه ومجتمعه كله، ويدرك أن ازدهار الجميع يعود بالنفع والاستقرار عليه وعلى أسرته أيضًا."}, {"type": "tfr", "q": "الاعتذار عن التصويت لصديق غير مؤهّل لا يعني كراهيته بل يعني حفظ الأمانة.", "answer": true, "reasons": ["المجاملة واجب دائمًا", "من لم يصوّت لصديقه يكرهه", "فالأمانة في الاختيار مقدّمة على المجاملة مع استمرار المحبة والاحترام بين الأصدقاء"], "reason": 2}, {"type": "essay", "q": "صُغ نصيحةً من سطرين لزملائك قبل بدء انتخابات مجلس الطلبة في مدرستك بعنوان «صوتي أمانة».", "model": "زملائي، استمعوا جيدًا لأفكار المرشحين وفكّروا في مصلحة مدرستنا، وضعوا أصواتكم أمانةً في يد الأكفأ والأصدق دون مجاملة؛ فبأمانتنا نرتقي بمدرستنا ووطننا!"}]}},
  {"id": "g4-social-2-u5-1", "grade": "g4", "subject": "social", "term": 2, "unit": 5, "no": 1, "title": "كوكبُنا في خطر", "summary": "شرح متحرك بـ SVG لدرس كوكبُنا في خطر للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-our-planet-in-danger.html", "video": "", "pdf": "", "notes": ["كوكب الأرض هو بيتنا المشترك الذي أنعم الله به علينا، وهو أمانةٌ في أعناقنا جميعًا.", "يواجه كوكبنا اليوم أخطارًا بيئيةً حقيقيةً معظمها بسبب سلوكيات الإنسان غير المسؤولة.", "من أبرز الأخطار: تلوّث الهواء والماء والتربة، وتراكم النفايات البلاستيكية، والإسراف في الماء والكهرباء، وقطع الأشجار.", "يؤدي التلوّث إلى ارتفاع حرارة الأرض، وتضرّر صحة الإنسان، وتهديد الكائنات الحية كالسلاحف البحرية والطيور.", "معرفة أسباب المشكلة البيئية هي الخطوة الأولى لحماية كوكبنا وبيئتنا العُمانية."], "exercises": ["اذكر ثلاثة أخطار بيئية تهدد كوكب الأرض اليوم.", "كيف تؤثر النفايات البلاستيكية المرمية على الشواطئ في الكائنات البحرية؟", "ما العلاقة بين الإسراف في الماء والكهرباء والمشكلات البيئية؟"], "levels": {"easy": [{"type": "mcq", "q": "من الأخطار التي تهدد كوكب الأرض اليوم:", "options": ["التلوّث والإسراف وقطع الأشجار", "النظافة والتشجير", "ترشيد الماء", "إعادة التدوير"], "answer": 0, "why": "التلوث والإسراف وقطع الأشجار من أبرز أخطار البيئة."}, {"type": "mcq", "q": "رمي النفايات البلاستيكية على الشواطئ يضرّ بـ:", "options": ["النجوم في السماء", "السلاحف والأسماك والبيئة البحرية", "الأقمار الصناعية", "لا يضرّ أحدًا"], "answer": 1, "why": "البلاستيك يهدد الحياة البحرية ويشوه الشواطئ."}, {"type": "mcq", "q": "الغازات المنبعثة من عوادم السيارات وحرق القمامة تسبب تلوّث:", "options": ["الأحجار فقط", "الكتب", "الهواء", "الحديد"], "answer": 2, "why": "الدخان والعوادم تلوث الهواء."}, {"type": "mcq", "q": "العضو الطبيعي الذي يُلقّب بـ«رئة الأرض» لأنه يُنقي الهواء هو:", "options": ["النفايات", "المصانع", "السيارات", "الأشجار والنباتات"], "answer": 3, "why": "الأشجار تنتج الأكسجين وتنقي الهواء."}], "medium": [{"type": "mcq", "q": "ما السبب الرئيسي وراء معظم المشكلات البيئية التي يواجهها كوكبنا اليوم؟", "options": ["السلوكيات البشرية غير المسؤولة كالتلوث والإسراف", "دوران الأرض حول الشمس", "وجود الأشجار", "نظافة الشواطئ"], "answer": 0, "why": "معظم الأخطار البيئية ناتجة عن سلوكيات الإنسان الخاطئة."}, {"type": "tfr", "q": "تتحلّل الأكياس البلاستيكية وتختفي من التربة والبحر خلال يومين فقط.", "answer": false, "reasons": ["البلاستيك مفيد للتربة", "البلاستيك يذوب فورًا", "البلاستيك يستغرق عشرات ومئات السنين ليتحلل ويظل خطرًا على الكائنات"], "reason": 2}, {"type": "essay", "q": "اذكر أنواع التلوّث الثلاثة مع مثال واحد لكل نوع.", "model": "١) تلوّث الهواء: دخان المصانع والسيارات. ٢) تلوّث الماء: رمي النفايات في البحر والأودية. ٣) تلوّث التربة: تراكم القمامة والمواد الكيميائية على الأرض."}, {"type": "tfr", "q": "قطع الأشجار بكثرة يُسهم في ارتفاع درجة حرارة الأرض وتقليل الظل والهواء النقي.", "answer": true, "reasons": ["لأن الأشجار تمتص ثاني أكسيد الكربون وتلطّف الجو وتنقي الهواء", "لأن الأشجار ترفع الحرارة", "لأن الأشجار لا تؤثر على الهواء"], "reason": 0}, {"type": "mcq", "q": "في رحلة إلى أحد الأودية العُمانية، تركت أسرة بقايا طعام وعلب بلاستيك على الأرض؛ ما الضرر المباشر لهذا السلوك؟", "options": ["تجميل الوادي", "حماية البيئة", "زيادة خصوبة التربة", "تلوّث التربة ومجرى الماء وتشويه المنظر وتأذّي الحيوانات"], "answer": 3, "why": "النفايات في الأودية تلوث المياه والتربة وتؤذي الكائنات."}, {"type": "essay", "q": "لماذا يُعدّ الإسراف في الماء خطرًا كبيرًا في بيئتنا العُمانية؟", "model": "لأن مصادر المياه العذبة محدودة وقليلة في منطقتنا، والإسراف فيها يستنزف المخزون المائي ويحرم الإنسان والنباتات والأجيال القادمة منها."}, {"type": "tfr", "q": "التلوّث البيئي يضرّ بالحيوانات والنباتات فقط ولا يؤثر على صحة الإنسان.", "answer": false, "reasons": ["البيئة منفصلة عن صحة الإنسان", "الإنسان لا يتأثر بالهواء الملوث", "التلوّث يسبب أمراضًا تنفسية وهضمية للإنسان ويؤثر على غذائه ومائه"], "reason": 2}], "hard": [{"type": "mcq", "q": "لماذا يرتبط الإسراف في استهلاك الكهرباء بالبيت بزيادة تلوّث الهواء؟", "options": ["لا توجد أي علاقة بينهما", "لأن توليد الكهرباء يستهلك وقودًا يطلق غازات عند احتراقه، فزيادة الهدر تزيد الانبعاثات", "الكهرباء تُنظف الهواء", "المصابيح تزرع الأشجار"], "answer": 1, "why": "ترشيد الكهرباء يقلل استهلاك الوقود والانبعاثات الملوثة."}, {"type": "essay", "q": "اربط بين تلوّث الشواطئ العُمانية وتهديد الكائنات البحرية النادرة مثل السلاحف في محمية رأس الجنز.", "model": "السلاحف البحرية تضع بيضها على الشواطئ وتسبح في البحر؛ فتراكم البلاستيك والنفايات يعيق حركتها وقد تبتلعه ظنًا أنه قنديل بحر، مما يهدد حياتها وبقاءها."}, {"type": "tfr", "q": "حرق النفايات في الهواء الطلق يُعدّ حلًا سليمًا للتخلص من القمامة.", "answer": false, "reasons": ["الحرق يُنظف الهواء", "حرق النفايات يطلق غازات سامة تلوّث الهواء وتؤذي الجهاز التنفسي", "الدخان مفيد للبيئة"], "reason": 1}, {"type": "mcq", "q": "أيّ سلسلة سبب ونتيجة صحيحة بيئيًا؟", "options": ["إعادة التدوير ← تراكم القمامة", "تشجير المدن ← زيادة التلوّث", "ترشيد الماء ← جفاف الأنهار", "زيادة المصانع والدخان + قطع الأشجار ← ارتفاع حرارة الأرض وتلوّث الهواء"], "answer": 3, "why": "الدخان وقطع الأشجار يرفعان التلوث وحرارة الأرض."}, {"type": "essay", "q": "ما المقصود بعبارة «كوكب الأرض بيتنا المشترك وأمانة في أعناقنا»؟", "model": "أي أن جميع البشر والكائنات يعيشون على أرض واحدة ومواردها مشتركة، وواجبنا الحفاظ عليها سليمة ونظيفة لنا وللأجيال التي ستأتي بعدنا."}, {"type": "tfr", "q": "الوعي بخطورة المشكلة البيئية هو الخطوة الأولى لتغيير سلوكنا نحو الأفضل.", "answer": true, "reasons": ["عندما يفهم الإنسان أثر أفعاله السلبية على الكوكب، يتحفّز لتعديلها وحماية البيئة", "المعرفة لا تغير السلوك", "تجاهل الأخطار أفضل"], "reason": 0}, {"type": "mcq", "q": "رأيت في حديقة عامة طفلًا يكسر أغصان شجرة صغيرة؛ ما التفسير البيئي المناسب الذي تنصحه به بلطف؟", "options": ["الشجرة لا تشعر ولا فائدة منها", "الشجرة كائن حي يعطينا الظل والهواء النقي، وكسر أغصانها يؤذيها ويحرمنا من جمالها", "اكسر المزيد منها", "الحديقة لا تهمنا"], "answer": 1, "why": "التوعية اللطيفة توضح قيمة الأشجار للبيئة."}, {"type": "essay", "q": "قارن بين مظهر وادٍ عُماني نظيف ومظهر وادٍ ملوّث بالنفايات من حيث الأثر على الإنسان والطبيعة.", "model": "الوادي النظيف ماؤه نقي، وهواؤه عليل، وتعيش فيه الطيور والنباتات بأمان، ويسعد الزوار به. أما الوادي الملوّث فتتلف مياهه، وتنتشر فيه الحشرات والأمراض، وتتأذى كائناته، وينفر الناس منه."}, {"type": "tfr", "q": "تتأثر الأجيال القادمة بسلوكياتنا البيئية اليوم سواء كانت إيجابية أم سلبية.", "answer": true, "reasons": ["سلوكنا اليوم ينتهي أثره فورًا", "كل جيل له كوكب منفصل", "لأن الموارد والبيئة التي نحفظها أو نلوثها اليوم هي التي سيرثونها غدًا"], "reason": 2}, {"type": "essay", "q": "اكتب ثلاث رسائل تحذيرية قصيرة تُعلّق على لوحة المدرسة لتوعية زملائك بالأخطار التي تهدد كوكبنا.", "model": "١) كيس بلاستيك واحد على الشاطئ قد يقتل سلحفاةً بحرية! ٢) قطرة ماء تُهدرها اليوم قد نحتاجها غدًا. ٣) حافظ على الأشجار؛ فهي رئة أرضنا ومصدر هوائنا النقي."}]}},
  {"id": "g4-social-2-u5-2", "grade": "g4", "subject": "social", "term": 2, "unit": 5, "no": 2, "title": "لِنَحْمِ كوكبَنا", "summary": "شرح متحرك بـ SVG لدرس لِنَحْمِ كوكبَنا للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-protect-our-planet.html", "video": "", "pdf": "", "notes": ["حماية كوكب الأرض مسؤولية مشتركة بين الأفراد والأسر والمدارس والدول.", "القاعدة الذهبية لإدارة النفايات (3R): التقليل من الاستهلاك، وإعادة الاستخدام، وإعادة التدوير.", "ترشيد استهلاك الماء والكهرباء والاعتماد على الطاقة النظيفة (كالطاقة الشمسية في عُمان) يحمي الموارد ويقلل التلوّث.", "زراعة الأشجار والمحافظة على المحميات الطبيعية في عُمان تحفظ التنوع الحيوي وتُلطّف المناخ.", "كل سلوك إيجابي صغير في البيت والمدرسة يصنع فرقًا كبيرًا عندما يمارسه الملايين."], "exercises": ["اشرح القاعدة الذهبية لحماية البيئة (التقليل، إعادة الاستخدام، إعادة التدوير) بمثال لكل منها.", "اذكر ثلاث طرق عملية لترشيد استهلاك الماء والكهرباء في بيتك.", "كيف تُسهم سلطنة عُمان في حماية البيئة والكائنات المهددة بالانقراض؟"], "levels": {"easy": [{"type": "mcq", "q": "فرز الورق والبلاستيك ليُعاد تصنيعها في المصانع يُسمّى:", "options": ["الحرق", "الإسراف", "التلوّث", "إعادة التدوير"], "answer": 3, "why": "إعادة التدوير تحوّل النفايات المفروزة إلى منتجات جديدة."}, {"type": "mcq", "q": "من السلوكيات الصحيحة لترشيد استهلاك الماء:", "options": ["إغلاق الصنبور أثناء تنظيف الأسنان", "ترك الصنبور مفتوحًا", "غسل السيارة بالخرطوم لساعة", "اللعب بالماء"], "answer": 0, "why": "إغلاق الصنبور يوفّر لترات كثيرة من الماء يوميًا."}, {"type": "mcq", "q": "من الأشجار المحلية المناسبة لبيئة عُمان وتتحمل الحرارة:", "options": ["أشجار القطب المتجمد", "الغاف والسدر والنخيل", "لا توجد أشجار محلية", "البلاستيك"], "answer": 1, "why": "الغاف والسدر والنخيل أشجار عُمانية أصيلة تتحمل المناخ الحار."}, {"type": "mcq", "q": "أخذ حقيبة قماشية عند التسوق بدل الأكياس البلاستيكية يُعدّ مثالًا على:", "options": ["زيادة النفايات", "التلوّث", "التقليل من البلاستيك", "الإهمال"], "answer": 2, "why": "استخدام الحقيبة القماشية يقلل استهلاك البلاستيك."}], "medium": [{"type": "mcq", "q": "أيّ مثال يوضّح الفرق بين «إعادة الاستخدام» و«إعادة التدوير»؟", "options": ["لا يوجد فرق بينهما", "كلاهما يعني حرق النفايات", "كلاهما يعني رمي النفايات في البحر", "إعادة الاستخدام: استخدام زجاجة ماء قابلة للتعبئة؛ إعادة التدوير: إرسال علب الورق للمصنع لتصنيع ورق جديد"], "answer": 3, "why": "إعادة الاستخدام تكون مباشرة، بينما إعادة التدوير تتطلب فرزًا وإعادة تصنيع."}, {"type": "tfr", "q": "الاعتماد على الطاقة الشمسية وطاقة الرياح يساعد على تقليل تلوّث الهواء.", "answer": true, "reasons": ["لأن الرياح تلوّث الجو", "لأن الطاقة الشمسية تطلق دخانًا", "لأنها مصادر نظيفة متجددة لا تطلق غازات ملوّثة للهواء"], "reason": 2}, {"type": "essay", "q": "اذكر ثلاث طرق عملية تستطيع بها حماية البيئة داخل مدرستك.", "model": "١) رمي الأوراق والعبوات في حاويات الفرز المخصصة. ٢) إغلاق صنابير المياه ومصابيح الصف عند الخروج. ٣) المشاركة في زراعة شتلات المدرسة والمحافظة عليها."}, {"type": "tfr", "q": "المحميات الطبيعية في سلطنة عُمان أُنشئت لحماية الكائنات الحية النادرة والمحافظة على التوازن البيئي.", "answer": true, "reasons": ["مثل محمية رأس الجنز للسلاحف ومحمية الكائنات الحية والفطرية للمها العربية", "المحميات تُنشأ لقطع الأشجار", "لا توجد محميات في عُمان"], "reason": 0}, {"type": "mcq", "q": "استفادَت أسرة من ضوء الشمس بفتح الستائر نهارًا بدل إشعال المصابيح؛ هذا السلوك يحقق:", "options": ["زيادة فاتورة الكهرباء", "تلوّث البيت", "ترشيد استهلاك الكهرباء وحماية البيئة", "إضاعة الطاقة"], "answer": 2, "why": "الاستفادة من الإضاءة الطبيعية توفر الكهرباء بسهولة."}, {"type": "essay", "q": "لماذا يُفضّل زراعة الأشجار العُمانية المحلية كالغاف والسدر في حملات التشجير؟", "model": "لأنها متأقلمة مع مناخ عُمان الحار، وتحتاج كميات أقل من الماء، وتوفر ظلًا كثيفًا ومأوى للطيور وتحافظ على التنوع البيئي المحلي."}, {"type": "tfr", "q": "حماية كوكب الأرض هي مسؤولية الحكومة وحدها ولا دور للأفراد والأطفال فيها.", "answer": false, "reasons": ["الأفراد لا يؤثرون على البيئة", "الأطفال لا يستطيعون المساعدة", "حماية البيئة مسؤولية مشتركة يبدأ أثرها بسلوك كل فرد وأسرة وطالب"], "reason": 2}], "hard": [{"type": "mcq", "q": "لماذا تأتي خطوة «التقليل» أولًا في القاعدة الذهبية (تقليل ← إعادة استخدام ← إعادة تدوير)؟", "options": ["لأن منع إنتاج النفاية من البداية هو الحل الأفضل والأقل استهلاكًا للطاقة والموارد", "لأن إعادة التدوير غير مفيدة", "لأنه ترتيب عشوائي", "لأن التقليل يعني عدم الشراء أبدًا"], "answer": 0, "why": "تقليل النفايات من المصدر يوفر طاقة إعادة التدوير ويحمي الموارد."}, {"type": "essay", "q": "اقترح ثلاث أفكار مبتكرة لتطبيق «إعادة الاستخدام» في صفك الدراسي.", "model": "١) الكتابة على وجهي أوراق المسودات قبل التخلص منها. ٢) تحويل علب الكرتون الفارغة لمنظمات أقلام ومجسمات تعليمية. ٣) التبرع بالكتب والقصص المقروءة لمكتبة الصف ليستفيد منها طلاب آخرون."}, {"type": "tfr", "q": "الإبلاغ السريع عن صنبور ماء يسرّب قطرات صغيرة في المدرسة سلوك بيئي مهم جدًا.", "answer": true, "reasons": ["القطرات الصغيرة لا تُهدر شيئًا", "لأن القطرات المتواصلة تُهدر عشرات اللترات من الماء العذب خلال أيام قليلة", "إصلاح التسرب غير مهم"], "reason": 1}, {"type": "mcq", "q": "تتمتع سلطنة عُمان بسطوع الشمس معظم أيام السنة؛ كيف يُعدّ ذلك ميزةً بيئيةً رائعة؟", "options": ["يزيد التلوّث فقط", "يمنع الزراعة تمامًا", "يتيح توليد كهرباء نظيفة ومتجددة عبر محطات وألواح الطاقة الشمسية وتقليل الانبعاثات", "لا فائدة بيئية منه"], "answer": 2, "why": "الطاقة الشمسية استثمار ذكي لمناخ عُمان لحماية الكوكب."}, {"type": "essay", "q": "صمّم خطةً أسبوعيةً بسيطةً لأسرتك لتقليل النفايات البلاستيكية في البيت.", "model": "١) استخدام حقائب قماشية عند التسوق. ٢) حمل زجاجات ماء قابلة لإعادة الاستخدام للمدرسة والعمل. ٣) استبدال الأكواب البلاستيكية بأكواب زجاجية أو معدنية وفرز البلاستيك المتبقي للتدوير."}, {"type": "tfr", "q": "الالتزام بقواعد الزيارة في المحميات الطبيعية (كعدم إزعاج السلاحف وعدم استخدام فلاش الكاميرا) يحمي الحياة الفطرية.", "answer": true, "reasons": ["لأن الإضاءة القوية والضوضاء تُخيف السلاحف وتمنعها من وضع بيضها بأمان", "السلاحف تحب الضوضاء والأضواء", "لا توجد قواعد للمحميات"], "reason": 0}, {"type": "mcq", "q": "أيّ موقف يُجسّد تكامل الجهود بين «الدولة» و«المواطن» في حماية البيئة العُمانية؟", "options": ["توفير البلدية لحاويات فرز ومحميات، والتزام المواطنين والطلاب بالنظافة والفرز والترشيد", "ترك الحاويات فارغة ورمي القمامة بجانبها", "اعتماد كل طرف على الآخر دون عمل", "تجاهل القوانين البيئية"], "answer": 0, "why": "تعاون الدولة والمواطنين يحقق أعلى درجات حماية البيئة."}, {"type": "essay", "q": "قارن بين الطاقة النظيفة (كالشمس والرياح) والوقود التقليدي من حيث الأثر على الهواء والاستمرارية.", "model": "الطاقة النظيفة لا تُلوّث الهواء ولا تنفد (متجددة). أما الوقود التقليدي فيُطلق غازات ملوّثة عند احتراقه وكميته محدودة قابلة للنفاد."}, {"type": "tfr", "q": "إعادة تدوير طن واحد من الورق يُسهم في إنقاذ العديد من الأشجار وتقليل استهلاك الماء والطاقة.", "answer": true, "reasons": ["إعادة التدوير تزيد قطع الأشجار", "الورق لا يُصنع من الأشجار", "لأن الورق يُصنع أصلًا من لبّ الأشجار، فإعادة تدويره تقلل الحاجة لقطع أشجار جديدة"], "reason": 2}, {"type": "essay", "q": "اكتب تعهدًا قصيرًا من ثلاث نقاط بعنوان «أنا حامي كوكبي» تلتزم به يوميًا.", "model": "١) أُغلق الصنبور والمصباح فور الانتهاء من استخدامهما. ٢) أستخدم زجاجتي الخاصة وأقلّل من البلاستيك وأفرز النفايات. ٣) أحافظ على الأشجار ونظافة مدرستي وشواطئ وطني عُمان."}]}},
  {"id": "g4-social-2-u5-3", "grade": "g4", "subject": "social", "term": 2, "unit": 5, "no": 3, "title": "قراراتي صديقة للبيئة", "summary": "شرح متحرك بـ SVG لدرس قراراتي صديقة للبيئة للصف الرابع (الهوية والمواطنة — سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.", "page": "lesson-g4-eco-friendly-decisions.html", "video": "", "pdf": "", "notes": ["القرار الصديق للبيئة هو اختيار واعٍ نتخذه في حياتنا اليومية ليقلّل الضرر على الأرض ويحفظ مواردها.", "كل يوم نتخذ قراراتٍ بسيطةً لها أثر بيئي: ماذا نشتري، كيف نستخدم الماء والكهرباء، وكيف نتخلص من النفايات، وكيف ننتقل.", "قبل اتخاذ أي قرار، أسأل نفسي: هل أحتاج هذا فعلًا؟ وهل يوجد بديل أنظف وقابل لإعادة الاستخدام؟", "من أمثلة القرارات الصديقة للبيئة: استخدام مطّارة ماء وحافظة طعام، وعدم الإسراف في الطعام، والمشي للمسافات القريبة، وإهداء الألعاب الزائدة.", "الاستمرار في اتخاذ قرارات صديقة للبيئة يصنع «مواطنًا بيئيًا مسؤولًا» يحفظ أمانة الكوكب."], "exercises": ["ما المقصود بالقرار الصديق للبيئة؟", "اذكر ثلاثة قرارات يومية صديقة للبيئة يمكنك اتخاذها في البيت والمدرسة.", "كيف يساعدك التفكير في البدائل قبل الشراء على حماية كوكب الأرض؟"], "levels": {"easy": [{"type": "mcq", "q": "الاختيار اليومي الواعي الذي يحفظ موارد الأرض ويقلل الضرر عليها يُسمّى:", "options": ["الإهمال", "الإسراف", "القرار الصديق للبيئة", "التبذير"], "answer": 2, "why": "القرار الصديق للبيئة يراعي حماية الأرض والموارد."}, {"type": "mcq", "q": "أفضل بديل لعبوات الماء البلاستيكية ذات الاستخدام الواحد في المدرسة هو:", "options": ["عدم شرب الماء", "شراء ٣ عبوات بلاستيك يوميًا", "رمي العبوات في الساحة", "مطّارة ماء متينة قابلة لإعادة التعبئة"], "answer": 3, "why": "المطّارة القابلة لإعادة التعبئة تقلل مئات العبوات سنويًا."}, {"type": "mcq", "q": "وضع مقدار الطعام الذي أستطيع أكله فقط في صحني يُعدّ:", "options": ["قرارًا صديقًا للبيئة وحفظًا للنعمة", "تبذيرًا", "تلوّثًا", "خطأً"], "answer": 0, "why": "عدم هدر الطعام سلوك ديني وبيئي رائع."}, {"type": "mcq", "q": "للمسافات القريبة والآمنة داخل الحيّ، القرار الصديق للبيئة هو:", "options": ["استخدام السيارة دائمًا", "المشي أو ركوب الدراجة", "ترك محرك السيارة يعمل بلا سبب", "إلقاء الأوراق من النافذة"], "answer": 1, "why": "المشي والدراجة لا يطلقان عوادم ملوّثة ويفيدان الصحة."}], "medium": [{"type": "mcq", "q": "أمامك خياران في نهاية العام الدراسي للكتب والدفاتر السليمة: أي قرار هو الصديق للبيئة؟", "options": ["تمزيقها ورميها في الشارع", "حرقها في الحديقة", "إهداؤها أو تسليمها لمبادرة إعادة التدوير في المدرسة", "تركها في الممر"], "answer": 2, "why": "إعادة الاستخدام أو التدوير تحفظ الورق والأشجار."}, {"type": "tfr", "q": "القرارات البيئية المهمة يتخذها الكبار فقط، ولا تؤثر قرارات الأطفال اليومية على البيئة.", "answer": false, "reasons": ["قرارات الصغار بلا أثر", "الأطفال لا يتخذون قرارات", "قرارات الأطفال في الماء والورق والطعام والبلاستيك تتراكم وتصنع فرقًا كبيرًا"], "reason": 2}, {"type": "essay", "q": "اذكر ثلاثة قرارات صديقة للبيئة تتخذها أسرتك عند الذهاب في رحلة إلى أحد الأودية أو الشواطئ العُمانية.", "model": "١) إحضار أكياس لجمع جميع النفايات وأخذها معنا للحاوية. ٢) استخدام أطباق وأكواب قابلة لإعادة الاستخدام. ٣) عدم إشعال النار قرب الأشجار وعدم إزعاج الكائنات الحية."}, {"type": "tfr", "q": "التبرع بالألعاب والملابس النظيفة التي لم نعد نحتاجها يُعدّ قرارًا إنسانيًا وصديقًا للبيئة في الوقت نفسه.", "answer": true, "reasons": ["لأنه يُسعد المحتاجين ويمنع تحوّل الأشياء السليمة إلى نفايات", "لأنه يزيد القمامة", "لأنه يضر البيئة"], "reason": 0}, {"type": "mcq", "q": "اشترى طالب دفترًا جديدًا بينما لديه دفتران شبه فارغين من الفصل السابق؛ أي سؤال من «ميزان القرار البيئي» نسي أن يسأله؟", "options": ["ما لون الغلاف؟", "هل أحتاج هذا الشيء فعلًا؟", "كم عدد المتاجر؟", "هل هو ثقيل؟"], "answer": 1, "why": "التأكد من الحاجة الفعلية يمنع الاستهلاك غير الضروري."}, {"type": "essay", "q": "كيف تحوّل حقيبتك المدرسية إلى «حقيبة صديقة للبيئة»؟", "model": "بوضع مطّارة ماء وحافظة طعام قابلة لإعادة الاستخدام، والمحافظة على كتبي ودفاتري وأقلامي حتى نهاية العام، واستخدام أوراقي بحرص دون تمزيق."}, {"type": "tfr", "q": "شراء المنتجات الزراعية العُمانية المحلية الطازجة أقل ضررًا بالبيئة من المنتجات المستوردة لمسافات بعيدة جدًا.", "answer": true, "reasons": ["النقل لا يستهلك وقودًا", "المنتجات البعيدة أقل تلوثًا دائمًا", "لأنها تحتاج نقلًا وشحنًا أقل، مما يقلل استهلاك الوقود وتلوّث الهواء ويدعم المزارع المحلي"], "reason": 2}], "hard": [{"type": "mcq", "q": "إذا استخدم كل طالب من طلاب صفّك (٢٥ طالبًا) مطّارة ماء بدلًا من شراء عبوة بلاستيك واحدة يوميًا لمدة ٢٠ يومًا دراسيًا في الشهر، فكم عبوة بلاستيكية أنقذتم البيئة منها في شهر واحد؟", "options": ["٢٥ عبوة", "١٠٠ عبوة", "٥٠ عبوة", "٥٠٠ عبوة بلاستيكية!"], "answer": 3, "why": "٢٥ طالبًا × ٢٠ يومًا = ٥٠٠ عبوة بلاستيكية في شهر واحد فقط!"}, {"type": "essay", "q": "وضّح بمثال كيف يمكن لقرار بيئي واحد يتخذه طالب في الصف الرابع أن يُلهم أسرته كلها.", "model": "إذا قرّر الطالب وضع صندوق صغير في المطبخ لفرز العبوات الورقية والبلاستيكية والتزم به يوميًا، فستلاحظ أسرته سهولة الفكرة وتشاركه الفرز فيتحوّل إلى عادة أسرية دائمة."}, {"type": "tfr", "q": "القرار الصديق للبيئة يعني دائمًا دفع مالٍ أكثر أو التضحية براحتنا.", "answer": false, "reasons": ["حماية البيئة مكلفة دائمًا", "كثير من القرارات البيئية توفّر المال (كترشيد الكهرباء والماء وعدم هدر الطعام وإعادة الاستخدام)", "الترشيد يزيد المصاريف"], "reason": 1}, {"type": "mcq", "q": "أكمل تسلسل دروس الوحدة الخامسة (كوكبُنا أمانة) بترتيبها المنطقي:", "options": ["أهمل البيئة ← أتحدث عنها ← أنساها", "أعرف الأخطار (كوكبنا في خطر) ← أتعلّم الحلول (لنحمِ كوكبنا) ← أُطبّقها يوميًا (قراراتي صديقة للبيئة)", "أشتري كثيرًا ← أرمي ← أندم", "لا علاقة بين الدروس الثلاثة"], "answer": 1, "why": "تبدأ الوحدة بالوعي بالخطر، ثم معرفة الحلول، ثم تحويلها لقرارات يومية."}, {"type": "essay", "q": "قارن بين قرارين عند تنظيم حفلة نجاح صغيرة في البيت: قرار غير صديق للبيئة وقرار صديق للبيئة.", "model": "غير صديق للبيئة: استخدام أطباق وأكواب بلاستيكية تُرمى، وبالونات كثيرة، وتحضير طعام زائد يُرمى. صديق للبيئة: استخدام أطباق المنزل القابلة للغسل، وزينة ورقية يُعاد استخدامها، وطعام بقدر الضيوف."}, {"type": "tfr", "q": "إصلاح لعبة أو حقيبة ممزقة قليلًا بدل رميها وشراء جديدة فورًا يُعدّ قرارًا صديقًا للبيئة.", "answer": true, "reasons": ["لأن الإصلاح يطيل عمر الأشياء ويقلل النفايات ويوفر المال والموارد", "الإصلاح يضر البيئة", "يجب رمي أي شيء به خدش بسيط"], "reason": 0}, {"type": "mcq", "q": "أيّ عبارة تصف «المواطن البيئي المسؤول» بدقة؟", "options": ["شخص يهتم ببيته ويلوّث الشارع", "شخص يحفظ شعارات البيئة دون تطبيقها", "شخص يرمي النفايات إذا لم يره أحد", "شخص يراعي أثر قراراته اليومية على الأرض، ويلتزم بالترشيد والنظافة، ويُلهم غيره"], "answer": 3, "why": "المواطنة البيئية الحقيقية تظهر في السلوك اليومي المستمر."}, {"type": "essay", "q": "لماذا يُعدّ «تجنّب هدر الطعام» قرارًا أخلاقيًا وبيئيًا واقتصاديًا في آنٍ واحد؟", "model": "أخلاقيًا: شكر لنعمة الله واحترام للمحتاجين. بيئيًا: يقلل النفايات والمياه والطاقة المستهلكة في إنتاجه. اقتصاديًا: يوفّر مال الأسرة ويمنع التبذير."}, {"type": "tfr", "q": "الالتزام بقرارات صديقة للبيئة حتى عندما لا يراقبنا أحد هو دليل على حفظ الأمانة.", "answer": true, "reasons": ["لا حاجة للالتزام وحدنا", "النظافة تكون أمام المعلم فقط", "لأن الأمانة الحقيقية نابعة من الضمير والوعي لا من مراقبة الآخرين"], "reason": 2}, {"type": "essay", "q": "اكتب خطة «يومي الصديق للبيئة» تتضمن ٤ قرارات إيجابية من الصباح حتى المساء.", "model": "صباحًا: أغلق الصنبور أثناء الوضوء وأحمل مطّارتي للمدرسة. ظهرًا: أفرز نفاياتي ولا أهدر طعامي. عصرًا: أستفيد من ضوء الشمس وأغلق المصابيح غير المستخدمة. مساءً: أسقي نباتات البيت بماء موفّر وأرتب كتبي بحرص."}]}}
);
